finance_tax_correction_lines r)),('finance_tax_deadline_rules',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_deadline_rules r)),('finance_tax_document_corrections',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r)-array['direct_money_receipt_id','direct_source_line_id'] order by (to_jsonb(r)-array['direct_money_receipt_id','direct_source_line_id'])::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_document_corrections r)),('finance_tax_filing_allocations',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_filing_allocations r)),('finance_tax_filing_audit',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_filing_audit r)),('finance_tax_filings',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_filings r)),('finance_tax_invoice_audit_events',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_invoice_audit_events r)),('finance_tax_invoice_items',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r)-array['direct_money_receipt_id','direct_source_line_id'] order by (to_jsonb(r)-array['direct_money_receipt_id','direct_source_line_id'])::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_invoice_items r)),('finance_tax_invoice_source_coverages',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r)-array['direct_money_receipt_id','direct_source_line_id'] order by (to_jsonb(r)-array['direct_money_receipt_id','direct_source_line_id'])::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_invoice_source_coverages r)),('finance_tax_invoices',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r)-array['direct_money_receipt_id','direct_source_line_id'] order by (to_jsonb(r)-array['direct_money_receipt_id','direct_source_line_id'])::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_invoices r)),('finance_tax_periods',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_periods r)),('finance_tax_point_events',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r)-array['direct_money_receipt_id','direct_source_line_id'] order by (to_jsonb(r)-array['direct_money_receipt_id','direct_source_line_id'])::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_point_events r)),('finance_tax_position_audit',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_position_audit r)),('finance_tax_position_facts',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_position_facts r)),('finance_tax_remittance_audit',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_remittance_audit r)),('finance_tax_remittances',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_remittances r)),('finance_tax_source_revisions',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_tax_source_revisions r)),('finance_treasury_account_authorities',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_treasury_account_authorities r)),('finance_treasury_authority_audit',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_treasury_authority_audit r)),('finance_vp_revenue_distribution_audit',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_vp_revenue_distribution_audit r)),('finance_vp_revenue_distributions',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.finance_vp_revenue_distributions r)),('user_profiles',(select jsonb_build_object('count',count(*),'sha256',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),'[]')::text,'UTF8')),'hex')) from public.user_profiles r))) data(name,hash)) r), now_functions as (select item.value v from state,jsonb_array_elements(state.value->'functions') item),
 now_catalog as (select item.value v from state,jsonb_array_elements(state.value->'catalog') item),
 expected_functions as (select value v from jsonb_array_elements('[{"acl":"{postgres=X/postgres}","name":"assert_finance_document_route","owner":"postgres","config":["search_path=public"],"signature":"assert_finance_document_route(uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.assert_finance_document_route(p_payment_id uuid, p_route text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare d jsonb;\nbegin\n  perform 1 from public.finance_payments where id=p_payment_id for update;\n  d:=public.finance_payment_document_decision(p_payment_id);\n  if p_route=''receipt'' and d->>''decision'' in (''receipt_only'',''receipt_completion_only'') and d->>''combined_id'' is null then return; end if;\n  if p_route=''tax_invoice'' and d->>''decision''=''tax_invoice_completion_only'' and d->>''combined_id'' is null then return; end if;\n  raise exception using message=''DOCUMENT_ROUTE_''||upper(d->>''decision'');\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"build_finance_document_tax_source","owner":"postgres","config":["search_path=public"],"signature":"build_finance_document_tax_source(uuid)","definition":"CREATE OR REPLACE FUNCTION public.build_finance_document_tax_source(p_payment_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare source jsonb; identity jsonb; profile public.finance_customer_tax_profiles%rowtype; state text; client uuid;\nbegin\n  source:=public.document_tax_source_pre042(p_payment_id);\n  client:=(source #>> ''{customer,id}'')::uuid;\n  perform 1 from public.clients where id=client for share;\n  identity:=public.finance_customer_tax_identity(client);\n  select * into profile from public.finance_customer_tax_profiles where client_id=client for share;\n  state:=case when profile.client_id is null then ''missing''\n    when identity is null or identity is distinct from profile.identity_snapshot_json then ''stale''\n    when profile.verified_at is null then ''unverified'' else ''verified'' end;\n  -- Separate reviewed tax identity, never a rewrite of the issued Invoice or\n  -- standalone Receipt customer. Existing Issue stale-source checks still apply.\n  return source||jsonb_build_object(''buyer_tax_profile'',jsonb_build_object(''schema_version'',1,''status'',state,\n    ''profile'',case when profile.client_id is not null then to_jsonb(profile) end),\n    ''customer'',case when state=''verified'' then profile.identity_snapshot_json||jsonb_build_object(\n      ''branch'',case when profile.branch_type=''head_office'' then ''head office'' end) else source->''customer'' end);\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"build_finance_receipt_source","owner":"postgres","config":["search_path=public"],"signature":"build_finance_receipt_source(uuid)","definition":"CREATE OR REPLACE FUNCTION public.build_finance_receipt_source(p_payment_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_payment public.finance_payments%rowtype;\n  v_company jsonb;\n  v_seller jsonb;\n  v_bank jsonb;\n  v_customer jsonb;\n  v_candidate_customer jsonb;\n  v_allocation record;\n  v_invoice public.finance_invoices%rowtype;\n  v_invoices jsonb := ''[]''::jsonb;\n  v_cash numeric := 0;\n  v_wht numeric := 0;\n  v_description text;\nbegin\n  select * into v_payment from public.finance_payments where id = p_payment_id for update;\n  if not found or v_payment.status <> ''confirmed'' then raise exception ''RECEIPT_CONFIRMED_PAYMENT_REQUIRED''; end if;\n  if v_payment.received_on is null or v_payment.payment_method is null or v_payment.settlement_amount <= 0\n  then raise exception ''RECEIPT_PAYMENT_EVIDENCE_REQUIRED''; end if;\n  select to_jsonb(company) into v_company from public.finance_company_profiles company where id = ''default'' for share;\n  v_seller := jsonb_build_object(\n    ''company_name_th'',v_company->>''company_name_th'',''company_name_en'',v_company->>''company_name_en'',\n    ''tax_id'',v_company->>''tax_id'',''address_th'',v_company->>''address_th'',''address_en'',v_company->>''address_en'',\n    ''branch_label_th'',coalesce(nullif(btrim(v_company->>''branch_th''),''''),nullif(btrim(v_company->>''branch_label''),''''),''สำนักงานใหญ่''),\n    ''branch_label_en'',coalesce(nullif(btrim(v_company->>''branch_en''),''''),''Head Office''),\n    ''phone'',v_company->>''phone'',''email'',v_company->>''email'',''website'',v_company->>''website'',\n    ''logo_asset'',public.document_logo_evidence(v_company->>''logo_storage_path'')\n  );\n  if nullif(btrim(v_seller->>''company_name_th''),'''') is null\n    or nullif(btrim(v_seller->>''address_th''),'''') is null\n    or nullif(btrim(v_seller->>''tax_id''),'''') is null\n  then raise exception ''RECEIPT_SELLER_IDENTITY_REQUIRED''; end if;\n  if v_payment.receiving_bank_account_id is not null then\n    select jsonb_build_object(''id'',bank.id,''short_name'',bank.short_name,''bank_name'',bank.bank_name,\n      ''account_name'',bank.account_name,''account_number'',bank.account_number,''branch_name'',to_jsonb(bank)->>''branch_name'')\n    into v_bank from public.finance_bank_accounts bank where id = v_payment.receiving_bank_account_id for share;\n    if v_bank is null or nullif(btrim(v_bank->>''bank_name''),'''') is null\n      or nullif(btrim(v_bank->>''account_name''),'''') is null or nullif(btrim(v_bank->>''account_number''),'''') is null\n    then raise exception ''RECEIPT_RECEIVING_ACCOUNT_REQUIRED''; end if;\n  end if;\n  if v_payment.payment_method = ''bank_transfer'' and v_bank is null\n    and nullif(btrim(v_payment.receiving_account_reference),'''') is null\n  then raise exception ''RECEIPT_RECEIVING_ACCOUNT_REQUIRED''; end if;\n  perform 1 from public.finance_invoices where id in (\n    select invoice_id from public.finance_payment_effective_invoice_allocations where payment_id = p_payment_id\n  ) order by id for share;\n  for v_allocation in select * from public.finance_payment_effective_invoice_allocations\n    where payment_id = p_payment_id order by invoice_id\n  loop\n    select * into strict v_invoice from public.finance_invoices where id = v_allocation.invoice_id;\n    if v_invoice.document_status <> ''issued'' or v_invoice.client_id <> v_payment.client_id\n      or v_invoice.currency <> v_payment.currency\n      or coalesce(v_invoice.issued_snapshot_json->>''schema_version'','''') not in (''1'',''2'')\n      or (v_invoice.issued_snapshot_json #>> ''{invoice,id}'') is distinct from v_invoice.id::text\n      or (v_invoice.issued_snapshot_json #>> ''{invoice,invoice_no}'') is distinct from v_invoice.invoice_no\n      or (v_invoice.issued_snapshot_json #>> ''{invoice,document_status}'') is distinct from ''issued''\n      or (v_invoice.issued_snapshot_json #>> ''{invoice,currency}'') is distinct from v_payment.currency\n      or nullif(v_invoice.issued_snapshot_json #>> ''{invoice,issued_at}'','''') is null\n      or nullif(v_invoice.invoice_no,'''') is null\n      or jsonb_typeof(v_invoice.issued_snapshot_json->''items'') is distinct from ''array''\n    then raise exception ''RECEIPT_FROZEN_INVOICE_EVIDENCE_REQUIRED''; end if;\n    -- V1 snapshots have normalized customer fields; V2 preserves the Invoice\n    -- row and its original customer snapshot. Never consult mutable Client data.\n    v_candidate_customer := jsonb_build_object(\n      ''id'',v_payment.client_id,\n      ''name'',coalesce(v_invoice.issued_snapshot_json #>> ''{invoice,customer_name}'',\n        v_invoice.issued_snapshot_json #>> ''{customer,name}'',v_invoice.issued_snapshot_json #>> ''{customer,client_display_name}''),\n      ''tax_id'',coalesce(v_invoice.issued_snapshot_json #>> ''{invoice,customer_tax_id}'',v_invoice.issued_snapshot_json #>> ''{customer,tax_id}''),\n      ''address'',coalesce(v_invoice.issued_snapshot_json #>> ''{invoice,customer_billing_address}'',\n        v_invoice.issued_snapshot_json #>> ''{customer,billing_address}'',v_invoice.issued_snapshot_json #>> ''{customer,address}''),\n      ''branch'',coalesce(v_invoice.issued_snapshot_json #>> ''{invoice,customer_branch}'',\n        v_invoice.issued_snapshot_json #>> ''{customer,branch}'',v_invoice.issued_snapshot_json #>> ''{customer,branch_label}'')\n    );\n    if nullif(btrim(v_candidate_customer->>''name''),'''') is null then raise exception ''RECEIPT_CUSTOMER_IDENTITY_REQUIRED''; end if;\n    if v_customer is not null and v_customer <> v_candidate_customer then raise exception ''RECEIPT_CUSTOMER_EVIDENCE_CONFLICT''; end if;\n    v_customer := v_candidate_customer;\n    select string_agg(coalesce(item->>''description'',item #>> ''{invoice_item,description}''),''; '' order by ordinal)\n      into v_description from jsonb_array_elements(v_invoice.issued_snapshot_json->''items'') with ordinality as entries(item,ordinal);\n    if nullif(btrim(v_description),'''') is null then raise exception ''RECEIPT_FROZEN_INVOICE_EVIDENCE_REQUIRED''; end if;\n    if v_allocation.effective_cash_allocated < 0 or v_allocation.effective_wht_credit_allocated < 0\n      or v_allocation.effective_settlement_total <= 0\n      or v_allocation.effective_settlement_total <> v_allocation.effective_cash_allocated + v_allocation.effective_wht_credit_allocated\n    then raise exception ''RECEIPT_ALLOCATION_MISMATCH''; end if;\n    v_cash := v_cash + v_allocation.effective_cash_allocated;\n    v_wht := v_wht + v_allocation.effective_wht_credit_allocated;\n    v_invoices := v_invoices || jsonb_build_array(jsonb_build_object(\n      ''invoice_id'',v_invoice.id,''invoice_no'',v_invoice.invoice_no,''currency'',v_invoice.currency,\n      ''description'',v_description,''matter'',v_invoice.issued_snapshot_json->''matter'',\n      ''cash_allocated'',v_allocation.effective_cash_allocated,''wht_allocated'',v_allocation.effective_wht_credit_allocated,\n      ''settlement_allocated'',v_allocation.effective_settlement_total,\n      ''invoice_snapshot_schema_version'',v_invoice.issued_snapshot_json->''schema_version'',\n      ''invoice_issued_at'',v_invoice.issued_snapshot_json #> ''{invoice,issued_at}''\n    ));\n  end loop;\n  if jsonb_array_length(v_invoices) = 0 or v_cash <> v_payment.cash_amount or v_wht <> v_payment.wht_amount\n  then raise exception ''RECEIPT_ALLOCATION_MISMATCH''; end if;\n  return jsonb_build_object(''schema_version'',2,''document_kind'',''receipt'',''seller'',v_seller,''customer'',v_customer,\n    ''payment'',jsonb_build_object(''id'',v_payment.id,''internal_reference'',v_payment.internal_reference,\n      ''received_on'',v_payment.received_on,''payment_method'',v_payment.payment_method,\n      ''receiving_bank_account'',v_bank,''receiving_account_reference'',v_payment.receiving_account_reference,\n      ''external_transaction_reference'',v_payment.external_transaction_reference,''payer_name'',v_payment.payer_name,\n      ''cash_amount'',v_payment.cash_amount,''wht_amount'',v_payment.wht_amount,\n      ''settlement_amount'',v_payment.settlement_amount,''currency'',v_payment.currency),\n    ''invoices'',v_invoices,''structured_wht_components'',coalesce((select jsonb_agg(jsonb_build_object(\n      ''id'',component.id,''invoice_id'',component.invoice_id,''invoice_item_id'',component.invoice_item_id,\n      ''calculation_rule'',component.calculation_rule,''base_amount'',component.base_amount,\n      ''rate_percent'',component.rate_percent,''calculated_wht_amount'',component.calculated_wht_amount,\n      ''basis_snapshot_json'',component.basis_snapshot_json) order by component.id)\n      from public.finance_payment_wht_components component where payment_id = p_payment_id),''[]''::jsonb));\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"build_finance_tax_invoice_source","owner":"postgres","config":["search_path=public"],"signature":"build_finance_tax_invoice_source(uuid)","definition":"CREATE OR REPLACE FUNCTION public.build_finance_tax_invoice_source(p_payment_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin return public.build_finance_document_tax_source(p_payment_id); end;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"calculate_finance_billable_charge_amounts","owner":"postgres","config":["search_path=public"],"signature":"calculate_finance_billable_charge_amounts(numeric,numeric,text,numeric)","definition":"CREATE OR REPLACE FUNCTION public.calculate_finance_billable_charge_amounts(p_quantity numeric, p_unit_rate numeric, p_price_tax_mode text, p_vat_rate numeric)\n RETURNS TABLE(vat_applicable boolean, amount_before_vat numeric, vat_amount numeric, total_amount numeric)\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_mode text := lower(btrim(coalesce(p_price_tax_mode, '''')));\n  v_entered_total numeric(14, 2);\n  v_before_vat numeric(14, 2);\n  v_vat numeric(14, 2);\nbegin\n  if p_quantity is null or p_quantity <= 0 or p_quantity <> round(p_quantity, 4) then\n    raise exception ''Billable Charge quantity must be positive with no more than four decimal places'';\n  end if;\n  if p_unit_rate is null or p_unit_rate < 0 or p_unit_rate <> round(p_unit_rate, 2) then\n    raise exception ''Billable Charge unit rate must be non-negative with no more than two decimal places'';\n  end if;\n  if v_mode not in (''non_vat'', ''vat_exclusive'', ''vat_inclusive'') then\n    raise exception ''Billable Charge price tax mode is invalid'';\n  end if;\n  if p_vat_rate is null or p_vat_rate < 0 or p_vat_rate <> round(p_vat_rate, 4) then\n    raise exception ''Billable Charge VAT rate must be non-negative with no more than four decimal places'';\n  end if;\n  if v_mode = ''non_vat'' and p_vat_rate <> 0 then\n    raise exception ''Non-VAT Billable Charge must use a zero VAT rate'';\n  end if;\n\n  v_entered_total := round(p_quantity * p_unit_rate, 2);\n  v_before_vat := case\n    when v_mode = ''vat_inclusive''\n      then round(v_entered_total / (1 + p_vat_rate / 100), 2)\n    else v_entered_total\n  end;\n  v_vat := case\n    when v_mode = ''non_vat'' then 0\n    when v_mode = ''vat_inclusive'' then v_entered_total - v_before_vat\n    else round(v_before_vat * p_vat_rate / 100, 2)\n  end;\n\n  return query select\n    v_mode <> ''non_vat'',\n    v_before_vat,\n    v_vat,\n    case when v_mode = ''vat_inclusive'' then v_entered_total else v_before_vat + v_vat end;\nend;\n$function$\n","anon_execute":false,"service_execute":true,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"cancel_finance_combined_document_draft","owner":"postgres","config":["search_path=public"],"signature":"cancel_finance_combined_document_draft(uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.cancel_finance_combined_document_draft(p_combined_id uuid, p_reason text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare c public.finance_combined_documents%rowtype;\nbegin\n  if not public.current_user_can_manage_combined_documents() then raise exception ''DOCUMENT_PERMISSION_DENIED''; end if;\n  perform 1 from public.finance_payments where id=(select payment_id from public.finance_combined_documents where id=p_combined_id) for update;\n  select * into strict c from public.finance_combined_documents where id=p_combined_id for update;\n  if c.status=''cancelled'' then return c.id; end if;\n  if c.status<>''draft'' then raise exception ''DOCUMENT_CORRECTION_WORKFLOW_REQUIRED''; end if;\n  perform public.receipt_cancel_pre040(c.receipt_id,p_reason);\n  perform public.tax_cancel_pre040(c.tax_invoice_id,p_reason);\n  update public.finance_combined_documents set status=''cancelled'',cancel_reason=btrim(p_reason),updated_at=clock_timestamp() where id=c.id;\n  insert into public.finance_combined_document_audit_events(combined_document_id,event_type,event_payload_json,actor_user_id)\n  values(c.id,''cancelled'',jsonb_build_object(''reason'',btrim(p_reason)),auth.uid());\n  return c.id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"cancel_finance_receipt_draft","owner":"postgres","config":["search_path=public"],"signature":"cancel_finance_receipt_draft(uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.cancel_finance_receipt_draft(p_receipt_id uuid, p_reason text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_payment_id uuid; v_receipt public.finance_receipts%rowtype;\nbegin\n  if not public.current_user_can_manage_finance_receipts() then raise exception ''RECEIPT_PERMISSION_DENIED''; end if;\n  if nullif(btrim(p_reason),'''') is null or length(p_reason) > 2000 then raise exception ''RECEIPT_REASON_REQUIRED''; end if;\n  select payment_id into v_payment_id from public.finance_receipts where id = p_receipt_id;\n  if not found then raise exception ''RECEIPT_NOT_FOUND''; end if;\n  perform 1 from public.finance_payments where id = v_payment_id for update;\n  select * into v_receipt from public.finance_receipts where id = p_receipt_id for update;\n  if v_receipt.combined_document_id is not null then raise exception ''DOCUMENT_USE_COMBINED_WORKFLOW''; end if;\n  if v_receipt.status = ''cancelled'' then return p_receipt_id; end if;\n  if v_receipt.status <> ''draft'' then raise exception ''RECEIPT_DRAFT_REQUIRED''; end if;\n  update public.finance_receipts set status = ''cancelled'',cancelled_at = now(),cancelled_by_user_id = auth.uid(),\n    cancel_reason = btrim(p_reason),updated_at = now() where id = p_receipt_id;\n  perform public.record_finance_receipt_audit(p_receipt_id,''cancelled'',jsonb_build_object(''reason'',btrim(p_reason),''payment_changed'',false));\n  return p_receipt_id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"cancel_finance_tax_invoice_draft","owner":"postgres","config":["search_path=public"],"signature":"cancel_finance_tax_invoice_draft(uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.cancel_finance_tax_invoice_draft(p_tax_invoice_id uuid, p_reason text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare t public.finance_tax_invoices%rowtype; pid uuid;\nbegin\n  if not public.current_user_can_manage_finance_tax_invoices() then raise exception ''TAX_INVOICE_PERMISSION_DENIED''; end if;\n  if nullif(btrim(p_reason),'''') is null or length(p_reason)>2000 then raise exception ''TAX_INVOICE_REASON_REQUIRED''; end if;\n  select payment_id into pid from public.finance_tax_invoices where id=p_tax_invoice_id;\n  perform 1 from public.finance_payments where id=pid for update;\n  select * into t from public.finance_tax_invoices where id=p_tax_invoice_id for update;\n  if t.combined_document_id is not null then raise exception ''DOCUMENT_USE_COMBINED_WORKFLOW''; end if;\n  if not found then raise exception ''TAX_INVOICE_NOT_FOUND''; end if;\n  if t.status=''cancelled'' then return t.id; end if;\n  if t.status<>''draft'' then raise exception ''TAX_INVOICE_DRAFT_REQUIRED''; end if;\n  update public.finance_tax_invoice_source_coverages set status=''released'' where tax_invoice_id=t.id;\n  update public.finance_tax_invoices set status=''cancelled'',cancelled_at=now(),cancelled_by_user_id=auth.uid(),cancel_reason=btrim(p_reason),updated_at=now() where id=t.id;\n  perform public.record_finance_tax_invoice_audit(t.id,''cancelled'',jsonb_build_object(''reason'',btrim(p_reason),''coverage_released'',true));\n  return t.id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"create_finance_combined_document_draft","owner":"postgres","config":["search_path=public"],"signature":"create_finance_combined_document_draft(uuid,boolean,boolean)","definition":"CREATE OR REPLACE FUNCTION public.create_finance_combined_document_draft(p_payment_id uuid, p_external_receipt_checked boolean, p_external_tax_checked boolean)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare d jsonb; v_id uuid:=gen_random_uuid(); rid uuid; tid uuid; source jsonb; day date:=(now() at time zone ''Asia/Bangkok'')::date;\nbegin\n  if not public.current_user_can_manage_combined_documents() then raise exception ''DOCUMENT_PERMISSION_DENIED''; end if;\n  perform 1 from public.finance_payments where finance_payments.id=p_payment_id for update;\n  select c.id into rid from public.finance_combined_documents c where c.payment_id=p_payment_id and status in (''draft'',''issued'');\n  if found then return rid; end if;\n  d:=public.finance_payment_document_decision(p_payment_id);\n  if d->>''decision''<>''combined_receipt_tax_invoice'' then raise exception using message=''DOCUMENT_ROUTE_''||upper(d->>''decision''); end if;\n  if d->>''receipt_id'' is not null or d->>''tax_invoice_id'' is not null then raise exception ''DOCUMENT_EXISTING_STANDALONE_DRAFT''; end if;\n  if p_external_receipt_checked is distinct from true or p_external_tax_checked is distinct from true then raise exception ''DOCUMENT_EXTERNAL_CHECK_REQUIRED''; end if;\n  rid:=public.receipt_create_pre040(p_payment_id,true);\n  tid:=public.prepare_finance_document_tax_draft(p_payment_id);\n  select source_snapshot_json into source from public.finance_tax_invoices where finance_tax_invoices.id=tid;\n  insert into public.finance_combined_documents(id,payment_id,receipt_id,tax_invoice_id,issue_date,source_snapshot_json,draft_snapshot_json,external_receipt_checked,created_by_user_id)\n  values(v_id,p_payment_id,rid,tid,day,source,public.finance_tax_invoice_draft_snapshot(source,''{}'',day),true,auth.uid());\n  update public.finance_receipts set combined_document_id=v_id where finance_receipts.id=rid;\n  update public.finance_tax_invoices set combined_document_id=v_id where finance_tax_invoices.id=tid;\n  insert into public.finance_combined_document_audit_events(combined_document_id,event_type,event_payload_json,actor_user_id)\n  values(v_id,''draft_created'',jsonb_build_object(''external_receipt_checked'',true,''external_tax_checked'',true,''number_allocated'',false),auth.uid());\n  return v_id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"create_finance_receipt_draft_from_payment","owner":"postgres","config":["search_path=public"],"signature":"create_finance_receipt_draft_from_payment(uuid,boolean)","definition":"CREATE OR REPLACE FUNCTION public.create_finance_receipt_draft_from_payment(p_payment_id uuid, p_external_receipt_checked boolean DEFAULT false)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_payment public.finance_payments%rowtype;\n  v_id uuid;\n  v_predecessor uuid;\n  v_snapshot jsonb;\nbegin\n  if not public.current_user_can_manage_finance_receipts() then raise exception ''RECEIPT_PERMISSION_DENIED''; end if;\n  select * into v_payment from public.finance_payments where id = p_payment_id for update;\n  if not found or v_payment.status <> ''confirmed'' then raise exception ''RECEIPT_CONFIRMED_PAYMENT_REQUIRED''; end if;\n  select id into v_id from public.finance_receipts where payment_id = p_payment_id and status in (''draft'',''issued'');\n  if v_id is not null then return v_id; end if;\n  perform public.assert_finance_document_route(p_payment_id,''receipt'');\n  if p_external_receipt_checked is distinct from true then raise exception ''RECEIPT_EXTERNAL_COVERAGE_ACK_REQUIRED''; end if;\n  select id into v_predecessor from public.finance_receipts where payment_id = p_payment_id and status = ''voided''\n    order by issued_at desc,id desc limit 1;\n  v_snapshot := public.build_finance_receipt_source(p_payment_id);\n  insert into public.finance_receipts(payment_id,client_id,receipt_date,currency,cash_amount,wht_amount,\n    draft_snapshot_json,replaces_receipt_id,external_receipt_checked_at,external_receipt_checked_by_user_id,created_by_user_id)\n  values (p_payment_id,v_payment.client_id,v_payment.received_on,v_payment.currency,v_payment.cash_amount,v_payment.wht_amount,\n    v_snapshot,v_predecessor,now(),auth.uid(),auth.uid()) returning id into v_id;\n  perform public.record_finance_receipt_audit(v_id,''draft_created'',jsonb_build_object(\n    ''payment_id'',p_payment_id,''external_receipt_checked'',true,''replaces_receipt_id'',v_predecessor));\n  return v_id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"create_finance_tax_correction_draft","owner":"postgres","config":["search_path=public"],"signature":"create_finance_tax_correction_draft(uuid,uuid,uuid,text,text,text,text,date,date,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.create_finance_tax_correction_draft(p_request_id uuid, p_tax_invoice_id uuid, p_combined_id uuid, p_mode text, p_reason text, p_legal_basis text, p_evidence_reference text, p_issue_date date, p_adjustment_date date, p_lines jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare src jsonb; req jsonb; draft jsonb; prior public.finance_tax_document_corrections%rowtype; cid uuid:=gen_random_uuid();\n line jsonb; original public.finance_tax_invoice_items%rowtype; delta numeric; dv numeric; pb numeric; pv numeric;\n lines jsonb:=''[]''; buyer jsonb; customer jsonb; sign integer; source_id uuid; totals jsonb;\nbegin\n if public.tax_correction_authorized(p_combined_id is not null,''manage'') is distinct from true then raise exception ''TAX_CORRECTION_PERMISSION_DENIED''; end if;\n if p_request_id is null then raise exception ''TAX_CORRECTION_REQUEST_REQUIRED''; end if;\n perform 1 from public.finance_tax_invoices where id=p_tax_invoice_id for update;\n req:=jsonb_build_object(''tax'',p_tax_invoice_id,''combined'',p_combined_id,''mode'',p_mode,''reason'',p_reason,''basis'',p_legal_basis,\n   ''evidence'',p_evidence_reference,''issue_date'',p_issue_date,''adjustment_date'',p_adjustment_date,''lines'',p_lines);\n select * into prior from public.finance_tax_document_corrections where request_id=p_request_id;\n if found then if prior.request_json is distinct from req then raise exception ''TAX_CORRECTION_IDEMPOTENCY_CONFLICT''; end if; return prior.id; end if;\n src:=public.tax_correction_source(p_tax_invoice_id,p_combined_id); source_id:=(src->>''source_correction_id'')::uuid;\n if p_mode is null or p_mode not in (''credit_note'',''debit_note'',''cancel_and_reissue'',''replacement_copy'')\n   or nullif(btrim(p_reason),'''') is null or length(btrim(p_reason))<5\n   or nullif(btrim(p_evidence_reference),'''') is null or length(btrim(p_evidence_reference))<5\n then raise exception ''TAX_CORRECTION_REASON_EVIDENCE_REQUIRED''; end if;\n if p_issue_date is null or p_adjustment_date is null or p_issue_date>(now() at time zone ''Asia/Bangkok'')::date\n   or p_adjustment_date>p_issue_date or p_adjustment_date<(src->>''document_date'')::date\n then raise exception ''TAX_CORRECTION_DATES_INVALID''; end if;\n if p_mode in (''credit_note'',''debit_note'') and p_issue_date>=(date_trunc(''month'',p_adjustment_date)+interval ''2 months'')::date\n then raise exception ''TAX_CORRECTION_ADJUSTMENT_PERIOD_REVIEW_REQUIRED''; end if;\n if p_legal_basis is null or not(case p_mode\n   when ''credit_note'' then p_legal_basis in (''service_overcharge'',''service_reduction'',''service_cancelled'')\n   when ''debit_note'' then p_legal_basis in (''service_undercharge'',''additional_service'')\n   when ''cancel_and_reissue'' then p_legal_basis=''documentary_identity_error''\n   when ''replacement_copy'' then p_legal_basis in (''lost'',''destroyed'',''materially_damaged'') else false end)\n then raise exception ''TAX_CORRECTION_MODE_BASIS_INCOMPATIBLE''; end if;\n if jsonb_typeof(p_lines) is distinct from ''array'' then raise exception ''TAX_CORRECTION_LINES_REQUIRED''; end if;\n if exists(select 1 from public.finance_tax_document_corrections where original_tax_invoice_id=p_tax_invoice_id and status in (''draft'',''approved''))\n then raise exception ''TAX_CORRECTION_OPEN_CASE_EXISTS''; end if;\n if p_mode in (''credit_note'',''debit_note'') then\n   if jsonb_array_length(p_lines)=0 then raise exception ''TAX_CORRECTION_LINES_REQUIRED''; end if;\n   sign:=case when p_mode=''credit_note'' then -1 else 1 end;\n   for line in select value from jsonb_array_elements(p_lines) loop\n     if jsonb_typeof(line) is distinct from ''object'' or line-array[''item_id'',''base_change'']<>''{}''::jsonb then raise exception ''TAX_CORRECTION_LINE_INVALID''; end if;\n     select * into original from public.finance_tax_invoice_items where id=(line->>''item_id'')::uuid and tax_invoice_id=p_tax_invoice_id;\n     if not found or exists(select 1 from jsonb_array_elements(lines) l where l->>''item_id''=original.id::text)\n     then raise exception ''TAX_CORRECTION_SOURCE_COVERAGE_INVALID''; end if;\n     delta:=(line->>''base_change'')::numeric;\n     if delta is null or delta::text in (''NaN'',''Infinity'',''-Infinity'') or delta<=0 or round(delta,2)<>delta then raise exception ''TAX_CORRECTION_AMOUNT_INVALID''; end if;\n     select original.amount_before_vat+coalesce(sum(case x.correction_mode when ''credit_note'' then -l.base_change else l.base_change end),0),\n       original.vat_amount+coalesce(sum(case x.correction_mode when ''credit_note'' then -l.vat_change else l.vat_change end),0)\n     into pb,pv from public.finance_tax_correction_lines l join public.finance_tax_document_corrections x on x.id=l.correction_id\n     where l.original_tax_invoice_item_id=original.id and x.status=''issued'';\n     -- Credit reductions cannot exceed the effective tax position; debit increases have no original-base cap.\n     if sign=-1 and delta>pb\n     then raise exception ''TAX_CORRECTION_SOURCE_COVERAGE_EXCEEDED''; end if;\n     dv:=case when sign=-1 and delta=pb then pv else round(delta*(original.source_snapshot_json->>''vat_rate'')::numeric/100,2) end;\n     if dv is null or dv<0 or (sign=-1 and dv>pv) then raise exception ''TAX_CORRECTION_VAT_INVALID''; end if;\n     lines:=lines||jsonb_build_array(jsonb_build_object(''item_id'',original.id,''source'',original.source_snapshot_json,\n       ''original_base'',original.amount_before_vat,''original_vat'',original.vat_amount,''previous_base'',pb,''previous_vat'',pv,\n       ''base_change'',delta,''vat_change'',dv,''resulting_base'',pb+sign*delta,''resulting_vat'',pv+sign*dv));\n   end loop;\n elsif jsonb_array_length(p_lines)<>0 then raise exception ''TAX_CORRECTION_DOCUMENTARY_AMOUNTS_BLOCKED''; end if;\n draft:=src||jsonb_build_object(''schema_version'',1,''correction_mode'',p_mode,''reason'',btrim(p_reason),''legal_basis'',p_legal_basis,\n   ''evidence_reference'',btrim(p_evidence_reference),''issue_date'',p_issue_date,''adjustment_date'',p_adjustment_date,''lines'',lines);\n select jsonb_build_object(''original_base'',sum(amount_before_vat),''original_vat'',sum(vat_amount)) into totals\n from public.finance_tax_invoice_items where tax_invoice_id=p_tax_invoice_id;\n select totals||jsonb_build_object(''previous_base'',(totals->>''original_base'')::numeric+coalesce(sum(case x.correction_mode when ''credit_note'' then -l.base_change else l.base_change end),0),\n   ''previous_vat'',(totals->>''original_vat'')::numeric+coalesce(sum(case x.correction_mode when ''credit_note'' then -l.vat_change else l.vat_change end),0)) into totals\n from public.finance_tax_correction_lines l join public.finance_tax_document_corrections x on x.id=l.correction_id\n where x.original_tax_invoice_id=p_tax_invoice_id and x.status=''issued'';\n select totals||jsonb_build_object(''base_change'',coalesce(sum((l->>''base_change'')::numeric),0),\n   ''vat_change'',coalesce(sum((l->>''vat_change'')::numeric),0),\n   ''resulting_base'',(totals->>''previous_base'')::numeric+coalesce(sign,0)*coalesce(sum((l->>''base_change'')::numeric),0),\n   ''resulting_vat'',(totals->>''previous_vat'')::numeric+coalesce(sign,0)*coalesce(sum((l->>''vat_change'')::numeric),0)) into totals from jsonb_array_elements(lines) l;\n draft:=draft||jsonb_build_object(''totals'',totals);\n if p_mode=''cancel_and_reissue'' then\n   buyer:=public.get_finance_customer_tax_profile((src #>> ''{tax,customer,id}'')::uuid);\n   buyer:=jsonb_build_object(''schema_version'',1,''status'',buyer->''status'',''profile'',buyer->''profile'');\n   if buyer->>''status'' is distinct from ''verified'' then raise exception ''TAX_CORRECTION_REVIEWED_BUYER_REQUIRED''; end if;\n   customer:=(src #> ''{tax,customer}'')||(buyer #> ''{profile,identity_snapshot_json}'')||jsonb_build_object(\n     ''vat_registered'',buyer #> ''{profile,vat_registered}'',''branch_type'',buyer #> ''{profile,branch_type}'',\n     ''branch_code'',buyer #> ''{profile,branch_code}'',''supplemental_evidence'',buyer #> ''{profile,identity_evidence}'');\n   if nullif(btrim(customer->>''name''),'''') is null or nullif(btrim(customer->>''address''),'''') is null\n     or customer->>''tax_id'' !~ ''^[0-9]{13}$'' then raise exception ''TAX_CORRECTION_REVIEWED_BUYER_REQUIRED''; end if;\n   draft:=jsonb_set(draft,''{tax}'',(src->''tax'')||jsonb_build_object(''customer'',customer,''buyer_tax_profile'',buyer));\n   if p_combined_id is not null then draft:=jsonb_set(draft,''{receipt}'',(src->''receipt'')||jsonb_build_object(''customer'',customer)); end if;\n end if;\n insert into public.finance_tax_document_corrections(id,request_id,original_tax_invoice_id,original_combined_document_id,original_receipt_id,\n   invoice_id,payment_id,source_correction_id,correction_mode,reason,legal_basis,evidence_reference,issue_date,adjustment_date,\n   source_snapshot_json,draft_snapshot_json,request_json,created_by_user_id)\n values(cid,p_request_id,p_tax_invoice_id,p_combined_id,(src->>''receipt_id'')::uuid,(src->>''invoice_id'')::uuid,(src->>''payment_id'')::uuid,\n   source_id,p_mode,btrim(p_reason),p_legal_basis,btrim(p_evidence_reference),p_issue_date,p_adjustment_date,src,draft,req,auth.uid());\n insert into public.finance_tax_correction_lines(correction_id,original_tax_invoice_item_id,base_change,vat_change,previous_base,previous_vat,resulting_base,resulting_vat,source_snapshot_json)\n select cid,(l->>''item_id'')::uuid,(l->>''base_change'')::numeric,(l->>''vat_change'')::numeric,(l->>''previous_base'')::numeric,\n   (l->>''previous_vat'')::numeric,(l->>''resulting_base'')::numeric,(l->>''resulting_vat'')::numeric,l->''source'' from jsonb_array_elements(lines) l;\n insert into public.finance_tax_correction_audit_events(correction_id,event_type,event_payload_json,actor_user_id)\n values(cid,''draft_created'',jsonb_build_object(''reason'',p_reason,''legal_basis'',p_legal_basis,''evidence_reference'',p_evidence_reference,''lines'',lines,''number_allocated'',false),auth.uid());\n return cid;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"create_finance_tax_invoice_draft","owner":"postgres","config":["search_path=public"],"signature":"create_finance_tax_invoice_draft(uuid)","definition":"CREATE OR REPLACE FUNCTION public.create_finance_tax_invoice_draft(p_payment_id uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare source jsonb; existing uuid; id uuid; event_id uuid; item_id uuid; item jsonb; date_today date:=(now() at time zone ''Asia/Bangkok'')::date;\nbegin\n  if not public.current_user_can_manage_finance_tax_invoices() then raise exception ''TAX_INVOICE_PERMISSION_DENIED''; end if;\n  perform 1 from public.finance_payments where finance_payments.id=p_payment_id for update;\n  select t.id into existing from public.finance_tax_invoices t where t.payment_id=p_payment_id and t.status in (''draft'',''issued'');\n  if found then return existing; end if;\n  perform public.assert_finance_document_route(p_payment_id,''tax_invoice'');\n  return public.prepare_finance_document_tax_draft(p_payment_id);\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"current_user_can_issue_combined_documents","owner":"postgres","config":["search_path=public"],"signature":"current_user_can_issue_combined_documents()","definition":"CREATE OR REPLACE FUNCTION public.current_user_can_issue_combined_documents()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nselect public.current_user_can_issue_finance_receipts() and public.current_user_can_issue_finance_tax_invoices();\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"current_user_can_issue_finance_receipts","owner":"postgres","config":["search_path=public"],"signature":"current_user_can_issue_finance_receipts()","definition":"CREATE OR REPLACE FUNCTION public.current_user_can_issue_finance_receipts()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select exists (select 1 from public.user_profiles where id = auth.uid() and active\n    and (role = ''admin'' or can_issue_finance_receipts));\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"current_user_can_issue_finance_tax_invoices","owner":"postgres","config":["search_path=public"],"signature":"current_user_can_issue_finance_tax_invoices()","definition":"CREATE OR REPLACE FUNCTION public.current_user_can_issue_finance_tax_invoices()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select exists(select 1 from public.user_profiles where id=auth.uid() and active and (role=''admin'' or can_issue_finance_tax_invoices));\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"current_user_can_manage_combined_documents","owner":"postgres","config":["search_path=public"],"signature":"current_user_can_manage_combined_documents()","definition":"CREATE OR REPLACE FUNCTION public.current_user_can_manage_combined_documents()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nselect public.current_user_can_manage_finance_receipts() and public.current_user_can_manage_finance_tax_invoices();\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"current_user_can_manage_finance_receipts","owner":"postgres","config":["search_path=public"],"signature":"current_user_can_manage_finance_receipts()","definition":"CREATE OR REPLACE FUNCTION public.current_user_can_manage_finance_receipts()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select exists (select 1 from public.user_profiles where id = auth.uid() and active\n    and (role = ''admin'' or can_manage_finance_receipts));\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"current_user_can_manage_finance_tax_invoices","owner":"postgres","config":["search_path=public"],"signature":"current_user_can_manage_finance_tax_invoices()","definition":"CREATE OR REPLACE FUNCTION public.current_user_can_manage_finance_tax_invoices()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select exists(select 1 from public.user_profiles where id=auth.uid() and active and (role=''admin'' or can_manage_finance_tax_invoices));\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"current_user_can_view_finance_receipts","owner":"postgres","config":["search_path=public"],"signature":"current_user_can_view_finance_receipts()","definition":"CREATE OR REPLACE FUNCTION public.current_user_can_view_finance_receipts()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select exists (select 1 from public.user_profiles where id = auth.uid() and active\n    and (role = ''admin'' or can_view_finance_receipts or can_manage_finance_receipts\n      or can_issue_finance_receipts or can_void_finance_receipts));\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"current_user_can_view_finance_tax_invoices","owner":"postgres","config":["search_path=public"],"signature":"current_user_can_view_finance_tax_invoices()","definition":"CREATE OR REPLACE FUNCTION public.current_user_can_view_finance_tax_invoices()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select exists(select 1 from public.user_profiles where id=auth.uid() and active and\n    (role=''admin'' or can_view_finance_tax_invoices or can_manage_finance_tax_invoices or can_issue_finance_tax_invoices));\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"current_user_can_void_finance_receipts","owner":"postgres","config":["search_path=public"],"signature":"current_user_can_void_finance_receipts()","definition":"CREATE OR REPLACE FUNCTION public.current_user_can_void_finance_receipts()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select exists (select 1 from public.user_profiles where id = auth.uid() and active\n    and (role = ''admin'' or can_void_finance_receipts));\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres}","name":"direct_money_lines","owner":"postgres","config":["search_path=public"],"signature":"direct_money_lines(jsonb)","definition":"CREATE OR REPLACE FUNCTION public.direct_money_lines(p_lines jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare l jsonb; result jsonb:=''[]''; amounts record; vat jsonb; wht numeric; base numeric; rate numeric; nature text; classification text;\nbegin\n if jsonb_typeof(p_lines) is distinct from ''array'' or jsonb_array_length(p_lines) not between 1 and 100\n then raise exception ''DIRECT_MONEY_LINES_REQUIRED''; end if;\n if (select count(distinct (value->>''source_line_id'')::uuid) from jsonb_array_elements(p_lines))<>jsonb_array_length(p_lines)\n then raise exception ''DIRECT_MONEY_LINE_ID_INVALID''; end if;\n for l in select value from jsonb_array_elements(p_lines) order by value->>''source_line_id'' loop\n  if jsonb_typeof(l) is distinct from ''object'' or exists(select 1 from jsonb_object_keys(l) k where k not in\n   (''source_line_id'',''description'',''reason'',''money_nature'',''classification'',''base'',''vat_applicable'',''vat_rate'',''vat_treatment_json'',''wht_applicability'',''wht_base'',''wht_rate''))\n   or nullif(btrim(l->>''description''),'''') is null or length(l->>''description'')>1000 or nullif(btrim(l->>''reason''),'''') is null or length(l->>''reason'')>2000\n  then raise exception ''DIRECT_MONEY_LINE_INVALID''; end if;\n  nature:=l->>''money_nature''; classification:=l->>''classification'';\n  if nature is null or nature not in(''business_revenue'',''client_money'',''owner_or_partner_funding'',''loan_or_deposit'',''reimbursement_or_pass_through'',''other_non_revenue'',''unclassified'')\n   or (nature=''business_revenue'' and (classification is null or classification not in(''professional_fee'',''additional_service'',''reimbursable_expense'',''government_or_court_fee'')))\n   or (nature<>''business_revenue'' and classification is not null) then raise exception ''DIRECT_MONEY_CLASSIFICATION_REQUIRED''; end if;\n  if jsonb_typeof(l->''vat_applicable'') is distinct from ''boolean'' or jsonb_typeof(l->''base'') is distinct from ''number''\n   or jsonb_typeof(l->''vat_rate'') is distinct from ''number'' then raise exception ''DIRECT_MONEY_VAT_INVALID''; end if;\n  base:=(l->>''base'')::numeric; rate:=(l->>''vat_rate'')::numeric;\n  if base<=0 or base>999999999999 or rate>100 then raise exception ''DIRECT_MONEY_AMOUNT_INVALID''; end if;\n  vat:=public.finance_vat_treatment(l->''vat_treatment_json'',(l->>''vat_applicable'')::boolean,rate);\n  if vat->>''treatment''=''unknown'' and nature<>''unclassified'' then raise exception ''DIRECT_MONEY_VAT_UNRESOLVED''; end if;\n  select * into amounts from public.calculate_finance_billable_charge_amounts(1,base,case when (l->>''vat_applicable'')::boolean then ''vat_exclusive'' else ''non_vat'' end,rate);\n  if l->>''wht_applicability''=''applies'' then\n   if jsonb_typeof(l->''wht_base'') is distinct from ''number'' or jsonb_typeof(l->''wht_rate'') is distinct from ''number''\n     or (l->>''wht_base'')::numeric>base then raise exception ''DIRECT_MONEY_WHT_INVALID''; end if;\n   wht:=public.finance_structured_wht_amount((l->>''wht_base'')::numeric,(l->>''wht_rate'')::numeric);\n   if wht<=0 then raise exception ''DIRECT_MONEY_WHT_INVALID''; end if;\n  elsif l->>''wht_applicability''=''does_not_apply'' then\n   if l->>''wht_base'' is not null or l->>''wht_rate'' is not null then raise exception ''DIRECT_MONEY_WHT_INVALID''; end if;\n   wht:=0;\n  else raise exception ''DIRECT_MONEY_WHT_INVALID''; end if;\n  result:=result||jsonb_build_array(l||jsonb_build_object(''source_line_id'',(l->>''source_line_id'')::uuid,\n   ''description'',btrim(l->>''description''),''reason'',btrim(l->>''reason''),''vat_treatment_json'',vat,\n   ''vat'',amounts.vat_amount,''gross'',amounts.total_amount,''wht'',wht,''cash'',amounts.total_amount-wht));\n end loop;\n return result;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"direct_money_snapshot","owner":"postgres","config":["search_path=public"],"signature":"direct_money_snapshot(finance_direct_money_receipts)","definition":"CREATE OR REPLACE FUNCTION public.direct_money_snapshot(p finance_direct_money_receipts)\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n select public.direct_money_snapshot_before_treasury(p)||jsonb_build_object(\n  ''cash_location'',(select to_jsonb(l) from public.finance_cash_locations l where l.id=p.receiving_cash_location_id),\n  ''cashbook'',jsonb_build_object(''posting_policy'',''confirmed_opening_strict_cutoff'',\n   ''original_leg_key'',''direct_money_receipt:''||p.id::text||'':original''));\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"direct_money_snapshot_before_treasury","owner":"postgres","config":["search_path=public"],"signature":"direct_money_snapshot_before_treasury(finance_direct_money_receipts)","definition":"CREATE OR REPLACE FUNCTION public.direct_money_snapshot_before_treasury(p finance_direct_money_receipts)\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n select jsonb_build_object(''schema_version'',1,''source_type'',''direct_money_receipt'',''source_id'',p.id,''source_version'',p.version,\n  ''currency'',p.currency,''actual_cash'',p.cash_amount,''wht_credit'',p.wht_amount,''gross_received'',p.gross_amount,\n  ''before_vat'',p.amount_before_vat,''vat'',p.vat_amount,''lines'',p.lines_json,\n  ''facts'',to_jsonb(p)-''confirmed_snapshot_json'',\n  ''client'',case when p.client_id is null then null else (select to_jsonb(c) from (select id,name from public.clients where id=p.client_id) c) end,\n  ''bank'',case when p.receiving_bank_account_id is null then null else (select to_jsonb(b) from (select id,short_name,bank_name from public.finance_bank_accounts where id=p.receiving_bank_account_id) b) end,\n  ''document_policy'',jsonb_build_object(''state'',''requires_review'',''automatic_issue'',false,''reason'',''direct_source_integration_not_enabled''),\n  ''cashbook'',jsonb_build_object(''posting_enabled'',false,''original_leg_key'',''direct_money_receipt:''||p.id::text||'':original''));\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"document_logo_evidence","owner":"postgres","config":["search_path=public"],"signature":"document_logo_evidence(text)","definition":"CREATE OR REPLACE FUNCTION public.document_logo_evidence(p_path text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_object storage.objects%rowtype;\nbegin\n  if p_path is null or p_path !~ ''^company/logo/[^/]+$'' or p_path like ''%..%'' then\n    raise exception ''RECEIPT_LOGO_EVIDENCE_REQUIRED'';\n  end if;\n  select * into v_object from storage.objects\n    where bucket_id = ''vp-document-assets'' and name = p_path;\n  if not found or lower(coalesce(v_object.metadata->>''mimetype'',''''))\n    not in (''image/png'',''image/jpeg'',''image/webp'',''image/svg+xml'') then\n    raise exception ''RECEIPT_LOGO_EVIDENCE_REQUIRED'';\n  end if;\n  return jsonb_build_object(''bucket'',''vp-document-assets'',''path'',v_object.name,\n    ''object_id'',v_object.id,''storage_version'',to_jsonb(v_object)->>''version'');\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"document_tax_snapshot_pre042","owner":"postgres","config":["search_path=public"],"signature":"document_tax_snapshot_pre042(jsonb,jsonb,date)","definition":"CREATE OR REPLACE FUNCTION public.document_tax_snapshot_pre042(p_source jsonb, p_decisions jsonb, p_issue_date date)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare decisions jsonb:=coalesce(p_decisions,''{}''); item jsonb; treatment text;\nbegin\n  if p_source->>''schema_version''=''2'' then\n    item:=p_source->''invoice_item''; treatment:=item #>> ''{resolved_vat_treatment,treatment}'';\n    decisions:=decisions||jsonb_build_object(''tax_treatment'',case when treatment=''standard_rate'' then ''standard_rated'' else treatment end,\n      ''treatment_reason'',item #> ''{resolved_vat_treatment,reason}'');\n  end if;\n  return public.tax_snapshot_pre040(p_source,decisions,p_issue_date);\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"document_tax_source_pre042","owner":"postgres","config":["search_path=public"],"signature":"document_tax_source_pre042(uuid)","definition":"CREATE OR REPLACE FUNCTION public.document_tax_source_pre042(p_payment_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare p public.finance_payments%rowtype; i public.finance_invoices%rowtype; a record; source jsonb; company jsonb;\n  lines jsonb; taxable jsonb; seller jsonb;\nbegin\n  select * into strict p from public.finance_payments where id=p_payment_id for update;\n  if p.status<>''confirmed'' then raise exception ''DOCUMENT_PAYMENT_REQUIRED''; end if;\n  if (select count(*) from public.finance_payment_effective_invoice_allocations where payment_id=p.id)<>1 then raise exception ''DOCUMENT_MULTIPLE_INVOICES''; end if;\n  select * into strict a from public.finance_payment_effective_invoice_allocations where payment_id=p.id;\n  select * into strict i from public.finance_invoices where id=a.invoice_id for share;\n  lines:=public.finance_document_invoice_lines(i.id);\n  if i.document_status<>''issued'' or i.source_model<>''billable_charge_v2'' or i.currency<>''THB'' or p.currency<>i.currency or p.client_id<>i.client_id\n    or a.effective_settlement_total<>i.total_amount or p.settlement_amount<>i.total_amount\n    or a.effective_cash_allocated<>p.cash_amount or a.effective_wht_credit_allocated<>p.wht_amount\n  then raise exception ''DOCUMENT_PARTIAL_TAXABLE''; end if;\n  if exists(select 1 from jsonb_array_elements(lines) e where e #>> ''{resolved_vat_treatment,treatment}''=''unknown'') then raise exception ''DOCUMENT_UNKNOWN_TREATMENT''; end if;\n  select jsonb_agg(e) into taxable from jsonb_array_elements(lines) e where e #>> ''{resolved_vat_treatment,treatment}'' in (''standard_rate'',''zero_rated'');\n  if taxable is null then raise exception ''DOCUMENT_RECEIPT_ONLY''; end if;\n  source:=public.build_finance_receipt_source(p.id);\n  select to_jsonb(c) into company from public.finance_company_profiles c where id=''default'';\n  seller:=source->''seller''||jsonb_build_object(''vat_registered'',true,''registration_basis'',''approved_vp_v1_policy'',\n    ''branch_label_th'',coalesce(nullif(btrim(company->>''branch_th''),''''),nullif(btrim(company->>''branch_label''),'''')),\n    ''branch_type'',case when lower(coalesce(nullif(btrim(company->>''branch_th''),''''),btrim(company->>''branch_label''))) in (''สำนักงานใหญ่'',''head office'') then ''head_office'' end,\n    ''branch_code'',case when lower(coalesce(nullif(btrim(company->>''branch_th''),''''),btrim(company->>''branch_label''))) in (''สำนักงานใหญ่'',''head office'') then ''00000'' end);\n  return source||jsonb_build_object(''schema_version'',2,''document_kind'',''tax_invoice'',''seller'',seller,\n    ''invoice'',i.issued_snapshot_json->''invoice'',''invoice_snapshot'',i.issued_snapshot_json,\n    ''invoice_item'',taxable->0,''invoice_items'',taxable,''document_lines'',lines,\n    ''receipt_reference'',(select jsonb_build_object(''id'',r.id,''receipt_no'',r.receipt_no,''issued_at'',r.issued_at)\n      from public.finance_receipts r where r.payment_id=p.id and r.status=''issued'' and r.combined_document_id is null));\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"finance_customer_tax_identity","owner":"postgres","config":["search_path=public"],"signature":"finance_customer_tax_identity(uuid)","definition":"CREATE OR REPLACE FUNCTION public.finance_customer_tax_identity(p_client_id uuid)\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  select jsonb_build_object(''id'',c.id,''name'',nullif(btrim(c.name),''''),''tax_id'',nullif(btrim(c.tax_id),''''),\n    ''address'',nullif(btrim(c.address),''''),''client_type'',c.client_type)\n  from public.clients c where c.id=p_client_id and c.status is distinct from ''deleted'';\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"finance_document_invoice_lines","owner":"postgres","config":["search_path=public"],"signature":"finance_document_invoice_lines(uuid)","definition":"CREATE OR REPLACE FUNCTION public.finance_document_invoice_lines(p_invoice_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare i public.finance_invoices%rowtype; entries jsonb; entry jsonb; item jsonb; evidence jsonb; result jsonb:=''[]'';\n  before_vat numeric:=0; vat numeric:=0; gross numeric:=0;\nbegin\n  select * into strict i from public.finance_invoices where id=p_invoice_id;\n  if i.document_status=''issued'' then\n    entries:=i.issued_snapshot_json->''items'';\n    if i.issued_snapshot_json->>''source_model'' is distinct from i.source_model then raise exception ''DOCUMENT_SOURCE_INVALID''; end if;\n  elsif i.document_status=''draft'' then\n    select coalesce(jsonb_agg(jsonb_build_object(''invoice_item'',to_jsonb(it)) order by sort_order,id),''[]'') into entries\n      from public.finance_invoice_items it where invoice_id=i.id and source_state=''active'';\n  else raise exception ''DOCUMENT_SOURCE_INVALID''; end if;\n  if jsonb_typeof(entries) is distinct from ''array'' or jsonb_array_length(entries)=0 then raise exception ''DOCUMENT_SOURCE_INVALID''; end if;\n  for entry in select value from jsonb_array_elements(entries) loop\n    item:=coalesce(entry->''invoice_item'',entry);\n    if item->>''invoice_id'' is distinct from i.id::text or nullif(btrim(item->>''description''),'''') is null\n      or (item->>''line_total'')::numeric is distinct from (item->>''amount_before_vat'')::numeric+(item->>''vat_amount'')::numeric\n      or not exists(select 1 from public.finance_invoice_items where invoice_id=i.id and id::text=item->>''id'' and source_state=''active'')\n    then raise exception ''DOCUMENT_SOURCE_INVALID''; end if;\n    evidence:=public.finance_vat_treatment(item->''vat_treatment_json'',(item->>''vat_applicable'')::boolean,(item->>''vat_rate'')::numeric);\n    if evidence->>''treatment''<>''standard_rate'' and (item->>''vat_amount'')::numeric<>0 then raise exception ''DOCUMENT_VAT_CONFLICT''; end if;\n    result:=result||jsonb_build_array(item||jsonb_build_object(''resolved_vat_treatment'',evidence));\n    before_vat:=before_vat+(item->>''amount_before_vat'')::numeric; vat:=vat+(item->>''vat_amount'')::numeric; gross:=gross+(item->>''line_total'')::numeric;\n  end loop;\n  if before_vat is distinct from i.amount_before_vat or vat is distinct from i.vat_amount or gross is distinct from i.total_amount\n    or (select count(distinct value->>''id'') from jsonb_array_elements(result))<>jsonb_array_length(result)\n  then raise exception ''DOCUMENT_SOURCE_INVALID''; end if;\n  return result;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"finance_invoice_wht_basis_v1","owner":"postgres","config":["search_path=public"],"signature":"finance_invoice_wht_basis_v1(jsonb)","definition":"CREATE OR REPLACE FUNCTION public.finance_invoice_wht_basis_v1(p_snapshot jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare v_invoice jsonb; v_item jsonb; v_base numeric; v_vat numeric; v_gross numeric;\nbegin\n  if p_snapshot->>''schema_version'' is distinct from ''2''\n    or p_snapshot->>''source_model'' is distinct from ''billable_charge_v2''\n    or jsonb_typeof(p_snapshot->''items'') is distinct from ''array''\n  then raise exception ''WHT_SNAPSHOT_INVALID''; end if;\n  if jsonb_array_length(p_snapshot->''items'') <> 1 then raise exception ''WHT_COMPONENT_SCOPE_UNSUPPORTED''; end if;\n  v_invoice := p_snapshot->''invoice'';\n  v_item := p_snapshot->''items''->0->''invoice_item'';\n  if v_invoice->>''document_status'' is distinct from ''issued''\n    or v_item->>''source_state'' is distinct from ''active''\n    or v_item->>''invoice_id'' is distinct from v_invoice->>''id''\n    or nullif(v_invoice->>''currency'','''') is null\n    or nullif(v_invoice->>''id'','''') is null or nullif(v_item->>''id'','''') is null\n    or jsonb_typeof(v_item->''vat_applicable'') is distinct from ''boolean''\n    or exists (select 1 from (values (''amount_before_vat''),(''vat_amount''),(''total_amount'')) f(key)\n      where jsonb_typeof(v_invoice->f.key) is distinct from ''number'')\n    or exists (select 1 from (values (''amount_before_vat''),(''vat_amount''),(''line_total'')) f(key)\n      where jsonb_typeof(v_item->f.key) is distinct from ''number'')\n  then raise exception ''WHT_SNAPSHOT_INVALID''; end if;\n  v_base := (v_invoice->>''amount_before_vat'')::numeric;\n  v_vat := (v_invoice->>''vat_amount'')::numeric;\n  v_gross := (v_invoice->>''total_amount'')::numeric;\n  if v_base <= 0 or v_vat < 0 or v_gross <= 0 or v_base+v_vat <> v_gross\n    or v_base <> round(v_base,2) or v_vat <> round(v_vat,2) or v_gross <> round(v_gross,2)\n    or (v_item->>''amount_before_vat'')::numeric <> v_base\n    or (v_item->>''vat_amount'')::numeric <> v_vat or (v_item->>''line_total'')::numeric <> v_gross\n    or (v_item->>''vat_applicable'' = ''false'' and v_vat <> 0)\n  then raise exception ''WHT_SNAPSHOT_INVALID''; end if;\n  return jsonb_build_object(''invoice_id'',v_invoice->>''id'',''invoice_item_id'',v_item->>''id'',\n    ''currency'',v_invoice->>''currency'',''amount_before_vat'',v_base,''vat_amount'',v_vat,''total_amount'',v_gross,\n    ''vat_applicable'',(v_item->>''vat_applicable'')::boolean,''calculation_rule'',''single_line_full_invoice_v1'');\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"finance_invoice_wht_lines_v2","owner":"postgres","config":["search_path=public"],"signature":"finance_invoice_wht_lines_v2(jsonb)","definition":"CREATE OR REPLACE FUNCTION public.finance_invoice_wht_lines_v2(p_snapshot jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare\n  inv jsonb; item jsonb; result jsonb:=''[]''; ids text[]:=array[]::text[];\n  b numeric; v numeric; g numeric; sb numeric:=0; sv numeric:=0; sg numeric:=0;\nbegin\n  if p_snapshot->>''schema_version'' is distinct from ''2''\n    or p_snapshot->>''source_model'' is distinct from ''billable_charge_v2''\n    or jsonb_typeof(p_snapshot->''items'') is distinct from ''array''\n  then raise exception ''WHT_SNAPSHOT_INVALID''; end if;\n  if jsonb_array_length(p_snapshot->''items'')=0 then raise exception ''WHT_SNAPSHOT_INVALID''; end if;\n  inv:=p_snapshot->''invoice'';\n  if inv->>''document_status'' is distinct from ''issued'' or nullif(inv->>''currency'','''') is null\n    or nullif(inv->>''id'','''') is null\n    or exists(select 1 from (values(''amount_before_vat''),(''vat_amount''),(''total_amount'')) f(k)\n      where jsonb_typeof(inv->f.k) is distinct from ''number'')\n  then raise exception ''WHT_SNAPSHOT_INVALID''; end if;\n  perform (inv->>''id'')::uuid;\n  for item in select e->''invoice_item'' from jsonb_array_elements(p_snapshot->''items'') e loop\n    if item->>''source_state'' is distinct from ''active''\n      or item->>''invoice_id'' is distinct from inv->>''id'' or nullif(item->>''id'','''') is null\n      or (item->>''id'')=any(ids) or jsonb_typeof(item->''vat_applicable'') is distinct from ''boolean''\n      or exists(select 1 from (values(''amount_before_vat''),(''vat_amount''),(''line_total'')) f(k)\n        where jsonb_typeof(item->f.k) is distinct from ''number'')\n    then raise exception ''WHT_SNAPSHOT_INVALID''; end if;\n    perform (item->>''id'')::uuid;\n    ids:=array_append(ids,item->>''id'');\n    b:=(item->>''amount_before_vat'')::numeric; v:=(item->>''vat_amount'')::numeric; g:=(item->>''line_total'')::numeric;\n    if b<=0 or v<0 or g<=0 or b+v<>g or b<>round(b,2) or v<>round(v,2) or g<>round(g,2)\n      or (item->>''vat_applicable''=''false'' and v<>0)\n    then raise exception ''WHT_SNAPSHOT_INVALID''; end if;\n    sb:=sb+b; sv:=sv+v; sg:=sg+g;\n    result:=result||jsonb_build_array(jsonb_build_object(''invoice_id'',inv->>''id'',''invoice_item_id'',item->>''id'',\n      ''currency'',inv->>''currency'',''amount_before_vat'',b,''vat_amount'',v,''total_amount'',g,\n      ''vat_applicable'',(item->>''vat_applicable'')::boolean,''calculation_rule'',''line_review_full_invoice_v2''));\n  end loop;\n  if sb<>(inv->>''amount_before_vat'')::numeric or sv<>(inv->>''vat_amount'')::numeric or sg<>(inv->>''total_amount'')::numeric\n  then raise exception ''WHT_SNAPSHOT_INVALID''; end if;\n  return result;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"finance_payment_document_decision","owner":"postgres","config":["search_path=public"],"signature":"finance_payment_document_decision(uuid)","definition":"CREATE OR REPLACE FUNCTION public.finance_payment_document_decision(p_payment_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare p public.finance_payments%rowtype; allocation record; i public.finance_invoices%rowtype; lines jsonb:=''[]''; current_lines jsonb;\n  partial boolean:=false; relevant boolean; unknown_lines jsonb; r public.finance_receipts%rowtype; t public.finance_tax_invoices%rowtype;\n  combined public.finance_combined_documents%rowtype; decision text; cash numeric:=0; wht numeric:=0;\nbegin\n  select * into p from public.finance_payments where id=p_payment_id;\n  if not found or p.status<>''confirmed'' then return jsonb_build_object(''decision'',''blocked_payment'',''lines'',''[]''::jsonb); end if;\n  for allocation in select * from public.finance_payment_effective_invoice_allocations where payment_id=p.id order by invoice_id loop\n    select * into strict i from public.finance_invoices where id=allocation.invoice_id;\n    if i.document_status<>''issued'' or i.client_id<>p.client_id or i.currency<>p.currency then raise exception ''DOCUMENT_SOURCE_INVALID''; end if;\n    current_lines:=public.finance_document_invoice_lines(i.id); lines:=lines||current_lines;\n    cash:=cash+allocation.effective_cash_allocated; wht:=wht+allocation.effective_wht_credit_allocated;\n    partial:=partial or allocation.effective_settlement_total<>i.total_amount;\n  end loop;\n  if jsonb_array_length(lines)=0 or cash<>p.cash_amount or wht<>p.wht_amount then raise exception ''DOCUMENT_SOURCE_INVALID''; end if;\n  select coalesce(jsonb_agg(value) filter(where value #>> ''{resolved_vat_treatment,treatment}''=''unknown''),''[]''),\n    bool_or(value #>> ''{resolved_vat_treatment,treatment}'' in (''standard_rate'',''zero_rated'')) into unknown_lines,relevant from jsonb_array_elements(lines);\n  select * into r from public.finance_receipts where payment_id=p.id and status in (''draft'',''issued'');\n  select * into t from public.finance_tax_invoices where payment_id=p.id and status in (''draft'',''issued'');\n  select * into combined from public.finance_combined_documents where payment_id=p.id and status in (''draft'',''issued'');\n  decision:=case\n    when jsonb_array_length(unknown_lines)>0 then ''blocked_unknown_treatment''\n    when relevant and partial then ''blocked_partial_taxable''\n    when relevant and (select count(*) from public.finance_payment_effective_invoice_allocations where payment_id=p.id)<>1 then ''blocked_multiple_invoices''\n    when combined.status=''issued'' then ''complete''\n    when combined.id is not null then ''combined_receipt_tax_invoice''\n    when r.status=''issued'' and t.status=''issued'' then ''complete''\n    when relevant and r.status=''issued'' then ''tax_invoice_completion_only''\n    when relevant and t.status=''issued'' then ''receipt_completion_only''\n    when relevant then ''combined_receipt_tax_invoice''\n    when r.status=''issued'' then ''complete''\n    else ''receipt_only'' end;\n  return jsonb_build_object(''decision'',decision,''lines'',lines,''unknown_lines'',unknown_lines,''partial'',partial,\n    ''receipt_id'',r.id,''receipt_status'',r.status,''tax_invoice_id'',t.id,''tax_invoice_status'',t.status,\n    ''combined_id'',combined.id,''combined_status'',combined.status);\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"finance_structured_wht_amount","owner":"postgres","config":["search_path=public"],"signature":"finance_structured_wht_amount(numeric,numeric)","definition":"CREATE OR REPLACE FUNCTION public.finance_structured_wht_amount(p_base numeric, p_rate numeric)\n RETURNS numeric\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\nbegin\n if p_base is null or p_base<=0 or p_base<>round(p_base,2) or p_rate is null or p_rate<=0 or p_rate>100 or p_rate<>round(p_rate,4)\n then raise exception ''WHT_LINE_RATE_REQUIRED''; end if;\n return round(p_base*p_rate/100,2);\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"finance_tax_invoice_draft_snapshot","owner":"postgres","config":["search_path=public"],"signature":"finance_tax_invoice_draft_snapshot(jsonb,jsonb,date)","definition":"CREATE OR REPLACE FUNCTION public.finance_tax_invoice_draft_snapshot(p_source jsonb, p_decisions jsonb, p_issue_date date)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare envelope jsonb:=p_source->''buyer_tax_profile''; profile jsonb:=envelope->''profile''; controlled jsonb; k text;\n  decisions jsonb:=coalesce(p_decisions,''{}''); reviewed boolean:=envelope->>''status''=''verified'';\nbegin\n  -- Existing frozen Draft/Issued sources retain their exact predecessor semantics.\n  if envelope is null then return public.document_tax_snapshot_pre042(p_source,p_decisions,p_issue_date); end if;\n  if jsonb_typeof(decisions) is distinct from ''object'' then raise exception ''TAX_INVOICE_DECISIONS_INVALID''; end if;\n  controlled:=jsonb_build_object(''buyer_vat_registered'',case when reviewed then profile->''vat_registered'' end,\n    ''buyer_branch_type'',case when reviewed then profile->''branch_type'' end,\n    ''buyer_branch_code'',case when reviewed then profile->''branch_code'' end,\n    ''identity_evidence'',case when reviewed then profile->''identity_evidence'' end);\n  foreach k in array array[''buyer_vat_registered'',''buyer_branch_type'',''buyer_branch_code'',''identity_evidence''] loop\n    if decisions ? k and decisions->k is distinct from controlled->k then raise exception ''CUSTOMER_TAX_PROFILE_OVERRIDE_BLOCKED''; end if;\n  end loop;\n  if decisions ? ''customer_address'' or decisions ? ''customer_tax_id'' then raise exception ''CUSTOMER_TAX_PROFILE_OVERRIDE_BLOCKED''; end if;\n  return public.document_tax_snapshot_pre042(p_source,decisions||controlled,p_issue_date);\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"finance_tax_invoice_issue_blockers","owner":"postgres","config":["search_path=public"],"signature":"finance_tax_invoice_issue_blockers(jsonb)","definition":"CREATE OR REPLACE FUNCTION public.finance_tax_invoice_issue_blockers(p_snapshot jsonb)\n RETURNS text[]\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare result text[]:=''{}''; item jsonb; treatment text; b text[];\nbegin\n  if p_snapshot->>''schema_version''<>''2'' then return public.tax_blockers_pre040(p_snapshot); end if;\n  if jsonb_typeof(p_snapshot->''invoice_items'') is distinct from ''array'' or jsonb_array_length(p_snapshot->''invoice_items'')=0 then return array[''DOCUMENT_SOURCE_INVALID'']; end if;\n  for item in select value from jsonb_array_elements(p_snapshot->''invoice_items'') loop\n    treatment:=item #>> ''{resolved_vat_treatment,treatment}'';\n    b:=public.tax_blockers_pre040(p_snapshot||jsonb_build_object(''invoice_item'',item,\n      ''tax_treatment'',case when treatment=''standard_rate'' then ''standard_rated'' else treatment end,''treatment_reason'',item #> ''{resolved_vat_treatment,reason}''));\n    result:=result||b;\n  end loop;\n  return array(select distinct e from unnest(result) e order by e);\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"finance_vat_treatment","owner":"postgres","config":["search_path=public"],"signature":"finance_vat_treatment(jsonb,boolean,numeric)","definition":"CREATE OR REPLACE FUNCTION public.finance_vat_treatment(p_evidence jsonb, p_applicable boolean, p_rate numeric)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare treatment text:=p_evidence->>''treatment''; reason text:=nullif(btrim(p_evidence->>''reason''),'''');\nbegin\n  if p_applicable is true and p_rate>0 and p_rate<=100 then\n    if treatment is not null and treatment not in (''unknown'',''standard_rate'') then raise exception ''DOCUMENT_VAT_CONFLICT''; end if;\n    return jsonb_build_object(''schema_version'',1,''treatment'',''standard_rate'',''reason'',null,''basis'',''explicit_positive_vat'');\n  end if;\n  if treatment is null or treatment=''unknown'' then\n    return jsonb_build_object(''schema_version'',1,''treatment'',''unknown'',''reason'',null,''basis'',''unresolved'');\n  end if;\n  if p_rate is distinct from 0 or reason is null or length(reason)>2000\n    or treatment not in (''zero_rated'',''exempt'',''outside_scope'',''disbursement'',''pass_through'')\n    or (treatment=''zero_rated'') is distinct from p_applicable then raise exception ''DOCUMENT_VAT_CONFLICT''; end if;\n  return jsonb_build_object(''schema_version'',1,''treatment'',treatment,''reason'',reason,''basis'',''explicit_review'');\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"generate_finance_document_no","owner":"postgres","config":["search_path=public"],"signature":"generate_finance_document_no(text,date)","definition":"CREATE OR REPLACE FUNCTION public.generate_finance_document_no(p_doc_type text, p_issue_date date DEFAULT CURRENT_DATE)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_input_type text := lower(trim(coalesce(p_doc_type, '''')));\n  v_counter_type text;\n  v_year integer := extract(year from p_issue_date)::integer;\n  v_month integer;\n  v_prefix_code text;\n  v_prefix text;\n  v_next integer;\n  v_width integer := 4;\n  v_period_scope text;\nbegin\n  if v_input_type = '''' then raise exception ''Document type is required''; end if;\n  if p_issue_date is null then raise exception ''Document issue date is required''; end if;\n  if v_input_type = ''receipt_tax_invoice'' then\n    if not public.current_user_can_issue_combined_documents() then raise exception ''DOCUMENT_PERMISSION_DENIED''; end if;\n  elsif v_input_type = ''tax_invoice'' then\n    if not public.current_user_can_issue_finance_tax_invoices() then raise exception ''TAX_INVOICE_PERMISSION_DENIED''; end if;\n  elsif v_input_type = ''receipt'' then\n    if not public.current_user_can_issue_finance_receipts() then raise exception ''RECEIPT_PERMISSION_DENIED''; end if;\n  elsif not public.current_user_can_manage_finance_quotations() then\n    raise exception ''Not allowed to allocate document number'';\n  end if;\n\n  if v_input_type in (''fee_agreement'', ''invoice'', ''receipt'', ''tax_invoice'', ''receipt_tax_invoice'') then\n    select display_prefix, period_scope, sequence_width\n      into v_prefix_code, v_period_scope, v_width\n    from public.document_numbering_profiles\n    where document_type = v_input_type and is_active;\n    if v_prefix_code is null then raise exception ''Document numbering profile is not active''; end if;\n    if v_input_type = ''receipt'' and (v_prefix_code <> ''VP-RC'' or v_period_scope <> ''monthly'' or v_width <> 6) then\n      raise exception ''RECEIPT_NUMBERING_PROFILE_INVALID'';\n    end if;\n    if v_input_type = ''tax_invoice'' and (v_prefix_code <> ''VP-TI'' or v_period_scope <> ''monthly'' or v_width <> 6) then\n      raise exception ''TAX_INVOICE_NUMBERING_PROFILE_INVALID'';\n    end if;\n    if v_input_type=''receipt_tax_invoice'' and (v_prefix_code<>''VP-RTI'' or v_period_scope<>''monthly'' or v_width<>6) then raise exception ''DOCUMENT_NUMBERING_PROFILE_INVALID''; end if;\n    v_counter_type := v_input_type;\n    v_month := case when v_period_scope = ''annual'' then null else extract(month from p_issue_date)::integer end;\n    v_prefix := v_prefix_code || ''-'' || case\n      when v_period_scope = ''annual'' then to_char(p_issue_date, ''YYYY'')\n      else to_char(p_issue_date, ''YYYYMM'')\n    end || ''-'';\n  else\n    v_counter_type := upper(v_input_type);\n    v_month := extract(month from p_issue_date)::integer;\n    if v_counter_type = ''QT'' then\n      select nullif(trim(quotation_prefix), '''') into v_prefix_code\n      from public.finance_company_profiles where id = ''default'';\n      v_prefix_code := coalesce(v_prefix_code, ''VP-QT'');\n    else\n      v_prefix_code := v_counter_type;\n    end if;\n    v_prefix := v_prefix_code || ''-'' || to_char(p_issue_date, ''YYYYMM'') || ''-'';\n  end if;\n\n  insert into public.finance_document_counters (doc_type, year, month, prefix, last_no)\n  values (v_counter_type, v_year, v_month, v_prefix, 1)\n  on conflict (doc_type, year, (coalesce(month, 0))) do update set\n    last_no = public.finance_document_counters.last_no + 1,\n    prefix = excluded.prefix,\n    updated_at = now()\n  returning last_no into v_next;\n\n  if v_input_type in (''receipt'',''tax_invoice'',''receipt_tax_invoice'') and length(v_next::text) > v_width then\n    raise exception using message = case when v_input_type=''tax_invoice'' then ''TAX_INVOICE_NUMBERING_EXHAUSTED'' else ''RECEIPT_NUMBERING_EXHAUSTED'' end;\n  end if;\n  return v_prefix || lpad(v_next::text, v_width, ''0'');\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"get_finance_customer_tax_profile","owner":"postgres","config":["search_path=public"],"signature":"get_finance_customer_tax_profile(uuid)","definition":"CREATE OR REPLACE FUNCTION public.get_finance_customer_tax_profile(p_client_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare identity jsonb; profile public.finance_customer_tax_profiles%rowtype;\nbegin\n  if not public.current_user_can_view_finance_tax_invoices() then raise exception ''CUSTOMER_TAX_PROFILE_PERMISSION_DENIED''; end if;\n  identity:=public.finance_customer_tax_identity(p_client_id);\n  if identity is null then raise exception ''CUSTOMER_TAX_PROFILE_CLIENT_REQUIRED''; end if;\n  select * into profile from public.finance_customer_tax_profiles where client_id=p_client_id;\n  return jsonb_build_object(''identity'',identity,''profile'',case when profile.client_id is not null then to_jsonb(profile) end,\n    ''can_manage'',public.current_user_can_manage_finance_tax_invoices(),\n    ''status'',case when profile.client_id is null then ''missing''\n      when profile.identity_snapshot_json is distinct from identity then ''stale''\n      when profile.verified_at is null then ''unverified'' else ''verified'' end);\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"get_finance_document_decision","owner":"postgres","config":["search_path=public"],"signature":"get_finance_document_decision(uuid)","definition":"CREATE OR REPLACE FUNCTION public.get_finance_document_decision(p_payment_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare d jsonb; source jsonb;\nbegin\n  if not(public.current_user_can_view_finance_receipts() or public.current_user_can_view_finance_tax_invoices()) then raise exception ''DOCUMENT_PERMISSION_DENIED''; end if;\n  d:=public.finance_payment_document_decision(p_payment_id);\n  if d->>''decision'' in (''combined_receipt_tax_invoice'',''tax_invoice_completion_only'') then\n    if d->>''tax_invoice_id'' is not null then\n      select draft_snapshot_json into source from public.finance_tax_invoices where id=(d->>''tax_invoice_id'')::uuid;\n    else\n      source:=public.finance_tax_invoice_draft_snapshot(public.build_finance_document_tax_source(p_payment_id),''{}'',(now() at time zone ''Asia/Bangkok'')::date);\n    end if;\n    d:=d||jsonb_build_object(''blockers'',public.finance_tax_invoice_issue_blockers(source));\n  end if;\n  return d;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres}","name":"guard_finance_receipt_lifecycle","owner":"postgres","config":["search_path=public"],"signature":"guard_finance_receipt_lifecycle()","definition":"CREATE OR REPLACE FUNCTION public.guard_finance_receipt_lifecycle()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''public''\nAS $function$\nbegin\n  if tg_op = ''DELETE'' then raise exception ''RECEIPT_HISTORY_IMMUTABLE''; end if;\n  if tg_op = ''INSERT'' then\n    if new.status <> ''draft'' then raise exception ''RECEIPT_DRAFT_REQUIRED''; end if;\n    return new;\n  end if;\n  if new.id is distinct from old.id or new.payment_id is distinct from old.payment_id\n    or new.client_id is distinct from old.client_id or new.replaces_receipt_id is distinct from old.replaces_receipt_id\n    or new.created_at is distinct from old.created_at or new.created_by_user_id is distinct from old.created_by_user_id\n    or new.external_receipt_checked_at is distinct from old.external_receipt_checked_at\n    or new.external_receipt_checked_by_user_id is distinct from old.external_receipt_checked_by_user_id\n  then raise exception ''RECEIPT_SOURCE_IMMUTABLE''; end if;\n  if old.status = ''draft'' and new.status in (''draft'',''issued'',''cancelled'') then return new; end if;\n  if old.status = ''issued'' and new.status = ''voided'' and\n    (to_jsonb(new) - array[''status'',''voided_at'',''voided_by_user_id'',''void_reason'',''updated_at'',''settlement_amount''])\n      = (to_jsonb(old) - array[''status'',''voided_at'',''voided_by_user_id'',''void_reason'',''updated_at'',''settlement_amount''])\n  then return new; end if;\n  raise exception ''RECEIPT_HISTORY_IMMUTABLE'';\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"guard_receipt_logo_issue","owner":"postgres","config":["search_path=public"],"signature":"guard_receipt_logo_issue()","definition":"CREATE OR REPLACE FUNCTION public.guard_receipt_logo_issue()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n  if new.status = ''issued'' and old.status is distinct from ''issued'' then\n    if (new.issued_snapshot_json->''schema_version'') is distinct from ''2''::jsonb\n      or (new.issued_snapshot_json #> ''{seller,logo_asset}'') is distinct from\n        public.document_logo_evidence(new.issued_snapshot_json #>> ''{seller,logo_asset,path}'') then\n      raise exception ''RECEIPT_LOGO_EVIDENCE_REQUIRED'';\n    end if;\n  end if;\n  return new;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"issue_finance_combined_document","owner":"postgres","config":["search_path=public"],"signature":"issue_finance_combined_document(uuid,jsonb,boolean,boolean,boolean,boolean)","definition":"CREATE OR REPLACE FUNCTION public.issue_finance_combined_document(p_combined_id uuid, p_reviewed_snapshot_json jsonb, p_acknowledged boolean, p_delayed_issue_acknowledged boolean, p_external_receipt_checked boolean, p_external_tax_checked boolean)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare c public.finance_combined_documents%rowtype; r public.finance_receipts%rowtype; t public.finance_tax_invoices%rowtype;\n  point public.finance_tax_point_events%rowtype; source jsonb; rs jsonb; ts jsonb; number text; moment timestamptz:=now(); blockers text[];\nbegin\n  if not public.current_user_can_issue_combined_documents() then raise exception ''DOCUMENT_PERMISSION_DENIED''; end if;\n  if p_acknowledged is distinct from true then raise exception ''DOCUMENT_ISSUE_ACK_REQUIRED''; end if;\n  perform 1 from public.finance_payments where id=(select payment_id from public.finance_combined_documents where id=p_combined_id) for update;\n  select * into strict c from public.finance_combined_documents where id=p_combined_id for update;\n  if c.status=''issued'' then return c.id; end if;\n  if c.status<>''draft'' then raise exception ''DOCUMENT_DRAFT_REQUIRED''; end if;\n  if p_external_receipt_checked is distinct from true or p_external_tax_checked is distinct from true then raise exception ''DOCUMENT_EXTERNAL_CHECK_REQUIRED''; end if;\n  if public.finance_payment_document_decision(c.payment_id)->>''decision''<>''combined_receipt_tax_invoice'' then raise exception ''DOCUMENT_SOURCE_CHANGED''; end if;\n  source:=public.build_finance_document_tax_source(c.payment_id);\n  if source is distinct from c.source_snapshot_json then raise exception ''DOCUMENT_SOURCE_CHANGED''; end if;\n  if c.draft_snapshot_json is distinct from p_reviewed_snapshot_json then raise exception ''DOCUMENT_STALE_REVIEW''; end if;\n  select * into strict r from public.finance_receipts where id=c.receipt_id for update;\n  select * into strict t from public.finance_tax_invoices where id=c.tax_invoice_id for update;\n  if r.status<>''draft'' or t.status<>''draft'' then raise exception ''DOCUMENT_DRAFT_REQUIRED''; end if;\n  blockers:=public.finance_tax_invoice_issue_blockers(t.draft_snapshot_json);\n  if cardinality(blockers)>0 then raise exception using message=blockers[1]; end if;\n  select * into strict point from public.finance_tax_point_events where tax_invoice_id=t.id for update;\n  if point.approved_at is null or point.approved_by_user_id is null then raise exception ''TAX_INVOICE_TAX_POINT_APPROVAL_REQUIRED''; end if;\n  if c.issue_date<point.occurred_on or c.issue_date>(moment at time zone ''Asia/Bangkok'')::date then raise exception ''TAX_INVOICE_ISSUE_DATE_INVALID''; end if;\n  if c.issue_date>point.occurred_on and p_delayed_issue_acknowledged is distinct from true then raise exception ''TAX_INVOICE_DELAY_ACK_REQUIRED''; end if;\n  rs:=public.build_finance_receipt_source(c.payment_id);\n  if rs is distinct from r.draft_snapshot_json then raise exception ''RECEIPT_SOURCE_CHANGED_REFRESH_REQUIRED''; end if;\n  perform 1 from public.finance_tax_invoice_source_coverages where tax_invoice_id=t.id order by invoice_item_id for update;\n  number:=public.generate_finance_document_no(''receipt_tax_invoice'',c.issue_date);\n  rs:=rs||jsonb_build_object(''receipt'',jsonb_build_object(''id'',r.id,''receipt_no'',number,''receipt_date'',r.receipt_date,''issued_at'',moment,\n    ''issued_by_user_id'',auth.uid(),''issued_by_name'',(select coalesce(nullif(full_name,''''),email) from public.user_profiles where id=auth.uid()),''replaces_receipt_id'',r.replaces_receipt_id,''combined_document_id'',c.id));\n  ts:=t.draft_snapshot_json||jsonb_build_object(''tax_point'',t.draft_snapshot_json->''tax_point''||to_jsonb(point),\n    ''document'',jsonb_build_object(''id'',t.id,''tax_invoice_no'',number,''issue_date'',t.issue_date,''issued_at'',moment,''issued_by_user_id'',auth.uid(),''combined_document_id'',c.id));\n  update public.finance_tax_invoice_source_coverages set status=''issued'' where tax_invoice_id=t.id;\n  update public.finance_receipts set status=''issued'',receipt_no=number,issued_snapshot_json=rs,issued_at=moment,issued_by_user_id=auth.uid(),updated_at=moment where id=r.id;\n  insert into public.finance_receipt_invoice_allocations(receipt_id,invoice_id,invoice_no,currency,cash_allocated,wht_allocated,source_snapshot_json)\n  select r.id,(value->>''invoice_id'')::uuid,value->>''invoice_no'',value->>''currency'',(value->>''cash_allocated'')::numeric,(value->>''wht_allocated'')::numeric,value\n    from jsonb_array_elements(rs->''invoices'');\n  update public.finance_tax_invoices set status=''issued'',tax_invoice_no=number,issued_snapshot_json=ts,issued_at=moment,issued_by_user_id=auth.uid(),updated_at=moment where id=t.id;\n  update public.finance_combined_documents set status=''issued'',combined_no=number,issued_at=moment,issued_by_user_id=auth.uid(),updated_at=moment,\n    issued_snapshot_json=jsonb_build_object(''schema_version'',1,''document_kind'',''receipt_tax_invoice'',''combined_document_id'',c.id,''combined_no'',number,\n      ''issued_at'',moment,''issue_date'',c.issue_date,''receipt'',rs,''tax_invoice'',ts) where id=c.id;\n  perform public.record_finance_receipt_audit(r.id,''issued'',jsonb_build_object(''receipt_no'',number,''combined_document_id'',c.id,''documentary_only'',true));\n  perform public.record_finance_tax_invoice_audit(t.id,''issued'',jsonb_build_object(''tax_invoice_no'',number,''combined_document_id'',c.id,''delayed_issue_acknowledged'',p_delayed_issue_acknowledged,''documentary_only'',true));\n  insert into public.finance_combined_document_audit_events(combined_document_id,event_type,event_payload_json,actor_user_id)\n  values(c.id,''issued'',jsonb_build_object(''combined_no'',number,''receipt_id'',r.id,''tax_invoice_id'',t.id,''external_receipt_checked'',true,''external_tax_checked'',true,\n    ''documentary_only'',true,''cash_created'',false,''ledger_created'',false,''compensation_created'',false,''revenue_allocation_created'',false),auth.uid());\n  return c.id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"issue_finance_receipt","owner":"postgres","config":["search_path=public"],"signature":"issue_finance_receipt(uuid,boolean,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.issue_finance_receipt(p_receipt_id uuid, p_acknowledged boolean, p_reviewed_snapshot_json jsonb DEFAULT NULL::jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_payment_id uuid; v_receipt public.finance_receipts%rowtype; v_snapshot jsonb; v_number text; v_now timestamptz := now();\nbegin\n  if not public.current_user_can_issue_finance_receipts() then raise exception ''RECEIPT_PERMISSION_DENIED''; end if;\n  if p_acknowledged is distinct from true then raise exception ''RECEIPT_ISSUE_ACK_REQUIRED''; end if;\n  select payment_id into v_payment_id from public.finance_receipts where id = p_receipt_id;\n  if not found then raise exception ''RECEIPT_NOT_FOUND''; end if;\n  perform 1 from public.finance_payments where id = v_payment_id for update;\n  -- Retry must not consult changed master data or allocate another number.\n  select * into v_receipt from public.finance_receipts where id = p_receipt_id;\n  if v_receipt.status = ''issued'' then return p_receipt_id; end if;\n  if v_receipt.combined_document_id is not null then raise exception ''DOCUMENT_USE_COMBINED_WORKFLOW''; end if;\n  perform public.assert_finance_document_route(v_payment_id,''receipt'');\n  if v_receipt.status <> ''draft'' then raise exception ''RECEIPT_DRAFT_REQUIRED''; end if;\n  v_snapshot := public.build_finance_receipt_source(v_payment_id);\n  select * into v_receipt from public.finance_receipts where id = p_receipt_id for update;\n  if v_snapshot is distinct from v_receipt.draft_snapshot_json then raise exception ''RECEIPT_SOURCE_CHANGED_REFRESH_REQUIRED''; end if;\n  if p_reviewed_snapshot_json is distinct from v_receipt.draft_snapshot_json then raise exception ''RECEIPT_REVIEW_REQUIRED''; end if;\n  v_number := public.generate_finance_document_no(''receipt'',v_receipt.receipt_date);\n  v_snapshot := v_snapshot || jsonb_build_object(''receipt'',jsonb_build_object(''id'',p_receipt_id,\n    ''receipt_no'',v_number,''receipt_date'',v_receipt.receipt_date,''issued_at'',v_now,''issued_by_user_id'',auth.uid(),\n    ''issued_by_name'',(select coalesce(nullif(full_name,''''),email) from public.user_profiles where id = auth.uid()),\n    ''replaces_receipt_id'',v_receipt.replaces_receipt_id));\n  update public.finance_receipts set status = ''issued'',receipt_no = v_number,issued_snapshot_json = v_snapshot,\n    issued_at = v_now,issued_by_user_id = auth.uid(),updated_at = v_now where id = p_receipt_id;\n  insert into public.finance_receipt_invoice_allocations(receipt_id,invoice_id,invoice_no,currency,\n    cash_allocated,wht_allocated,source_snapshot_json)\n  select p_receipt_id,(item->>''invoice_id'')::uuid,item->>''invoice_no'',item->>''currency'',\n    (item->>''cash_allocated'')::numeric,(item->>''wht_allocated'')::numeric,item\n  from jsonb_array_elements(v_snapshot->''invoices'') as entries(item);\n  perform public.record_finance_receipt_audit(p_receipt_id,''issued'',jsonb_build_object(\n    ''payment_id'',v_payment_id,''receipt_no'',v_number,''cash_amount'',v_receipt.cash_amount,\n    ''wht_amount'',v_receipt.wht_amount,''settlement_amount'',v_receipt.settlement_amount,\n    ''documentary_only'',true,''cash_created'',false,''ledger_created'',false,''compensation_created'',false,''tax_invoice_created'',false));\n  return p_receipt_id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"issue_finance_tax_invoice","owner":"postgres","config":["search_path=public"],"signature":"issue_finance_tax_invoice(uuid,jsonb,boolean,boolean)","definition":"CREATE OR REPLACE FUNCTION public.issue_finance_tax_invoice(p_tax_invoice_id uuid, p_reviewed_snapshot_json jsonb, p_acknowledged boolean, p_delayed_issue_acknowledged boolean)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare t public.finance_tax_invoices%rowtype; source jsonb; pid uuid; number text; event public.finance_tax_point_events%rowtype; snapshot jsonb; moment timestamptz:=now(); b text[];\nbegin\n  if not public.current_user_can_issue_finance_tax_invoices() then raise exception ''TAX_INVOICE_PERMISSION_DENIED''; end if;\n  if p_acknowledged is distinct from true then raise exception ''TAX_INVOICE_ISSUE_ACK_REQUIRED''; end if;\n  select payment_id into pid from public.finance_tax_invoices where id=p_tax_invoice_id;\n  perform 1 from public.finance_payments where id=pid for update;\n  select * into t from public.finance_tax_invoices where id=p_tax_invoice_id for update;\n  if not found then raise exception ''TAX_INVOICE_NOT_FOUND''; end if;\n  if t.status=''issued'' then return t.id; end if;\n  if t.combined_document_id is not null then raise exception ''DOCUMENT_USE_COMBINED_WORKFLOW''; end if;\n  perform public.assert_finance_document_route(pid,''tax_invoice'');\n  if t.status<>''draft'' then raise exception ''TAX_INVOICE_DRAFT_REQUIRED''; end if;\n  source:=public.build_finance_tax_invoice_source(pid);\n  if source is distinct from t.source_snapshot_json then raise exception ''TAX_INVOICE_SOURCE_CHANGED''; end if;\n  if p_reviewed_snapshot_json is distinct from t.draft_snapshot_json then raise exception ''TAX_INVOICE_STALE_REVIEW''; end if;\n  b:=public.finance_tax_invoice_issue_blockers(t.draft_snapshot_json);\n  if cardinality(b)>0 then raise exception using message=b[1]; end if;\n  select * into strict event from public.finance_tax_point_events where tax_invoice_id=t.id;\n  if event.approved_at is null then raise exception ''TAX_INVOICE_TAX_POINT_APPROVAL_REQUIRED''; end if;\n  if t.issue_date<event.occurred_on or t.issue_date>(moment at time zone ''Asia/Bangkok'')::date then raise exception ''TAX_INVOICE_ISSUE_DATE_INVALID''; end if;\n  if t.issue_date>event.occurred_on and p_delayed_issue_acknowledged is distinct from true then raise exception ''TAX_INVOICE_DELAY_ACK_REQUIRED''; end if;\n  perform 1 from public.finance_tax_invoice_source_coverages where tax_invoice_id=t.id and status=''reserved'' for update;\n  number:=public.generate_finance_document_no(''tax_invoice'',t.issue_date);\n  snapshot:=t.draft_snapshot_json||jsonb_build_object(''tax_point'',t.draft_snapshot_json->''tax_point''||to_jsonb(event),\n    ''document'',jsonb_build_object(''id'',t.id,''tax_invoice_no'',number,''issue_date'',t.issue_date,''issued_at'',moment,\n      ''issued_by_user_id'',auth.uid(),''issued_by_name'',(select coalesce(nullif(full_name,''''),email) from public.user_profiles where id=auth.uid())));\n  update public.finance_tax_invoice_source_coverages set status=''issued'' where tax_invoice_id=t.id;\n  update public.finance_tax_invoices set status=''issued'',tax_invoice_no=number,issued_at=moment,issued_by_user_id=auth.uid(),issued_snapshot_json=snapshot,updated_at=moment where id=t.id;\n  perform public.record_finance_tax_invoice_audit(t.id,''issued'',jsonb_build_object(''tax_invoice_no'',number,''tax_point_date'',event.occurred_on,''issue_date'',t.issue_date,\n    ''delayed_issue_acknowledged'',t.issue_date>event.occurred_on and p_delayed_issue_acknowledged,''decisions'',t.decisions_json,\n    ''documentary_only'',true,''payment_changed'',false,''cash_created'',false,''ledger_created'',false,''compensation_created'',false,''revenue_allocation_created'',false,''receipt_changed'',false));\n  return t.id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres}","name":"money_allocation_decisions","owner":"postgres","config":["search_path=public"],"signature":"money_allocation_decisions(jsonb,jsonb,boolean)","definition":"CREATE OR REPLACE FUNCTION public.money_allocation_decisions(p_source jsonb, p_choices jsonb, p_complete boolean)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare l jsonb; c jsonb; result jsonb:=''[]'';\nbegin\n if jsonb_typeof(p_choices) is distinct from ''array'' then raise exception ''MONEY_ALLOCATION_CHOICES_INVALID''; end if;\n if jsonb_array_length(p_choices)<>jsonb_array_length(p_source->''lines'')\n   or exists(select 1 from jsonb_array_elements(p_choices) x where jsonb_typeof(x)<>''object'')\n then raise exception ''MONEY_ALLOCATION_CHOICES_INVALID''; end if;\n for l in select value from jsonb_array_elements(p_source->''lines'') loop\n  if (select count(*) from jsonb_array_elements(p_choices) x where x->>''invoice_item_id''=l->>''invoice_item_id'')<>1\n  then raise exception ''MONEY_ALLOCATION_CHOICES_INVALID''; end if;\n  select value into c from jsonb_array_elements(p_choices) where value->>''invoice_item_id''=l->>''invoice_item_id'';\n  if exists(select 1 from jsonb_object_keys(c) k where k not in (''invoice_item_id'',''category'',''reason''))\n    or coalesce(c->>''category'','''') not in (''unallocated'',''company_revenue'',''pass_through'',''disbursement'',''client_money'',''other'')\n    or length(coalesce(c->>''reason'',''''))>2000\n  then raise exception ''MONEY_ALLOCATION_CHOICES_INVALID''; end if;\n  if p_complete and (c->>''category''=''unallocated'' or nullif(btrim(c->>''reason''),'''') is null)\n  then raise exception ''MONEY_ALLOCATION_REVIEW_REQUIRED''; end if;\n  result:=result||jsonb_build_array(jsonb_build_object(''invoice_item_id'',l->>''invoice_item_id'',''category'',c->>''category'',''reason'',btrim(coalesce(c->>''reason'',''''))));\n end loop;\n return result;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"money_allocation_lock","owner":"postgres","config":["search_path=public"],"signature":"money_allocation_lock(uuid)","definition":"CREATE OR REPLACE FUNCTION public.money_allocation_lock(p_payment_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n perform 1 from public.finance_payments where id=p_payment_id for update;\n perform 1 from public.finance_invoices where id in (select invoice_id from public.finance_payment_effective_invoice_allocations where payment_id=p_payment_id) order by id for update;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"money_allocation_source","owner":"postgres","config":["search_path=public"],"signature":"money_allocation_source(uuid)","definition":"CREATE OR REPLACE FUNCTION public.money_allocation_source(p_payment_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare p public.finance_payments%rowtype; i public.finance_invoices%rowtype; a record; l jsonb; lines jsonb;\n w public.finance_payment_wht_components%rowtype; wht numeric; cash numeric;\n invoices jsonb:=''[]''; components jsonb:=''[]''; blockers jsonb:=''[]''; corrections jsonb;\n invoice_components jsonb; invoice_blocked boolean; invoice_wht numeric; expected_basis jsonb;\n total_cash numeric:=0; total_wht numeric:=0; total_base numeric:=0; total_vat numeric:=0;\nbegin\n select * into p from public.finance_payments where id=p_payment_id;\n if p.id is null then raise exception ''MONEY_ALLOCATION_PAYMENT_MISSING''; end if;\n if p.status<>''confirmed'' then blockers:=blockers||''\"payment_not_confirmed\"''::jsonb; end if;\n for a in select * from public.finance_payment_effective_invoice_allocations where payment_id=p.id order by invoice_id loop\n  select * into strict i from public.finance_invoices where id=a.invoice_id;\n  select coalesce(jsonb_agg(jsonb_build_object(''id'',c.id,''mode'',c.correction_mode,''issued_at'',c.issued_at) order by c.id),''[]'') into corrections\n   from public.finance_tax_document_corrections c join public.finance_tax_invoices t on t.id=c.original_tax_invoice_id\n   where t.invoice_id=i.id and c.status=''issued'' and c.correction_mode<>''replacement_copy'';\n  invoices:=invoices||jsonb_build_array(jsonb_build_object(''invoice_id'',i.id,''invoice_no'',i.invoice_no,\n   ''status'',i.document_status,''cash'',a.effective_cash_allocated,''wht'',a.effective_wht_credit_allocated,\n   ''settlement'',a.effective_settlement_total,''gross'',i.total_amount,''issued_snapshot'',i.issued_snapshot_json,''corrections'',corrections));\n  total_cash:=total_cash+a.effective_cash_allocated; total_wht:=total_wht+a.effective_wht_credit_allocated;\n  if i.document_status<>''issued'' or i.client_id is distinct from p.client_id or i.currency is distinct from p.currency then\n   blockers:=blockers||''\"invoice_context_invalid\"''::jsonb; continue;\n  end if;\n  if corrections<>''[]'' then blockers:=blockers||''\"corrected_document_review_required\"''::jsonb; continue; end if;\n  if a.effective_settlement_total<>i.total_amount then blockers:=blockers||''\"partial_line_evidence_missing\"''::jsonb; continue; end if;\n  begin\n   if i.issued_snapshot_json#>>''{invoice,id}'' is distinct from i.id::text\n     or i.issued_snapshot_json#>>''{invoice,currency}'' is distinct from i.currency\n     or i.issued_snapshot_json#>>''{invoice,document_status}'' is distinct from ''issued''\n     or (i.issued_snapshot_json#>>''{invoice,total_amount}'')::numeric is distinct from i.total_amount\n     or (i.issued_snapshot_json#>>''{invoice,amount_before_vat}'')::numeric is distinct from i.amount_before_vat\n     or (i.issued_snapshot_json#>>''{invoice,vat_amount}'')::numeric is distinct from i.vat_amount\n   then raise exception ''SOURCE_INVALID''; end if;\n   lines:=public.finance_document_invoice_lines(i.id);\n   if exists(select 1 from jsonb_array_elements(lines) x where (x->>''amount_before_vat'')::numeric<=0\n     or (x->>''vat_amount'')::numeric<0 or (x->>''line_total'')::numeric<=0\n     or x->>''source_state'' is distinct from ''active''\n     or exists(select 1 from (values(''amount_before_vat''),(''vat_amount''),(''line_total'')) k(name)\n       where jsonb_typeof(x->k.name) is distinct from ''number'' or (x->>k.name)::numeric<>round((x->>k.name)::numeric,2))) then raise exception ''SOURCE_INVALID''; end if;\n  exception when others then blockers:=blockers||''\"frozen_lines_invalid\"''::jsonb; continue;\n  end;\n  invoice_components:=''[]''; invoice_wht:=0; invoice_blocked:=false;\n  for l in select value from jsonb_array_elements(lines) order by value->>''id'' loop\n   select * into w from public.finance_payment_wht_components where payment_id=p.id and invoice_id=i.id and invoice_item_id=(l->>''id'')::uuid;\n   wht:=coalesce(w.calculated_wht_amount,0);\n   if w.id is not null then\n    begin\n     if w.calculation_rule=''single_line_full_invoice_v1'' then\n      expected_basis:=public.finance_invoice_wht_basis_v1(i.issued_snapshot_json);\n      if w.basis_snapshot_json is distinct from expected_basis or p.wht_calculation_mode is distinct from ''rate'' then invoice_blocked:=true; end if;\n     else\n      select value into expected_basis from jsonb_array_elements(public.finance_invoice_wht_lines_v2(i.issued_snapshot_json)) x\n       where value->>''invoice_item_id''=l->>''id'';\n      if w.basis_snapshot_json->''basis'' is distinct from expected_basis or p.wht_calculation_mode is distinct from ''line_review''\n        or w.basis_snapshot_json->>''applicability'' not in (''applies'',''does_not_apply'') then invoice_blocked:=true; end if;\n     end if;\n     if (wht>0 and (w.rate_percent is null or wht<>round(w.base_amount*w.rate_percent/100,2)))\n       or (wht=0 and (w.rate_percent is not null or w.basis_snapshot_json->>''applicability'' is distinct from ''does_not_apply''))\n     then invoice_blocked:=true; end if;\n    exception when others then invoice_blocked:=true;\n    end;\n   end if;\n   if (a.effective_wht_credit_allocated>0 and w.id is null and p.wht_calculation_mode=''line_review'')\n     or (w.id is not null and (w.base_amount is distinct from (l->>''amount_before_vat'')::numeric\n       or (w.calculation_rule=''single_line_full_invoice_v1'' and (w.basis_snapshot_json->>''invoice_item_id'' is distinct from l->>''id''\n         or w.basis_snapshot_json->>''invoice_id'' is distinct from i.id::text))\n       or (w.calculation_rule=''line_review_full_invoice_v2'' and (w.basis_snapshot_json#>>''{basis,invoice_item_id}'' is distinct from l->>''id''\n         or w.basis_snapshot_json#>>''{basis,invoice_id}'' is distinct from i.id::text)))) then invoice_blocked:=true; end if;\n   cash:=(l->>''line_total'')::numeric-wht; invoice_wht:=invoice_wht+wht;\n   if cash<0 then invoice_blocked:=true; end if;\n   if l#>>''{resolved_vat_treatment,treatment}'' is null or l#>>''{resolved_vat_treatment,treatment}''=''unknown''\n   then blockers:=blockers||''\"vat_evidence_unknown\"''::jsonb; end if;\n   invoice_components:=invoice_components||jsonb_build_array(jsonb_build_object(''invoice_id'',i.id,''invoice_no'',i.invoice_no,\n    ''invoice_item_id'',l->>''id'',''description'',l->>''description'',''base'',(l->>''amount_before_vat'')::numeric,\n    ''vat'',(l->>''vat_amount'')::numeric,''settlement'',(l->>''line_total'')::numeric,''cash'',cash,''wht'',wht,\n    ''vat_treatment'',l->''resolved_vat_treatment'',''source_item'',l,''wht_evidence'',case when w.id is null then null else to_jsonb(w) end));\n  end loop;\n  if invoice_wht<>a.effective_wht_credit_allocated or invoice_blocked\n    or exists(select 1 from public.finance_payment_wht_components c where c.payment_id=p.id and c.invoice_id=i.id\n      and not exists(select 1 from jsonb_array_elements(lines) x where x->>''id''=c.invoice_item_id::text))\n  then blockers:=blockers||''\"wht_line_evidence_missing\"''::jsonb; continue; end if;\n  components:=components||invoice_components; total_base:=total_base+i.amount_before_vat; total_vat:=total_vat+i.vat_amount;\n end loop;\n if total_cash<>p.cash_amount or total_wht<>p.wht_amount or jsonb_array_length(invoices)=0\n then blockers:=blockers||''\"settlement_evidence_invalid\"''::jsonb; end if;\n if exists(select 1 from public.finance_payment_wht_components c where c.payment_id=p.id and not exists(\n   select 1 from jsonb_array_elements(invoices) x where x->>''invoice_id''=c.invoice_id::text))\n then blockers:=blockers||''\"wht_line_evidence_missing\"''::jsonb; end if;\n return jsonb_build_object(''schema_version'',1,''payment'',jsonb_build_object(''id'',p.id,''status'',p.status,''currency'',p.currency,\n  ''cash'',p.cash_amount,''wht'',p.wht_amount,''settlement'',p.settlement_amount,''received_on'',p.received_on,\n  ''receiving_bank_account_id'',p.receiving_bank_account_id,''wht_calculation_mode'',p.wht_calculation_mode),\n  ''invoices'',invoices,''lines'',components,''proven_base'',total_base,''proven_vat'',total_vat,\n  ''unallocated_settlement'',p.settlement_amount-total_base-total_vat,\n  ''blockers'',(select coalesce(jsonb_agg(distinct value order by value),''[]'') from jsonb_array_elements(blockers)));\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"prepare_finance_document_tax_draft","owner":"postgres","config":["search_path=public"],"signature":"prepare_finance_document_tax_draft(uuid)","definition":"CREATE OR REPLACE FUNCTION public.prepare_finance_document_tax_draft(p_payment_id uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare source jsonb; item jsonb; id uuid; point_id uuid; component_id uuid; date_today date:=(now() at time zone ''Asia/Bangkok'')::date;\nbegin\n  source:=public.build_finance_document_tax_source(p_payment_id);\n  insert into public.finance_tax_invoices(payment_id,invoice_id,client_id,issue_date,source_snapshot_json,draft_snapshot_json,created_by_user_id)\n  values(p_payment_id,(source #>> ''{invoice,id}'')::uuid,(source #>> ''{customer,id}'')::uuid,date_today,source,\n    public.finance_tax_invoice_draft_snapshot(source,''{}'',date_today),auth.uid()) returning finance_tax_invoices.id into id;\n  insert into public.finance_tax_point_events(tax_invoice_id,event_type,occurred_on,evidence_json)\n  values(id,''payment_received'',(source #>> ''{payment,received_on}'')::date,jsonb_build_object(''payment'',source->''payment'',''policy_version'',''vp_v1''))\n  returning finance_tax_point_events.id into point_id;\n  for item in select value from jsonb_array_elements(source->''invoice_items'') loop\n    insert into public.finance_tax_invoice_items(tax_invoice_id,invoice_item_id,amount_before_vat,vat_amount,total_amount,source_snapshot_json)\n    values(id,(item->>''id'')::uuid,(item->>''amount_before_vat'')::numeric,(item->>''vat_amount'')::numeric,(item->>''line_total'')::numeric,item)\n    returning finance_tax_invoice_items.id into component_id;\n    insert into public.finance_tax_invoice_source_coverages(tax_invoice_id,tax_invoice_item_id,invoice_item_id,tax_point_event_id,status,amount_before_vat,vat_amount,total_amount,source_snapshot_json)\n    values(id,component_id,(item->>''id'')::uuid,point_id,''reserved'',(item->>''amount_before_vat'')::numeric,(item->>''vat_amount'')::numeric,(item->>''line_total'')::numeric,\n      jsonb_build_object(''invoice_id'',source #> ''{invoice,id}'',''payment_id'',p_payment_id,''invoice_item'',item,''rule'',''explicit_full_line_v2''));\n  end loop;\n  perform public.record_finance_tax_invoice_audit(id,''draft_created'',jsonb_build_object(''payment_id'',p_payment_id,''number_allocated'',false,''contract_version'',2));\n  return id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"receipt_cancel_pre040","owner":"postgres","config":["search_path=public"],"signature":"receipt_cancel_pre040(uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.receipt_cancel_pre040(p_receipt_id uuid, p_reason text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_payment_id uuid; v_receipt public.finance_receipts%rowtype;\nbegin\n  if not public.current_user_can_manage_finance_receipts() then raise exception ''RECEIPT_PERMISSION_DENIED''; end if;\n  if nullif(btrim(p_reason),'''') is null or length(p_reason) > 2000 then raise exception ''RECEIPT_REASON_REQUIRED''; end if;\n  select payment_id into v_payment_id from public.finance_receipts where id = p_receipt_id;\n  if not found then raise exception ''RECEIPT_NOT_FOUND''; end if;\n  perform 1 from public.finance_payments where id = v_payment_id for update;\n  select * into v_receipt from public.finance_receipts where id = p_receipt_id for update;\n  if v_receipt.status = ''cancelled'' then return p_receipt_id; end if;\n  if v_receipt.status <> ''draft'' then raise exception ''RECEIPT_DRAFT_REQUIRED''; end if;\n  update public.finance_receipts set status = ''cancelled'',cancelled_at = now(),cancelled_by_user_id = auth.uid(),\n    cancel_reason = btrim(p_reason),updated_at = now() where id = p_receipt_id;\n  perform public.record_finance_receipt_audit(p_receipt_id,''cancelled'',jsonb_build_object(''reason'',btrim(p_reason),''payment_changed'',false));\n  return p_receipt_id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"receipt_create_pre040","owner":"postgres","config":["search_path=public"],"signature":"receipt_create_pre040(uuid,boolean)","definition":"CREATE OR REPLACE FUNCTION public.receipt_create_pre040(p_payment_id uuid, p_external_receipt_checked boolean DEFAULT false)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n  v_payment public.finance_payments%rowtype;\n  v_id uuid;\n  v_predecessor uuid;\n  v_snapshot jsonb;\nbegin\n  if not public.current_user_can_manage_finance_receipts() then raise exception ''RECEIPT_PERMISSION_DENIED''; end if;\n  select * into v_payment from public.finance_payments where id = p_payment_id for update;\n  if not found or v_payment.status <> ''confirmed'' then raise exception ''RECEIPT_CONFIRMED_PAYMENT_REQUIRED''; end if;\n  select id into v_id from public.finance_receipts where payment_id = p_payment_id and status in (''draft'',''issued'');\n  if v_id is not null then return v_id; end if;\n  if p_external_receipt_checked is distinct from true then raise exception ''RECEIPT_EXTERNAL_COVERAGE_ACK_REQUIRED''; end if;\n  select id into v_predecessor from public.finance_receipts where payment_id = p_payment_id and status = ''voided''\n    order by issued_at desc,id desc limit 1;\n  v_snapshot := public.build_finance_receipt_source(p_payment_id);\n  insert into public.finance_receipts(payment_id,client_id,receipt_date,currency,cash_amount,wht_amount,\n    draft_snapshot_json,replaces_receipt_id,external_receipt_checked_at,external_receipt_checked_by_user_id,created_by_user_id)\n  values (p_payment_id,v_payment.client_id,v_payment.received_on,v_payment.currency,v_payment.cash_amount,v_payment.wht_amount,\n    v_snapshot,v_predecessor,now(),auth.uid(),auth.uid()) returning id into v_id;\n  perform public.record_finance_receipt_audit(v_id,''draft_created'',jsonb_build_object(\n    ''payment_id'',p_payment_id,''external_receipt_checked'',true,''replaces_receipt_id'',v_predecessor));\n  return v_id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"receipt_refresh_pre040","owner":"postgres","config":["search_path=public"],"signature":"receipt_refresh_pre040(uuid)","definition":"CREATE OR REPLACE FUNCTION public.receipt_refresh_pre040(p_receipt_id uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_payment_id uuid; v_receipt public.finance_receipts%rowtype; v_snapshot jsonb;\nbegin\n  if not public.current_user_can_manage_finance_receipts() then raise exception ''RECEIPT_PERMISSION_DENIED''; end if;\n  select payment_id into v_payment_id from public.finance_receipts where id = p_receipt_id;\n  if not found then raise exception ''RECEIPT_NOT_FOUND''; end if;\n  v_snapshot := public.build_finance_receipt_source(v_payment_id);\n  select * into v_receipt from public.finance_receipts where id = p_receipt_id for update;\n  if v_receipt.status <> ''draft'' then raise exception ''RECEIPT_DRAFT_REQUIRED''; end if;\n  if v_snapshot = v_receipt.draft_snapshot_json then return p_receipt_id; end if;\n  update public.finance_receipts set draft_snapshot_json = v_snapshot,\n    receipt_date = (v_snapshot #>> ''{payment,received_on}'')::date,\n    currency = v_snapshot #>> ''{payment,currency}'',cash_amount = (v_snapshot #>> ''{payment,cash_amount}'')::numeric,\n    wht_amount = (v_snapshot #>> ''{payment,wht_amount}'')::numeric,updated_at = now() where id = p_receipt_id;\n  perform public.record_finance_receipt_audit(p_receipt_id,''draft_refreshed'',jsonb_build_object(''payment_id'',v_payment_id));\n  return p_receipt_id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"record_finance_receipt_audit","owner":"postgres","config":["search_path=public"],"signature":"record_finance_receipt_audit(uuid,text,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.record_finance_receipt_audit(p_receipt_id uuid, p_event text, p_payload jsonb)\n RETURNS void\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  insert into public.finance_receipt_audit_events(receipt_id,event_type,event_payload_json,actor_user_id)\n  values (p_receipt_id,p_event,p_payload,auth.uid());\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"record_finance_tax_invoice_audit","owner":"postgres","config":["search_path=public"],"signature":"record_finance_tax_invoice_audit(uuid,text,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.record_finance_tax_invoice_audit(p_id uuid, p_event text, p_payload jsonb)\n RETURNS void\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n  insert into public.finance_tax_invoice_audit_events(tax_invoice_id,event_type,event_payload_json,actor_user_id)\n  values(p_id,p_event,p_payload,auth.uid());\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"refresh_finance_combined_document_draft","owner":"postgres","config":["search_path=public"],"signature":"refresh_finance_combined_document_draft(uuid,timestamp with time zone)","definition":"CREATE OR REPLACE FUNCTION public.refresh_finance_combined_document_draft(p_combined_id uuid, p_expected_updated_at timestamp with time zone)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare c public.finance_combined_documents%rowtype; t public.finance_tax_invoices%rowtype;\nbegin\n  if not public.current_user_can_manage_combined_documents() then raise exception ''DOCUMENT_PERMISSION_DENIED''; end if;\n  perform 1 from public.finance_payments where id=(select payment_id from public.finance_combined_documents where id=p_combined_id) for update;\n  select * into strict c from public.finance_combined_documents where id=p_combined_id for update;\n  if c.status<>''draft'' then raise exception ''DOCUMENT_DRAFT_REQUIRED''; end if;\n  if c.updated_at is distinct from p_expected_updated_at then raise exception ''DOCUMENT_STALE_REVIEW''; end if;\n  select * into strict t from public.finance_tax_invoices where id=c.tax_invoice_id;\n  perform public.receipt_refresh_pre040(c.receipt_id);\n  perform public.tax_refresh_pre040(t.id,t.updated_at);\n  select * into strict t from public.finance_tax_invoices where id=c.tax_invoice_id;\n  if (t.source_snapshot_json,t.draft_snapshot_json,t.decisions_json) is not distinct from\n    (c.source_snapshot_json,c.draft_snapshot_json,c.decisions_json) then return c.id; end if;\n  update public.finance_combined_documents set source_snapshot_json=t.source_snapshot_json,draft_snapshot_json=t.draft_snapshot_json,\n    decisions_json=t.decisions_json,updated_at=clock_timestamp() where id=c.id;\n  insert into public.finance_combined_document_audit_events(combined_document_id,event_type,event_payload_json,actor_user_id)\n  values(c.id,''draft_refreshed'',jsonb_build_object(''approvals_reset'',true),auth.uid());\n  return c.id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"refresh_finance_receipt_draft","owner":"postgres","config":["search_path=public"],"signature":"refresh_finance_receipt_draft(uuid)","definition":"CREATE OR REPLACE FUNCTION public.refresh_finance_receipt_draft(p_receipt_id uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_payment_id uuid; v_receipt public.finance_receipts%rowtype; v_snapshot jsonb;\nbegin\n  if not public.current_user_can_manage_finance_receipts() then raise exception ''RECEIPT_PERMISSION_DENIED''; end if;\n  select payment_id into v_payment_id from public.finance_receipts where id = p_receipt_id;\n  if not found then raise exception ''RECEIPT_NOT_FOUND''; end if;\n  v_snapshot := public.build_finance_receipt_source(v_payment_id);\n  select * into v_receipt from public.finance_receipts where id = p_receipt_id for update;\n  if v_receipt.combined_document_id is not null then raise exception ''DOCUMENT_USE_COMBINED_WORKFLOW''; end if;\n  if v_receipt.status <> ''draft'' then raise exception ''RECEIPT_DRAFT_REQUIRED''; end if;\n  if v_snapshot = v_receipt.draft_snapshot_json then return p_receipt_id; end if;\n  update public.finance_receipts set draft_snapshot_json = v_snapshot,\n    receipt_date = (v_snapshot #>> ''{payment,received_on}'')::date,\n    currency = v_snapshot #>> ''{payment,currency}'',cash_amount = (v_snapshot #>> ''{payment,cash_amount}'')::numeric,\n    wht_amount = (v_snapshot #>> ''{payment,wht_amount}'')::numeric,updated_at = now() where id = p_receipt_id;\n  perform public.record_finance_receipt_audit(p_receipt_id,''draft_refreshed'',jsonb_build_object(''payment_id'',v_payment_id));\n  return p_receipt_id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"refresh_finance_tax_invoice_draft","owner":"postgres","config":["search_path=public"],"signature":"refresh_finance_tax_invoice_draft(uuid,timestamp with time zone)","definition":"CREATE OR REPLACE FUNCTION public.refresh_finance_tax_invoice_draft(p_tax_invoice_id uuid, p_expected_updated_at timestamp with time zone)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare t public.finance_tax_invoices%rowtype; source jsonb; pid uuid;\nbegin\n  if not public.current_user_can_manage_finance_tax_invoices() then raise exception ''TAX_INVOICE_PERMISSION_DENIED''; end if;\n  select payment_id into pid from public.finance_tax_invoices where id=p_tax_invoice_id;\n  source:=public.build_finance_tax_invoice_source(pid);\n  select * into t from public.finance_tax_invoices where id=p_tax_invoice_id for update;\n  if t.combined_document_id is not null then raise exception ''DOCUMENT_USE_COMBINED_WORKFLOW''; end if;\n  if not found or t.status<>''draft'' then raise exception ''TAX_INVOICE_DRAFT_REQUIRED''; end if;\n  if t.updated_at is distinct from p_expected_updated_at then raise exception ''TAX_INVOICE_STALE_REVIEW''; end if;\n  if source->''invoice_item'' is distinct from t.source_snapshot_json->''invoice_item''\n    or source->''payment'' is distinct from t.source_snapshot_json->''payment''\n  then raise exception ''TAX_INVOICE_SOURCE_CHANGED''; end if;\n  if source=t.source_snapshot_json then return t.id; end if;\n  update public.finance_tax_point_events set approved_at=null,approved_by_user_id=null where tax_invoice_id=t.id;\n  update public.finance_tax_invoices set source_snapshot_json=source,decisions_json=''{}'',\n    draft_snapshot_json=public.finance_tax_invoice_draft_snapshot(source,''{}'',t.issue_date),updated_at=clock_timestamp() where id=t.id;\n  perform public.record_finance_tax_invoice_audit(t.id,''draft_refreshed'',jsonb_build_object(''approvals_reset'',true));\n  return t.id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"save_finance_combined_document_draft","owner":"postgres","config":["search_path=public"],"signature":"save_finance_combined_document_draft(uuid,date,jsonb,timestamp with time zone)","definition":"CREATE OR REPLACE FUNCTION public.save_finance_combined_document_draft(p_combined_id uuid, p_issue_date date, p_decisions_json jsonb, p_expected_updated_at timestamp with time zone)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare c public.finance_combined_documents%rowtype; t public.finance_tax_invoices%rowtype;\nbegin\n  if not public.current_user_can_manage_combined_documents() then raise exception ''DOCUMENT_PERMISSION_DENIED''; end if;\n  perform 1 from public.finance_payments where id=(select payment_id from public.finance_combined_documents where id=p_combined_id) for update;\n  select * into strict c from public.finance_combined_documents where id=p_combined_id for update;\n  if c.status<>''draft'' then raise exception ''DOCUMENT_DRAFT_REQUIRED''; end if;\n  if c.updated_at is distinct from p_expected_updated_at then raise exception ''DOCUMENT_STALE_REVIEW''; end if;\n  select * into strict t from public.finance_tax_invoices where id=c.tax_invoice_id;\n  perform public.tax_save_pre040(t.id,p_issue_date,p_decisions_json,t.updated_at);\n  select * into strict t from public.finance_tax_invoices where id=c.tax_invoice_id;\n  update public.finance_combined_documents set issue_date=p_issue_date,decisions_json=p_decisions_json,draft_snapshot_json=t.draft_snapshot_json,updated_at=clock_timestamp() where id=c.id;\n  insert into public.finance_combined_document_audit_events(combined_document_id,event_type,event_payload_json,actor_user_id)\n  values(c.id,''draft_saved'',jsonb_build_object(''decisions'',p_decisions_json,''issue_date'',p_issue_date),auth.uid());\n  return c.id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"save_finance_tax_invoice_draft","owner":"postgres","config":["search_path=public"],"signature":"save_finance_tax_invoice_draft(uuid,date,jsonb,timestamp with time zone)","definition":"CREATE OR REPLACE FUNCTION public.save_finance_tax_invoice_draft(p_tax_invoice_id uuid, p_issue_date date, p_decisions_json jsonb, p_expected_updated_at timestamp with time zone)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare t public.finance_tax_invoices%rowtype; snapshot jsonb; pid uuid;\nbegin\n  if not public.current_user_can_manage_finance_tax_invoices() then raise exception ''TAX_INVOICE_PERMISSION_DENIED''; end if;\n  select payment_id into pid from public.finance_tax_invoices where id=p_tax_invoice_id;\n  perform 1 from public.finance_payments where id=pid for update;\n  select * into t from public.finance_tax_invoices where id=p_tax_invoice_id for update;\n  if t.combined_document_id is not null then raise exception ''DOCUMENT_USE_COMBINED_WORKFLOW''; end if;\n  if not found or t.status<>''draft'' then raise exception ''TAX_INVOICE_DRAFT_REQUIRED''; end if;\n  if t.updated_at is distinct from p_expected_updated_at then raise exception ''TAX_INVOICE_STALE_REVIEW''; end if;\n  if p_issue_date is null or p_issue_date>(now() at time zone ''Asia/Bangkok'')::date\n    or p_issue_date<(t.source_snapshot_json #>> ''{payment,received_on}'')::date then raise exception ''TAX_INVOICE_ISSUE_DATE_INVALID''; end if;\n  snapshot:=public.finance_tax_invoice_draft_snapshot(t.source_snapshot_json,p_decisions_json,p_issue_date);\n  if snapshot=t.draft_snapshot_json and p_decisions_json=t.decisions_json then return t.id; end if;\n  update public.finance_tax_point_events set approved_at=case when p_decisions_json->''no_earlier_event''=''true''::jsonb then now() end,\n    approved_by_user_id=case when p_decisions_json->''no_earlier_event''=''true''::jsonb then auth.uid() end where tax_invoice_id=t.id;\n  update public.finance_tax_invoices set issue_date=p_issue_date,decisions_json=p_decisions_json,draft_snapshot_json=snapshot,updated_at=clock_timestamp() where id=t.id;\n  perform public.record_finance_tax_invoice_audit(t.id,''draft_saved'',jsonb_build_object(''previous_decisions'',t.decisions_json,''decisions'',p_decisions_json,''issue_date'',p_issue_date));\n  return t.id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres}","name":"tax_blockers_pre040","owner":"postgres","config":["search_path=public"],"signature":"tax_blockers_pre040(jsonb)","definition":"CREATE OR REPLACE FUNCTION public.tax_blockers_pre040(p_snapshot jsonb)\n RETURNS text[]\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare b text[]:=''{}''; s jsonb:=p_snapshot->''seller''; c jsonb:=p_snapshot->''customer''; item jsonb:=p_snapshot->''invoice_item'';\nbegin\n  if nullif(btrim(s->>''company_name_th''),'''') is null or nullif(btrim(s->>''address_th''),'''') is null\n    or coalesce(s->>''tax_id'','''')!~''^[0-9]{13}$'' or s->>''branch_type'' is distinct from ''head_office''\n    or s->>''branch_code'' is distinct from ''00000'' or s->''vat_registered'' is distinct from ''true''::jsonb\n  then b:=array_append(b,''TAX_INVOICE_SELLER_IDENTITY_REQUIRED''); end if;\n  if nullif(btrim(c->>''name''),'''') is null or nullif(btrim(c->>''address''),'''') is null\n    or jsonb_typeof(c->''vat_registered'') is distinct from ''boolean''\n    or (c->''vat_registered''=''true''::jsonb and (coalesce(c->>''tax_id'','''')!~''^[0-9]{13}$''\n      or coalesce(c->>''branch_type'','''') not in (''head_office'',''branch'') or coalesce(c->>''branch_code'','''')!~''^[0-9]{5}$''\n      or (c->>''branch_type''=''branch'' and c->>''branch_code''=''00000'')))\n    or ((nullif(btrim(p_snapshot #>> ''{invoice_snapshot,invoice,customer_billing_address}''),'''') is null\n      and nullif(btrim(p_snapshot #>> ''{invoice_snapshot,customer,address}''),'''') is null)\n      and nullif(btrim(c->>''supplemental_evidence''),'''') is null)\n    or (c->''vat_registered''=''true''::jsonb and\n      (nullif(btrim(p_snapshot #>> ''{invoice_snapshot,customer,tax_id}''),'''') is null\n       or lower(coalesce(p_snapshot #>> ''{invoice_snapshot,customer,branch}'','''')) not in (''สำนักงานใหญ่'',''head office'',''00000''))\n      and nullif(btrim(c->>''supplemental_evidence''),'''') is null)\n  then b:=array_append(b,''TAX_INVOICE_CUSTOMER_IDENTITY_REQUIRED''); end if;\n  if not coalesce((p_snapshot->>''tax_treatment''=''standard_rated'' and item->''vat_applicable''=''true''::jsonb\n      and (item->>''vat_rate'')::numeric>0 and (item->>''vat_amount'')::numeric>0)\n    or (p_snapshot->>''tax_treatment''=''zero_rated'' and item->''vat_applicable''=''true''::jsonb\n      and (item->>''vat_rate'')::numeric=0 and (item->>''vat_amount'')::numeric=0\n      and nullif(btrim(p_snapshot->>''treatment_reason''),'''') is not null),false)\n  then b:=array_append(b,''TAX_INVOICE_VAT_TREATMENT_UNRESOLVED''); end if;\n  if p_snapshot #> ''{tax_point,no_earlier_event_acknowledged}'' is distinct from ''true''::jsonb\n  then b:=array_append(b,''TAX_INVOICE_TAX_POINT_APPROVAL_REQUIRED''); end if;\n  if p_snapshot->''external_coverage_checked'' is distinct from ''true''::jsonb\n  then b:=array_append(b,''TAX_INVOICE_EXTERNAL_COVERAGE_CHECK_REQUIRED''); end if;\n  return b;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"tax_cancel_pre040","owner":"postgres","config":["search_path=public"],"signature":"tax_cancel_pre040(uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.tax_cancel_pre040(p_tax_invoice_id uuid, p_reason text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare t public.finance_tax_invoices%rowtype; pid uuid;\nbegin\n  if not public.current_user_can_manage_finance_tax_invoices() then raise exception ''TAX_INVOICE_PERMISSION_DENIED''; end if;\n  if nullif(btrim(p_reason),'''') is null or length(p_reason)>2000 then raise exception ''TAX_INVOICE_REASON_REQUIRED''; end if;\n  select payment_id into pid from public.finance_tax_invoices where id=p_tax_invoice_id;\n  perform 1 from public.finance_payments where id=pid for update;\n  select * into t from public.finance_tax_invoices where id=p_tax_invoice_id for update;\n  if not found then raise exception ''TAX_INVOICE_NOT_FOUND''; end if;\n  if t.status=''cancelled'' then return t.id; end if;\n  if t.status<>''draft'' then raise exception ''TAX_INVOICE_DRAFT_REQUIRED''; end if;\n  update public.finance_tax_invoice_source_coverages set status=''released'' where tax_invoice_id=t.id;\n  update public.finance_tax_invoices set status=''cancelled'',cancelled_at=now(),cancelled_by_user_id=auth.uid(),cancel_reason=btrim(p_reason),updated_at=now() where id=t.id;\n  perform public.record_finance_tax_invoice_audit(t.id,''cancelled'',jsonb_build_object(''reason'',btrim(p_reason),''coverage_released'',true));\n  return t.id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"tax_correction_authorized","owner":"postgres","config":["search_path=public"],"signature":"tax_correction_authorized(boolean,text)","definition":"CREATE OR REPLACE FUNCTION public.tax_correction_authorized(p_combined boolean, p_action text)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n select case p_action\n   when ''view'' then public.current_user_can_view_finance_tax_invoices() and (not p_combined or public.current_user_can_view_finance_receipts())\n   when ''manage'' then public.current_user_can_manage_finance_tax_invoices() and (not p_combined or public.current_user_can_manage_finance_receipts())\n   when ''issue'' then public.current_user_can_issue_finance_tax_invoices() and (not p_combined or public.current_user_can_issue_finance_receipts())\n   else false end;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres}","name":"tax_correction_source","owner":"postgres","config":["search_path=public"],"signature":"tax_correction_source(uuid,uuid)","definition":"CREATE OR REPLACE FUNCTION public.tax_correction_source(p_tax_id uuid, p_combined_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare t public.finance_tax_invoices%rowtype; c public.finance_combined_documents%rowtype; r public.finance_receipts%rowtype; replacement record;\nbegin\n select * into strict t from public.finance_tax_invoices where id=p_tax_id;\n if t.status<>''issued'' or t.issued_snapshot_json is null then raise exception ''TAX_CORRECTION_ISSUED_ORIGINAL_REQUIRED''; end if;\n if t.combined_document_id is distinct from p_combined_id then raise exception ''DOCUMENT_USE_COMBINED_WORKFLOW''; end if;\n if p_combined_id is not null then\n   select * into strict c from public.finance_combined_documents where id=p_combined_id;\n   select * into strict r from public.finance_receipts where id=c.receipt_id;\n   if c.status<>''issued'' or r.status<>''issued'' or c.tax_invoice_id<>t.id or c.payment_id<>t.payment_id or r.payment_id<>t.payment_id\n     or r.combined_document_id<>c.id or r.receipt_no<>c.combined_no or t.tax_invoice_no<>c.combined_no\n     or c.issued_snapshot_json->''tax_invoice'' is distinct from t.issued_snapshot_json\n     or c.issued_snapshot_json->''receipt'' is distinct from r.issued_snapshot_json\n   then raise exception ''TAX_CORRECTION_PAIR_INVALID''; end if;\n end if;\n select x.id,d.issued_snapshot_json into replacement from public.finance_tax_document_corrections x\n join public.finance_tax_correction_documents d on d.id=x.id\n where x.original_tax_invoice_id=t.id and x.correction_mode=''cancel_and_reissue'' and x.status=''issued''\n and not exists(select 1 from public.finance_tax_document_corrections later\n   where later.source_correction_id=x.id and later.correction_mode=''cancel_and_reissue'' and later.status=''issued'');\n return jsonb_build_object(''tax_invoice_id'',t.id,''combined_id'',p_combined_id,''receipt_id'',r.id,''invoice_id'',t.invoice_id,''payment_id'',t.payment_id,\n   ''source_correction_id'',replacement.id,''document_no'',coalesce(replacement.issued_snapshot_json->>''document_no'',t.tax_invoice_no),\n   ''document_date'',coalesce(replacement.issued_snapshot_json->>''document_date'',t.issue_date::text),\n   ''tax'',coalesce(replacement.issued_snapshot_json->''tax'',t.issued_snapshot_json),\n   ''receipt'',coalesce(replacement.issued_snapshot_json->''receipt'',r.issued_snapshot_json));\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"tax_expense_input_vat_status","owner":"postgres","config":["search_path=public"],"signature":"tax_expense_input_vat_status(uuid)","definition":"CREATE OR REPLACE FUNCTION public.tax_expense_input_vat_status(p_id uuid)\n RETURNS text\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n select case\n  when e.status<>''accepted'' or r.vat_state=''none'' or r.vat_amount=0 then ''none''\n  when r.vat_state=''exists'' and r.vat_base is not null and r.vat_amount>0 then\n   case when r.eligibility=''ineligible'' then ''ineligible'' else ''eligible'' end\n  when r.vat_state=''pending'' or e.vat_awareness=''yes'' then ''pending''\n  else ''none'' end\n from public.finance_expenses e left join lateral\n  (select * from public.finance_expense_tax_reviews where expense_id=e.id order by revision desc limit 1) r on true\n where e.id=p_id;\n$function$\n","anon_execute":false,"service_execute":true,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"tax_filing_monthly_facts_before_expense","owner":"postgres","config":["search_path=public"],"signature":"tax_filing_monthly_facts_before_expense(date)","definition":"CREATE OR REPLACE FUNCTION public.tax_filing_monthly_facts_before_expense(p_month date)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare r record; s jsonb; lines jsonb; l jsonb; evidence jsonb:=''[]''; issues jsonb:=''[]'';\n total numeric:=0; unknown_output boolean:=false;\nbegin\n if p_month is null or extract(day from p_month)<>1 then raise exception ''TAX_FILING_INPUT_INVALID''; end if;\n -- Same source priority/month/status rules as dashboard-data.ts. The existing\n -- pure 050 projection supplies stored VAT and signed corrections, not new math.\n for r in\n  select ''direct_money_receipt''::text as source_type,id as source_id from public.finance_direct_money_receipts\n   where status=''confirmed'' and currency=''THB'' and received_on>=p_month and received_on<p_month+interval ''1 month''\n  union all\n  select ''tax_invoice'',t.id from public.finance_tax_invoices t\n   where t.status=''issued'' and exists(select 1 from public.finance_tax_point_events p where p.tax_invoice_id=t.id\n    and p.approved_at is not null and p.occurred_on>=p_month and p.occurred_on<p_month+interval ''1 month'')\n  union all\n  select ''tax_correction'',id from public.finance_tax_document_corrections\n   where status=''issued'' and correction_mode in (''credit_note'',''debit_note'')\n    and adjustment_date>=p_month and adjustment_date<p_month+interval ''1 month''\n  order by source_type,source_id\n loop\n  s:=public.tax_position_source(r.source_type,r.source_id);\n  select coalesce(jsonb_agg(x order by x->>''line_id''),''[]'') into lines\n   from jsonb_array_elements(s->''lines'') x where x->>''kind''=''output_vat'';\n  if (s->>''active'')::boolean is distinct from true or s->>''currency''<>''THB''\n   or (s->>''effective_on'')::date<p_month or (s->>''effective_on'')::date>=p_month+interval ''1 month''\n   then raise exception ''TAX_FILING_SOURCE_CHANGED''; end if;\n  if r.source_type in (''tax_invoice'',''tax_correction'') and lines=''[]''::jsonb then\n   unknown_output:=true;\n   issues:=issues||jsonb_build_array(jsonb_build_object(''code'',''source_evidence_incomplete'',''count'',1));\n  end if;\n  for l in select value from jsonb_array_elements(lines) loop\n   if jsonb_typeof(l->''tax'') is distinct from ''number'' then unknown_output:=true;\n   else total:=total+(l->>''tax'')::numeric; end if;\n  end loop;\n  if s->''warnings''<>''[]''::jsonb then\n   issues:=issues||jsonb_build_array(jsonb_build_object(''code'',''source_evidence_incomplete'',''count'',jsonb_array_length(s->''warnings'')));\n  end if;\n  evidence:=evidence||jsonb_build_array(jsonb_build_object(''source_type'',r.source_type,''source_id'',r.source_id,\n   ''effective_on'',s->''effective_on'',''reference'',s->''reference'',''source_fingerprint'',md5(s::text),''lines'',lines));\n end loop;\n return jsonb_build_object(''output_vat'',case when unknown_output then null else total end,\n  ''input_vat'',null,''input_vat_complete'',false,''net_vat'',null,\n  ''source_evidence'',evidence,''issues'',issues,''source_contract'',''tax_position_source_v1'');\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres,service_role=X/postgres}","name":"tax_position_source","owner":"postgres","config":["search_path=public"],"signature":"tax_position_source(text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.tax_position_source(p_type text, p_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare s jsonb;e public.finance_expenses%rowtype;r public.finance_expense_tax_reviews%rowtype;\n d public.finance_external_input_vat%rowtype;x public.finance_external_input_vat_reviews%rowtype;lines jsonb:=''[]'';\nbegin\n if p_type=''expense'' then\n  s:=public.tax_position_source_before_external_input(p_type,p_id);\n  -- Preserve already-reviewed projections byte-for-byte (including their fingerprints).\n  if public.tax_expense_input_vat_status(p_id)=''eligible'' and s->''lines''=''[]''::jsonb then\n   select * into strict e from public.finance_expenses where id=p_id;\n   select * into strict r from public.finance_expense_tax_reviews where expense_id=p_id order by revision desc limit 1;\n   s:=s||jsonb_build_object(''effective_on'',coalesce(r.tax_document_date,e.expense_date),''lines'',\n    jsonb_build_array(jsonb_build_object(''line_id'',e.id,''kind'',''input_vat'',''base'',r.vat_base,''rate'',r.vat_rate,''tax'',r.vat_amount,\n     ''treatment'',''authoritative_source'',''date_basis'',''reviewed_expense_document'',''evidence'',to_jsonb(r))));\n  end if;\n  return s;\n end if;\n if p_type<>''external_input_vat'' then return public.tax_position_source_before_external_input(p_type,p_id); end if;\n select * into strict d from public.finance_external_input_vat where id=p_id;\n select * into x from public.finance_external_input_vat_reviews previous_review where evidence_id=p_id\n  and not exists(select 1 from public.finance_external_input_vat_reviews n where n.previous_id=previous_review.id);\n -- Saving acknowledged external evidence establishes VAT. A later explicit exception wins.\n if x.id is null or x.status=''eligible'' then\n  lines:=jsonb_build_array(jsonb_build_object(''line_id'',d.id,''kind'',''input_vat'',''base'',d.tax_base,''rate'',null,''tax'',d.vat_amount,\n   ''treatment'',case when x.id is null then ''authoritative_source'' else ''reviewed_eligible'' end,\n   ''date_basis'',''reviewed_external_document'',''evidence'',case when x.id is null then to_jsonb(d) else to_jsonb(x) end));\n end if;\n return jsonb_build_object(''source_type'',p_type,''source_id'',d.id,''active'',true,''reference'',d.invoice_number,\n  ''effective_on'',d.invoice_date,''currency'',''THB'',''payer'',jsonb_build_object(''name'',d.vendor),''lines'',lines,''warnings'',''[]''::jsonb,\n  ''source_evidence'',jsonb_build_object(''document'',to_jsonb(d),''review'',to_jsonb(x)));\nend;\n$function$\n","anon_execute":false,"service_execute":true,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"tax_position_source_before_expense","owner":"postgres","config":["search_path=public"],"signature":"tax_position_source_before_expense(text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.tax_position_source_before_expense(p_type text, p_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare s jsonb; lines jsonb:=''[]''; warnings jsonb:=''[]''; l jsonb; d public.finance_direct_money_receipts%rowtype;\n p public.finance_payments%rowtype; t public.finance_tax_invoices%rowtype; point public.finance_tax_point_events%rowtype;\n c public.finance_tax_document_corrections%rowtype; r record; moment date; ref text; payer jsonb:=''{}''; active boolean:=false;\nbegin\n if p_type=''direct_money_receipt'' then\n  select * into strict d from public.finance_direct_money_receipts where id=p_id;\n  active:=d.status=''confirmed''; moment:=d.received_on; ref:=upper(left(d.id::text,8));\n  payer:=jsonb_build_object(''client_id'',d.client_id,''name'',d.confirmed_snapshot_json#>>''{facts,payer_name}'');\n  s:=jsonb_build_object(''snapshot'',d.confirmed_snapshot_json,''classification'',d.classification_json,''version'',d.version,''status'',d.status);\n  if active then\n   for l in select value from jsonb_array_elements(coalesce(d.classification_json->''lines'',d.confirmed_snapshot_json->''lines'')) loop\n    if l#>>''{vat_treatment_json,treatment}'' in (''standard_rate'',''zero_rated'',''exempt'',''outside_scope'',''disbursement'',''pass_through'') then\n     lines:=lines||jsonb_build_array(jsonb_build_object(''line_id'',l->''source_line_id'',''kind'',''output_vat'',''base'',l->''base'',\n      ''rate'',l->''vat_rate'',''tax'',l->''vat'',''treatment'',l#>>''{vat_treatment_json,treatment}'',''date_basis'',''confirmed_receipt'',''evidence'',l));\n    else warnings:=warnings||jsonb_build_array(''vat_treatment_unresolved''); end if;\n    if (l->>''wht'')::numeric>0 then\n     lines:=lines||jsonb_build_array(jsonb_build_object(''line_id'',l->''source_line_id'',''kind'',''incoming_wht'',''base'',l->''wht_base'',\n      ''rate'',l->''wht_rate'',''tax'',l->''wht'',''treatment'',''structured'',''date_basis'',''confirmed_receipt'',''evidence'',l));\n    end if;\n   end loop;\n  end if;\n elsif p_type=''payment'' then\n  select * into strict p from public.finance_payments where id=p_id;\n  active:=p.status=''confirmed''; moment:=p.received_on; ref:=coalesce(p.internal_reference,upper(left(p.id::text,8)));\n  payer:=jsonb_build_object(''client_id'',p.client_id,''name'',p.payer_name);\n  s:=jsonb_build_object(''payment'',to_jsonb(p),''components'',(select coalesce(jsonb_agg(to_jsonb(w) order by w.id),''[]'') from public.finance_payment_wht_components w where w.payment_id=p.id),\n   ''certificates'',(select coalesce(jsonb_agg(to_jsonb(e) order by e.id),''[]'') from public.finance_payment_evidence e where payment_id=p.id and evidence_type=''wht_certificate''));\n  if active and p.currency<>''THB'' then warnings:=warnings||jsonb_build_array(''currency_outside_phase_scope''); end if;\n  if active and p.wht_amount>0 and p.currency=''THB'' then\n   if (select sum(calculated_wht_amount) from public.finance_payment_wht_components where payment_id=p.id)=p.wht_amount then\n    for r in select * from public.finance_payment_wht_components where payment_id=p.id and calculated_wht_amount>0 order by id loop\n     lines:=lines||jsonb_build_array(jsonb_build_object(''line_id'',r.id,''kind'',''incoming_wht'',''base'',r.base_amount,''rate'',r.rate_percent,\n      ''tax'',r.calculated_wht_amount,''treatment'',''structured'',''date_basis'',''confirmed_receipt'',''evidence'',to_jsonb(r)||jsonb_build_object(''certificates'',s->''certificates'')));\n    end loop;\n   else\n    warnings:=warnings||jsonb_build_array(''wht_structure_unavailable'');\n    lines:=jsonb_build_array(jsonb_build_object(''line_id'',p.id,''kind'',''incoming_wht'',''base'',null,''rate'',null,''tax'',p.wht_amount,\n     ''treatment'',''legacy_unstructured'',''date_basis'',''confirmed_receipt'',''evidence'',to_jsonb(p)||jsonb_build_object(''certificates'',s->''certificates'')));\n   end if;\n  end if;\n elsif p_type=''tax_invoice'' then\n  select * into strict t from public.finance_tax_invoices where id=p_id;\n  select * into point from public.finance_tax_point_events where tax_invoice_id=t.id;\n  active:=t.status=''issued'' and point.approved_at is not null; moment:=point.occurred_on; ref:=t.tax_invoice_no;\n  payer:=coalesce(t.issued_snapshot_json->''customer'',''{}'');\n  s:=jsonb_build_object(''snapshot'',t.issued_snapshot_json,''point'',to_jsonb(point),''status'',t.status);\n  if active then\n   for r in select * from public.finance_tax_invoice_items where tax_invoice_id=t.id order by id loop\n    l:=r.source_snapshot_json;\n    -- Item source is the frozen Invoice item, not a newly calculated tax value.\n    lines:=lines||jsonb_build_array(jsonb_build_object(''line_id'',r.id,''kind'',''output_vat'',''base'',r.amount_before_vat,\n     ''rate'',l->''vat_rate'',''tax'',r.vat_amount,''treatment'',coalesce(l#>>''{vat_treatment_json,treatment}'',t.issued_snapshot_json->>''tax_treatment''),\n     ''date_basis'',''approved_tax_point'',''evidence'',to_jsonb(r)));\n   end loop;\n  end if;\n elsif p_type=''tax_correction'' then\n  select * into strict c from public.finance_tax_document_corrections where id=p_id;\n  active:=c.status=''issued'' and c.correction_mode in (''credit_note'',''debit_note''); moment:=c.adjustment_date;\n  select document_no into ref from public.finance_tax_correction_documents where id=c.id;\n  payer:=coalesce(c.source_snapshot_json#>''{tax,customer}'',''{}'');\n  s:=jsonb_build_object(''correction'',to_jsonb(c),''document'',(select to_jsonb(x) from public.finance_tax_correction_documents x where id=c.id));\n  if active then\n   for r in select x.*,i.source_snapshot_json as original_item from public.finance_tax_correction_lines x\n    join public.finance_tax_invoice_items i on i.id=x.original_tax_invoice_item_id where correction_id=c.id order by x.id loop\n    lines:=lines||jsonb_build_array(jsonb_build_object(''line_id'',r.id,''kind'',''output_vat'',\n     ''base'',r.base_change*case c.correction_mode when ''credit_note'' then -1 else 1 end,\n     ''rate'',r.original_item->''vat_rate'',''tax'',r.vat_change*case c.correction_mode when ''credit_note'' then -1 else 1 end,\n     ''treatment'',c.correction_mode,''date_basis'',''document_adjustment'',''evidence'',to_jsonb(r)));\n   end loop;\n  end if;\n else raise exception ''TAX_POSITION_SOURCE_INVALID''; end if;\n return jsonb_build_object(''source_type'',p_type,''source_id'',p_id,''active'',active,''reference'',ref,''effective_on'',moment,\n  ''currency'',case when p_type=''payment'' then p.currency else ''THB'' end,''payer'',payer,''lines'',lines,''warnings'',warnings,''source_evidence'',s);\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"tax_position_source_before_external_input","owner":"postgres","config":["search_path=public"],"signature":"tax_position_source_before_external_input(text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.tax_position_source_before_external_input(p_type text, p_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare e public.finance_expenses%rowtype; r public.finance_expense_tax_reviews%rowtype; lines jsonb:=''[]'';\nbegin\n if p_type<>''expense'' then return public.tax_position_source_before_expense(p_type,p_id); end if;\n select * into strict e from public.finance_expenses where id=p_id;\n select * into r from public.finance_expense_tax_reviews where expense_id=p_id order by revision desc limit 1;\n if e.status=''accepted'' and r.eligibility=''eligible'' and r.vat_amount>0 then\n  lines:=jsonb_build_array(jsonb_build_object(''line_id'',e.id,''kind'',''input_vat'',''base'',r.vat_base,''rate'',r.vat_rate,''tax'',r.vat_amount,\n   ''treatment'',''reviewed_eligible'',''date_basis'',''reviewed_expense_document'',''evidence'',to_jsonb(r)));\n end if;\n return jsonb_build_object(''source_type'',''expense'',''source_id'',e.id,''active'',e.status=''accepted'',''reference'',r.tax_document_reference,\n  ''effective_on'',r.tax_document_date,''currency'',e.currency,''payer'',jsonb_build_object(''name'',e.vendor_name,''supplier_tax_id'',r.supplier_tax_id),\n  ''lines'',lines,''warnings'',''[]''::jsonb,''source_evidence'',jsonb_build_object(''expense'',to_jsonb(e),''tax_review'',to_jsonb(r)));\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"tax_refresh_pre040","owner":"postgres","config":["search_path=public"],"signature":"tax_refresh_pre040(uuid,timestamp with time zone)","definition":"CREATE OR REPLACE FUNCTION public.tax_refresh_pre040(p_tax_invoice_id uuid, p_expected_updated_at timestamp with time zone)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare t public.finance_tax_invoices%rowtype; source jsonb; pid uuid;\nbegin\n  if not public.current_user_can_manage_finance_tax_invoices() then raise exception ''TAX_INVOICE_PERMISSION_DENIED''; end if;\n  select payment_id into pid from public.finance_tax_invoices where id=p_tax_invoice_id;\n  source:=public.build_finance_tax_invoice_source(pid);\n  select * into t from public.finance_tax_invoices where id=p_tax_invoice_id for update;\n  if not found or t.status<>''draft'' then raise exception ''TAX_INVOICE_DRAFT_REQUIRED''; end if;\n  if t.updated_at is distinct from p_expected_updated_at then raise exception ''TAX_INVOICE_STALE_REVIEW''; end if;\n  if source->''invoice_item'' is distinct from t.source_snapshot_json->''invoice_item''\n    or source->''payment'' is distinct from t.source_snapshot_json->''payment''\n  then raise exception ''TAX_INVOICE_SOURCE_CHANGED''; end if;\n  if source=t.source_snapshot_json then return t.id; end if;\n  update public.finance_tax_point_events set approved_at=null,approved_by_user_id=null where tax_invoice_id=t.id;\n  update public.finance_tax_invoices set source_snapshot_json=source,decisions_json=''{}'',\n    draft_snapshot_json=public.finance_tax_invoice_draft_snapshot(source,''{}'',t.issue_date),updated_at=clock_timestamp() where id=t.id;\n  perform public.record_finance_tax_invoice_audit(t.id,''draft_refreshed'',jsonb_build_object(''approvals_reset'',true));\n  return t.id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"tax_save_pre040","owner":"postgres","config":["search_path=public"],"signature":"tax_save_pre040(uuid,date,jsonb,timestamp with time zone)","definition":"CREATE OR REPLACE FUNCTION public.tax_save_pre040(p_tax_invoice_id uuid, p_issue_date date, p_decisions_json jsonb, p_expected_updated_at timestamp with time zone)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare t public.finance_tax_invoices%rowtype; snapshot jsonb; pid uuid;\nbegin\n  if not public.current_user_can_manage_finance_tax_invoices() then raise exception ''TAX_INVOICE_PERMISSION_DENIED''; end if;\n  select payment_id into pid from public.finance_tax_invoices where id=p_tax_invoice_id;\n  perform 1 from public.finance_payments where id=pid for update;\n  select * into t from public.finance_tax_invoices where id=p_tax_invoice_id for update;\n  if not found or t.status<>''draft'' then raise exception ''TAX_INVOICE_DRAFT_REQUIRED''; end if;\n  if t.updated_at is distinct from p_expected_updated_at then raise exception ''TAX_INVOICE_STALE_REVIEW''; end if;\n  if p_issue_date is null or p_issue_date>(now() at time zone ''Asia/Bangkok'')::date\n    or p_issue_date<(t.source_snapshot_json #>> ''{payment,received_on}'')::date then raise exception ''TAX_INVOICE_ISSUE_DATE_INVALID''; end if;\n  snapshot:=public.finance_tax_invoice_draft_snapshot(t.source_snapshot_json,p_decisions_json,p_issue_date);\n  if snapshot=t.draft_snapshot_json and p_decisions_json=t.decisions_json then return t.id; end if;\n  update public.finance_tax_point_events set approved_at=case when p_decisions_json->''no_earlier_event''=''true''::jsonb then now() end,\n    approved_by_user_id=case when p_decisions_json->''no_earlier_event''=''true''::jsonb then auth.uid() end where tax_invoice_id=t.id;\n  update public.finance_tax_invoices set issue_date=p_issue_date,decisions_json=p_decisions_json,draft_snapshot_json=snapshot,updated_at=clock_timestamp() where id=t.id;\n  perform public.record_finance_tax_invoice_audit(t.id,''draft_saved'',jsonb_build_object(''previous_decisions'',t.decisions_json,''decisions'',p_decisions_json,''issue_date'',p_issue_date));\n  return t.id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"tax_snapshot_pre040","owner":"postgres","config":["search_path=public"],"signature":"tax_snapshot_pre040(jsonb,jsonb,date)","definition":"CREATE OR REPLACE FUNCTION public.tax_snapshot_pre040(p_source jsonb, p_decisions jsonb, p_issue_date date)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare customer jsonb:=p_source->''customer''; decisions jsonb:=coalesce(p_decisions,''{}''); branch text;\nbegin\n  if jsonb_typeof(decisions)<>''object'' or exists(select 1 from jsonb_object_keys(decisions) k where k not in\n    (''tax_treatment'',''treatment_reason'',''buyer_vat_registered'',''customer_address'',''customer_tax_id'',''buyer_branch_type'',\n     ''buyer_branch_code'',''identity_evidence'',''no_earlier_event'',''external_coverage_checked''))\n  then raise exception ''TAX_INVOICE_DECISIONS_INVALID''; end if;\n  if exists(select 1 from (values(''buyer_vat_registered''),(''no_earlier_event''),(''external_coverage_checked'')) f(key)\n    where decisions ? f.key and jsonb_typeof(decisions->f.key) not in (''boolean'',''null''))\n  then raise exception ''TAX_INVOICE_DECISIONS_INVALID''; end if;\n  if exists(select 1 from jsonb_each(decisions) f where f.key not in (''buyer_vat_registered'',''no_earlier_event'',''external_coverage_checked'')\n    and (jsonb_typeof(f.value) not in (''string'',''null'') or length(f.value #>> ''{}'')>2000))\n  then raise exception ''TAX_INVOICE_DECISIONS_INVALID''; end if;\n  if nullif(btrim(customer->>''address''),'''') is not null and nullif(btrim(decisions->>''customer_address''),'''') is not null\n    and btrim(decisions->>''customer_address'')<>customer->>''address''\n    or nullif(btrim(customer->>''tax_id''),'''') is not null and nullif(btrim(decisions->>''customer_tax_id''),'''') is not null\n    and btrim(decisions->>''customer_tax_id'')<>customer->>''tax_id''\n  then raise exception ''TAX_INVOICE_FROZEN_IDENTITY_CHANGE_BLOCKED''; end if;\n  branch:=case when lower(customer->>''branch'') in (''สำนักงานใหญ่'',''head office'',''00000'') then ''head_office''\n    else nullif(decisions->>''buyer_branch_type'','''') end;\n  customer:=customer||jsonb_build_object(''address'',coalesce(nullif(btrim(customer->>''address''),''''),nullif(btrim(decisions->>''customer_address''),'''')),\n    ''tax_id'',coalesce(nullif(btrim(customer->>''tax_id''),''''),nullif(btrim(decisions->>''customer_tax_id''),'''')),\n    ''vat_registered'',decisions->''buyer_vat_registered'',''branch_type'',branch,\n    ''branch_code'',case when branch=''head_office'' then ''00000'' else nullif(btrim(decisions->>''buyer_branch_code''),'''') end,\n    ''supplemental_evidence'',nullif(btrim(decisions->>''identity_evidence''),''''));\n  return p_source||jsonb_build_object(''customer'',customer,''issue_date'',p_issue_date,\n    ''tax_treatment'',nullif(decisions->>''tax_treatment'',''''),''treatment_reason'',nullif(btrim(decisions->>''treatment_reason''),''''),\n    ''tax_point'',jsonb_build_object(''event_type'',''payment_received'',''date'',p_source #> ''{payment,received_on}'',\n      ''no_earlier_event_acknowledged'',coalesce(decisions->''no_earlier_event'',''false''::jsonb),''policy_version'',''vp_v1''),\n    ''external_coverage_checked'',coalesce(decisions->''external_coverage_checked'',''false''::jsonb));\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"validate_finance_combined_document","owner":"postgres","config":["search_path=public"],"signature":"validate_finance_combined_document()","definition":"CREATE OR REPLACE FUNCTION public.validate_finance_combined_document()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare cid uuid; c public.finance_combined_documents%rowtype; r public.finance_receipts%rowtype; t public.finance_tax_invoices%rowtype;\nbegin\n  if tg_table_name=''finance_combined_documents'' then cid:=new.id; else cid:=new.combined_document_id; end if;\n  if cid is null then\n    if tg_op=''UPDATE'' and old.combined_document_id is not null then raise exception ''DOCUMENT_PAIR_IMMUTABLE''; end if;\n    return new;\n  end if;\n  if tg_op=''UPDATE'' and tg_table_name in (''finance_receipts'',''finance_tax_invoices'') then\n    if old.combined_document_id is not null and old.combined_document_id is distinct from new.combined_document_id then raise exception ''DOCUMENT_PAIR_IMMUTABLE''; end if;\n  end if;\n  select * into strict c from public.finance_combined_documents where id=cid;\n  select * into strict r from public.finance_receipts where id=c.receipt_id;\n  select * into strict t from public.finance_tax_invoices where id=c.tax_invoice_id;\n  if r.payment_id<>c.payment_id or t.payment_id<>c.payment_id or r.combined_document_id is distinct from c.id or t.combined_document_id is distinct from c.id\n    or r.status<>c.status or t.status<>c.status or c.issue_date<>t.issue_date\n    or c.draft_snapshot_json is distinct from t.draft_snapshot_json or c.source_snapshot_json is distinct from t.source_snapshot_json\n    or c.decisions_json is distinct from t.decisions_json or not c.external_receipt_checked\n  then raise exception ''DOCUMENT_PAIR_INVALID''; end if;\n  if c.status=''issued'' then\n    if c.combined_no is distinct from r.receipt_no or c.combined_no is distinct from t.tax_invoice_no\n      or c.issued_at is distinct from r.issued_at or c.issued_at is distinct from t.issued_at\n      or c.issued_by_user_id is distinct from r.issued_by_user_id or c.issued_by_user_id is distinct from t.issued_by_user_id\n      or c.issued_snapshot_json is distinct from jsonb_build_object(''schema_version'',1,''document_kind'',''receipt_tax_invoice'',''combined_document_id'',c.id,\n        ''combined_no'',c.combined_no,''issued_at'',c.issued_at,''issue_date'',c.issue_date,''receipt'',r.issued_snapshot_json,''tax_invoice'',t.issued_snapshot_json)\n      or not exists(select 1 from public.finance_combined_document_audit_events where combined_document_id=c.id and event_type=''issued''\n        and event_payload_json->>''combined_no''=c.combined_no and actor_user_id=c.issued_by_user_id)\n    then raise exception ''DOCUMENT_PAIR_ISSUED_EVIDENCE_INVALID''; end if;\n  end if;\n  return new;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"validate_finance_document_tax_integrity","owner":"postgres","config":["search_path=public"],"signature":"validate_finance_document_tax_integrity(uuid)","definition":"CREATE OR REPLACE FUNCTION public.validate_finance_document_tax_integrity(p_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare t public.finance_tax_invoices%rowtype; point public.finance_tax_point_events%rowtype; item jsonb; c record; expected_count integer; lines jsonb; taxable jsonb;\nbegin\n  select * into strict t from public.finance_tax_invoices where id=p_id;\n  lines:=public.finance_document_invoice_lines(t.invoice_id);\n  select jsonb_agg(e) into taxable from jsonb_array_elements(lines) e where e #>> ''{resolved_vat_treatment,treatment}'' in (''standard_rate'',''zero_rated'');\n  expected_count:=jsonb_array_length(t.source_snapshot_json->''invoice_items'');\n  if expected_count is null or expected_count<1 or t.draft_snapshot_json is distinct from public.finance_tax_invoice_draft_snapshot(t.source_snapshot_json,t.decisions_json,t.issue_date)\n    or t.source_snapshot_json->''document_lines'' is distinct from lines or t.source_snapshot_json->''invoice_items'' is distinct from taxable\n    or t.payment_id::text is distinct from t.source_snapshot_json #>> ''{payment,id}''\n    or t.invoice_id::text is distinct from t.source_snapshot_json #>> ''{invoice,id}''\n    or t.client_id::text is distinct from t.source_snapshot_json #>> ''{customer,id}''\n    or (select count(*) from public.finance_tax_invoice_items where tax_invoice_id=t.id)<>expected_count\n    or (select count(*) from public.finance_tax_invoice_source_coverages where tax_invoice_id=t.id)<>expected_count\n  then raise exception ''TAX_INVOICE_SOURCE_INVALID''; end if;\n  select * into strict point from public.finance_tax_point_events where tax_invoice_id=t.id;\n  if point.event_type<>''payment_received'' or point.occurred_on is distinct from (t.source_snapshot_json #>> ''{payment,received_on}'')::date\n    or point.evidence_json is distinct from jsonb_build_object(''payment'',t.source_snapshot_json->''payment'',''policy_version'',''vp_v1'')\n    or ((t.decisions_json->''no_earlier_event''=''true''::jsonb) is true)<>(point.approved_at is not null)\n  then raise exception ''TAX_INVOICE_TAX_POINT_APPROVAL_REQUIRED''; end if;\n  for item in select value from jsonb_array_elements(t.source_snapshot_json->''invoice_items'') loop\n    if item #>> ''{resolved_vat_treatment,treatment}'' not in (''standard_rate'',''zero_rated'') then raise exception ''DOCUMENT_VAT_CONFLICT''; end if;\n    select coverage.*,component.source_snapshot_json as component_snapshot,component.amount_before_vat as cb,component.vat_amount as cv,component.total_amount as ct\n    into strict c from public.finance_tax_invoice_source_coverages coverage join public.finance_tax_invoice_items component on component.id=coverage.tax_invoice_item_id\n    where coverage.tax_invoice_id=t.id and component.tax_invoice_id=t.id and component.invoice_item_id::text=item->>''id'';\n    if c.invoice_item_id::text is distinct from item->>''id'' or c.tax_point_event_id<>point.id\n      or c.component_snapshot is distinct from item or c.cb is distinct from (item->>''amount_before_vat'')::numeric\n      or c.cv is distinct from (item->>''vat_amount'')::numeric or c.ct is distinct from (item->>''line_total'')::numeric\n      or c.amount_before_vat<>c.cb or c.vat_amount<>c.cv or c.total_amount<>c.ct\n      or c.status<>(case t.status when ''draft'' then ''reserved'' when ''issued'' then ''issued'' else ''released'' end)\n      or c.source_snapshot_json is distinct from jsonb_build_object(''invoice_id'',t.source_snapshot_json #> ''{invoice,id}'',''payment_id'',t.payment_id,''invoice_item'',item,''rule'',''explicit_full_line_v2'')\n    then raise exception ''TAX_INVOICE_COVERAGE_INVALID''; end if;\n  end loop;\n  if t.status=''issued'' then\n    if cardinality(public.finance_tax_invoice_issue_blockers(t.draft_snapshot_json))>0\n      or (t.issued_snapshot_json-array[''document'',''tax_point'']) is distinct from (t.draft_snapshot_json-''tax_point'')\n      or t.issued_snapshot_json #>> ''{document,id}'' is distinct from t.id::text\n      or t.issued_snapshot_json #>> ''{document,tax_invoice_no}'' is distinct from t.tax_invoice_no\n      or (t.issued_snapshot_json #>> ''{document,issue_date}'')::date is distinct from t.issue_date\n      or (t.issued_snapshot_json #>> ''{document,issued_at}'')::timestamptz is distinct from t.issued_at\n      or t.issued_snapshot_json #>> ''{document,issued_by_user_id}'' is distinct from t.issued_by_user_id::text\n      or t.issued_snapshot_json->''tax_point'' is distinct from (t.draft_snapshot_json->''tax_point''||to_jsonb(point))\n      or t.issued_snapshot_json #> ''{seller,logo_asset}'' is distinct from public.document_logo_evidence(t.issued_snapshot_json #>> ''{seller,logo_asset,path}'')\n    then raise exception ''TAX_INVOICE_ISSUED_EVIDENCE_INVALID''; end if;\n    if not exists(select 1 from public.finance_tax_invoice_audit_events where tax_invoice_id=t.id and event_type=''issued''\n      and event_payload_json->>''tax_invoice_no''=t.tax_invoice_no and actor_user_id=t.issued_by_user_id\n      and (t.issue_date=point.occurred_on or event_payload_json->''delayed_issue_acknowledged''=''true''::jsonb)) then raise exception ''TAX_INVOICE_ISSUE_AUDIT_REQUIRED''; end if;\n  end if;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"validate_finance_receipt_integrity","owner":"postgres","config":["search_path=public"],"signature":"validate_finance_receipt_integrity()","definition":"CREATE OR REPLACE FUNCTION public.validate_finance_receipt_integrity()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_receipt public.finance_receipts%rowtype; v_id uuid; v_cash numeric; v_wht numeric; v_count bigint;\nbegin\n  if tg_table_name = ''finance_receipts'' then v_id := new.id;\n  else v_id := new.receipt_id; end if;\n  select * into strict v_receipt from public.finance_receipts where id = v_id;\n  if v_receipt.replaces_receipt_id is not null and not exists (\n    select 1 from public.finance_receipts prior where prior.id = v_receipt.replaces_receipt_id\n      and prior.payment_id = v_receipt.payment_id and prior.status = ''voided''\n  ) then raise exception ''RECEIPT_REPLACEMENT_SOURCE_INVALID''; end if;\n  select count(*),coalesce(sum(cash_allocated),0),coalesce(sum(wht_allocated),0)\n    into v_count,v_cash,v_wht from public.finance_receipt_invoice_allocations where receipt_id = v_id;\n  if v_receipt.status in (''draft'',''cancelled'') and v_count <> 0 then raise exception ''RECEIPT_DRAFT_COVERAGE_INVALID''; end if;\n  if v_receipt.status in (''issued'',''voided'') then\n    if v_count = 0 or v_cash <> v_receipt.cash_amount or v_wht <> v_receipt.wht_amount\n      or (v_receipt.issued_snapshot_json #>> ''{receipt,receipt_no}'') is distinct from v_receipt.receipt_no\n      or (v_receipt.issued_snapshot_json #>> ''{receipt,id}'') is distinct from v_id::text\n      or (v_receipt.issued_snapshot_json #>> ''{receipt,receipt_date}'') is distinct from v_receipt.receipt_date::text\n      or (v_receipt.issued_snapshot_json #>> ''{payment,id}'') is distinct from v_receipt.payment_id::text\n      or (v_receipt.issued_snapshot_json #>> ''{payment,currency}'') is distinct from v_receipt.currency\n      or (v_receipt.issued_snapshot_json #>> ''{payment,cash_amount}'')::numeric is distinct from v_receipt.cash_amount\n      or (v_receipt.issued_snapshot_json #>> ''{payment,wht_amount}'')::numeric is distinct from v_receipt.wht_amount\n      or (v_receipt.issued_snapshot_json #>> ''{payment,settlement_amount}'')::numeric is distinct from v_receipt.settlement_amount\n      or v_count <> jsonb_array_length(v_receipt.issued_snapshot_json->''invoices'')\n      or (v_receipt.issued_snapshot_json - ''receipt'') is distinct from v_receipt.draft_snapshot_json\n      or exists (select 1 from public.finance_receipt_invoice_allocations a where a.receipt_id = v_id\n        and (a.currency <> v_receipt.currency\n          or (a.source_snapshot_json->>''invoice_id'') is distinct from a.invoice_id::text\n          or (a.source_snapshot_json->>''invoice_no'') is distinct from a.invoice_no\n          or (a.source_snapshot_json->>''currency'') is distinct from a.currency\n          or (a.source_snapshot_json->>''cash_allocated'')::numeric is distinct from a.cash_allocated\n          or (a.source_snapshot_json->>''wht_allocated'')::numeric is distinct from a.wht_allocated\n          or (a.source_snapshot_json->>''settlement_allocated'')::numeric is distinct from a.settlement_allocated\n          or not (v_receipt.issued_snapshot_json->''invoices'' @> jsonb_build_array(a.source_snapshot_json))))\n    then raise exception ''RECEIPT_FROZEN_COVERAGE_INVALID''; end if;\n  end if;\n  return null;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"validate_finance_tax_invoice_integrity","owner":"postgres","config":["search_path=public"],"signature":"validate_finance_tax_invoice_integrity()","definition":"CREATE OR REPLACE FUNCTION public.validate_finance_tax_invoice_integrity()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare t public.finance_tax_invoices%rowtype; v_id uuid; c record; item jsonb; point public.finance_tax_point_events%rowtype;\nbegin\n  if tg_table_name=''finance_tax_invoices'' then v_id:=new.id; else v_id:=new.tax_invoice_id; end if;\n  select * into strict t from public.finance_tax_invoices where finance_tax_invoices.id=v_id;\n  if t.source_snapshot_json->>''schema_version''=''2'' then\n    perform public.validate_finance_document_tax_integrity(t.id); return new;\n  end if;\n  item:=t.source_snapshot_json->''invoice_item'';\n  if t.draft_snapshot_json is distinct from public.finance_tax_invoice_draft_snapshot(t.source_snapshot_json,t.decisions_json,t.issue_date)\n    or t.payment_id::text is distinct from t.source_snapshot_json #>> ''{payment,id}''\n    or t.invoice_id::text is distinct from t.source_snapshot_json #>> ''{invoice,id}''\n    or t.client_id::text is distinct from t.source_snapshot_json #>> ''{customer,id}''\n  then raise exception ''TAX_INVOICE_SOURCE_INVALID''; end if;\n  if (select count(*) from public.finance_tax_invoice_items where tax_invoice_id=t.id)<>1\n    or (select count(*) from public.finance_tax_point_events where tax_invoice_id=t.id)<>1\n    or (select count(*) from public.finance_tax_invoice_source_coverages where tax_invoice_id=t.id)<>1\n  then raise exception ''TAX_INVOICE_COVERAGE_INVALID''; end if;\n  select * into strict point from public.finance_tax_point_events where tax_invoice_id=t.id;\n  if point.event_type<>''payment_received'' or point.occurred_on is distinct from (t.source_snapshot_json #>> ''{payment,received_on}'')::date\n    or point.evidence_json is distinct from jsonb_build_object(''payment'',t.source_snapshot_json->''payment'',''policy_version'',''vp_v1'')\n    or ((t.decisions_json->''no_earlier_event''=''true''::jsonb) is true)<>(point.approved_at is not null)\n  then raise exception ''TAX_INVOICE_TAX_POINT_APPROVAL_REQUIRED''; end if;\n  select coverage.*,i.invoice_item_id as item_source_id,i.amount_before_vat as ib,i.vat_amount as iv,i.total_amount as it,i.source_snapshot_json as frozen_item\n  into strict c from public.finance_tax_invoice_source_coverages coverage join public.finance_tax_invoice_items i on i.id=coverage.tax_invoice_item_id\n  where coverage.tax_invoice_id=t.id and i.tax_invoice_id=t.id;\n  if c.invoice_item_id<>c.item_source_id or c.invoice_item_id::text is distinct from item->>''id'' or c.tax_point_event_id<>point.id\n    or c.amount_before_vat<>c.ib or c.vat_amount<>c.iv or c.total_amount<>c.it\n    or c.ib is distinct from (item->>''amount_before_vat'')::numeric or c.iv is distinct from (item->>''vat_amount'')::numeric or c.it is distinct from (item->>''line_total'')::numeric\n    or c.frozen_item is distinct from item or c.status<>(case t.status when ''draft'' then ''reserved'' when ''issued'' then ''issued'' else ''released'' end)\n    or c.source_snapshot_json is distinct from jsonb_build_object(''invoice_id'',t.source_snapshot_json #> ''{invoice,id}'',\n      ''payment_id'',t.payment_id,''invoice_item'',item,''rule'',''single_line_full_payment_v1'')\n  then raise exception ''TAX_INVOICE_COVERAGE_INVALID''; end if;\n  if t.status=''issued'' then\n    if cardinality(public.finance_tax_invoice_issue_blockers(t.draft_snapshot_json))>0\n      or t.issued_snapshot_json->>''document_kind'' is distinct from ''tax_invoice''\n      or t.issued_snapshot_json->''schema_version'' is distinct from ''1''::jsonb\n      or (t.issued_snapshot_json-array[''document'',''tax_point'']) is distinct from (t.draft_snapshot_json-''tax_point'')\n      or t.issued_snapshot_json #>> ''{document,tax_invoice_no}'' is distinct from t.tax_invoice_no\n      or t.issued_snapshot_json #>> ''{document,id}'' is distinct from t.id::text\n      or (t.issued_snapshot_json #>> ''{document,issue_date}'')::date is distinct from t.issue_date\n      or (t.issued_snapshot_json #>> ''{document,issued_at}'')::timestamptz is distinct from t.issued_at\n      or t.issued_snapshot_json #>> ''{document,issued_by_user_id}'' is distinct from t.issued_by_user_id::text\n      or t.issued_snapshot_json->''tax_point'' is distinct from (t.draft_snapshot_json->''tax_point''||to_jsonb(point))\n      or t.issued_snapshot_json #> ''{seller,logo_asset}'' is distinct from public.document_logo_evidence(t.issued_snapshot_json #>> ''{seller,logo_asset,path}'')\n    then raise exception ''TAX_INVOICE_ISSUED_EVIDENCE_INVALID''; end if;\n    if not exists(select 1 from public.finance_tax_invoice_audit_events where tax_invoice_id=t.id and event_type=''issued''\n      and event_payload_json->>''tax_invoice_no''=t.tax_invoice_no and actor_user_id=t.issued_by_user_id\n      and (t.issue_date=point.occurred_on or event_payload_json->''delayed_issue_acknowledged''=''true''::jsonb))\n    then raise exception ''TAX_INVOICE_ISSUE_AUDIT_REQUIRED''; end if;\n  end if;\n  return new;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"validate_tax_correction_document","owner":"postgres","config":["search_path=public"],"signature":"validate_tax_correction_document()","definition":"CREATE OR REPLACE FUNCTION public.validate_tax_correction_document()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare c public.finance_tax_document_corrections%rowtype; d public.finance_tax_correction_documents%rowtype; cid uuid; expected_tax jsonb; expected_receipt jsonb;\nbegin\n cid:=(to_jsonb(new)->>case when tg_table_name=''finance_tax_correction_lines'' then ''correction_id'' else ''id'' end)::uuid;\n select * into strict c from public.finance_tax_document_corrections where id=cid;\n select * into d from public.finance_tax_correction_documents where id=cid;\n if c.source_snapshot_json->>''tax_invoice_id'' is distinct from c.original_tax_invoice_id::text\n   or c.source_snapshot_json->>''combined_id'' is distinct from c.original_combined_document_id::text\n   or c.source_snapshot_json->>''receipt_id'' is distinct from c.original_receipt_id::text\n   or c.source_snapshot_json->>''invoice_id'' is distinct from c.invoice_id::text\n   or c.source_snapshot_json->>''payment_id'' is distinct from c.payment_id::text\n   or c.source_snapshot_json->>''source_correction_id'' is distinct from c.source_correction_id::text\n then raise exception ''TAX_CORRECTION_SOURCE_INTEGRITY''; end if;\n if (select count(*) from public.finance_tax_correction_lines where correction_id=cid)<>jsonb_array_length(c.draft_snapshot_json->''lines'')\n   or exists(select 1 from jsonb_array_elements(c.draft_snapshot_json->''lines'') j\n     left join public.finance_tax_correction_lines l on l.correction_id=cid and l.original_tax_invoice_item_id=(j->>''item_id'')::uuid\n     left join public.finance_tax_invoice_items i on i.id=l.original_tax_invoice_item_id\n     where l.id is null or i.tax_invoice_id is distinct from c.original_tax_invoice_id or l.source_snapshot_json is distinct from i.source_snapshot_json\n       or l.source_snapshot_json is distinct from j->''source''\n       or jsonb_build_array(l.base_change,l.vat_change,l.previous_base,l.previous_vat,l.resulting_base,l.resulting_vat)\n          is distinct from jsonb_build_array(j->''base_change'',j->''vat_change'',j->''previous_base'',j->''previous_vat'',j->''resulting_base'',j->''resulting_vat''))\n then raise exception ''TAX_CORRECTION_LINE_INTEGRITY''; end if;\n if (c.status=''issued'')<>(d.id is not null) then raise exception ''TAX_CORRECTION_DOCUMENT_INTEGRITY''; end if;\n if d.id is not null and (d.issued_at<>c.issued_at or d.issued_by_user_id<>c.issued_by_user_id or d.issued_snapshot_json->>''document_no'' is distinct from d.document_no\n   or d.issued_snapshot_json->>''correction_id'' is distinct from c.id::text\n   or d.issued_snapshot_json #> ''{tax,payment}'' is distinct from c.source_snapshot_json #> ''{tax,payment}''\n   or d.issued_snapshot_json #> ''{tax,tax_point}'' is distinct from c.source_snapshot_json #> ''{tax,tax_point}''\n   or d.issued_snapshot_json #> ''{tax,seller}'' is distinct from c.source_snapshot_json #> ''{tax,seller}''\n   or d.issued_snapshot_json #> ''{receipt,payment}'' is distinct from c.source_snapshot_json #> ''{receipt,payment}'')\n then raise exception ''TAX_CORRECTION_DOCUMENT_INTEGRITY''; end if;\n if d.id is not null then\n   expected_tax:=c.draft_snapshot_json->''tax''; expected_receipt:=c.draft_snapshot_json->''receipt'';\n   if c.correction_mode=''cancel_and_reissue'' then\n     expected_tax:=jsonb_set(expected_tax,''{document}'',(expected_tax->''document'')||jsonb_build_object(''tax_invoice_no'',d.document_no,''issued_at'',d.issued_at,''correction_id'',cid));\n     if c.original_combined_document_id is not null then expected_receipt:=jsonb_set(expected_receipt,''{receipt}'',(expected_receipt->''receipt'')||jsonb_build_object(''receipt_no'',d.document_no,''issued_at'',d.issued_at,''correction_id'',cid)); end if;\n   end if;\n   if d.issued_snapshot_json->''tax'' is distinct from expected_tax or d.issued_snapshot_json->''receipt'' is distinct from expected_receipt\n     or d.issued_snapshot_json->''lines'' is distinct from c.draft_snapshot_json->''lines''\n     or d.issued_snapshot_json->''totals'' is distinct from c.draft_snapshot_json->''totals''\n     or d.issued_snapshot_json->>''approval_evidence'' is distinct from c.approval_evidence\n   then raise exception ''TAX_CORRECTION_DOCUMENT_INTEGRITY''; end if;\n end if;\n if d.id is not null and c.correction_mode=''cancel_and_reissue'' and\n   (d.issued_snapshot_json #>> ''{tax,document,tax_invoice_no}'' is distinct from d.document_no\n     or (c.original_combined_document_id is not null and d.issued_snapshot_json #>> ''{receipt,receipt,receipt_no}'' is distinct from d.document_no))\n then raise exception ''TAX_CORRECTION_PAIR_INVALID''; end if;\n return new;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","name":"void_finance_receipt","owner":"postgres","config":["search_path=public"],"signature":"void_finance_receipt(uuid,text,boolean)","definition":"CREATE OR REPLACE FUNCTION public.void_finance_receipt(p_receipt_id uuid, p_reason text, p_acknowledged boolean)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare v_payment_id uuid; v_receipt public.finance_receipts%rowtype;\nbegin\n  if not public.current_user_can_void_finance_receipts() then raise exception ''RECEIPT_PERMISSION_DENIED''; end if;\n  if p_acknowledged is distinct from true then raise exception ''RECEIPT_VOID_ACK_REQUIRED''; end if;\n  if nullif(btrim(p_reason),'''') is null or length(p_reason) > 2000 then raise exception ''RECEIPT_REASON_REQUIRED''; end if;\n  select payment_id into v_payment_id from public.finance_receipts where id = p_receipt_id;\n  if not found then raise exception ''RECEIPT_NOT_FOUND''; end if;\n  perform 1 from public.finance_payments where id = v_payment_id for update;\n  select * into v_receipt from public.finance_receipts where id = p_receipt_id for update;\n  if v_receipt.combined_document_id is not null then raise exception ''DOCUMENT_USE_COMBINED_WORKFLOW''; end if;\n  if v_receipt.status = ''voided'' then return p_receipt_id; end if;\n  if v_receipt.status <> ''issued'' then raise exception ''RECEIPT_ISSUED_REQUIRED''; end if;\n  update public.finance_receipts set status = ''voided'',voided_at = now(),voided_by_user_id = auth.uid(),\n    void_reason = btrim(p_reason),updated_at = now() where id = p_receipt_id;\n  perform public.record_finance_receipt_audit(p_receipt_id,''voided'',jsonb_build_object(\n    ''reason'',btrim(p_reason),''receipt_no'',v_receipt.receipt_no,''payment_changed'',false,''cash_created'',false));\n  return p_receipt_id;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":true},{"acl":"{postgres=X/postgres}","name":"vp_direct_frozen_source","owner":"postgres","config":["search_path=public"],"signature":"vp_direct_frozen_source(jsonb)","definition":"CREATE OR REPLACE FUNCTION public.vp_direct_frozen_source(s jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare l jsonb; lines jsonb:=''[]''; blockers jsonb:=''[]''; economics jsonb; canonical jsonb; input_lines jsonb;\nbegin\n if s->>''source_type'' is distinct from ''direct_money_receipt'' or s->''schema_version'' is distinct from ''1''::jsonb\n  or jsonb_typeof(s->''lines'') is distinct from ''array'' or nullif(s->>''source_id'','''') is null\n then raise exception ''VP_DISTRIBUTION_SOURCE_UNPROVEN''; end if;\n perform (s->>''source_id'')::uuid;\n if s->>''status'' is distinct from ''confirmed'' then blockers:=blockers||jsonb_build_array(''direct_not_confirmed''); end if;\n select coalesce(jsonb_agg(x-array[''cash'',''wht'',''vat'',''gross'']),''[]'') into input_lines from jsonb_array_elements(s->''lines'') x;\n canonical:=public.direct_money_lines(input_lines);\n if canonical is distinct from s->''lines'' then raise exception ''VP_DISTRIBUTION_SOURCE_UNPROVEN''; end if;\n for l in select value from jsonb_array_elements(canonical) loop\n  economics:=jsonb_build_object(''professional_pool'',0,''company_economic'',0,''company_cash'',0);\n  if l->>''money_nature''<>''business_revenue'' then blockers:=blockers||jsonb_build_array(''direct_''||(l->>''money_nature''));\n  elsif l#>>''{vat_treatment_json,treatment}''=''unknown'' then blockers:=blockers||jsonb_build_array(''direct_vat_unresolved'');\n  else economics:=public.vp_received_line_economics((l->>''base'')::numeric,(l->>''wht'')::numeric,l->>''classification''); end if;\n  lines:=lines||jsonb_build_array(l||economics);\n end loop;\n if (s->>''actual_cash'')::numeric is distinct from (select sum((x->>''cash'')::numeric) from jsonb_array_elements(lines) x)\n  or (s->>''wht_credit'')::numeric is distinct from (select sum((x->>''wht'')::numeric) from jsonb_array_elements(lines) x)\n  or (s->>''before_vat'')::numeric is distinct from (select sum((x->>''base'')::numeric) from jsonb_array_elements(lines) x)\n  or (s->>''vat'')::numeric is distinct from (select sum((x->>''vat'')::numeric) from jsonb_array_elements(lines) x)\n  or (s->>''gross_received'')::numeric is distinct from (s->>''actual_cash'')::numeric+(s->>''wht_credit'')::numeric\n then raise exception ''VP_DISTRIBUTION_SOURCE_UNPROVEN''; end if;\n return jsonb_build_object(''schema_version'',1,''policy_version'',''vp_distribution_v1'',''received_money_source'',s,\n  ''money_source'',null,''money_allocation'',null,''lines'',lines,''totals'',jsonb_build_object(''cash'',s->''actual_cash'',''wht'',s->''wht_credit'',''base'',s->''before_vat'',''vat'',s->''vat'',\n   ''professional_pool'',(select sum((x->>''professional_pool'')::numeric) from jsonb_array_elements(lines) x),\n   ''company_economic'',(select sum((x->>''company_economic'')::numeric) from jsonb_array_elements(lines) x),\n   ''company_cash'',(select sum((x->>''company_cash'')::numeric) from jsonb_array_elements(lines) x)),\n  ''blockers'',(select coalesce(jsonb_agg(distinct value order by value),''[]'') from jsonb_array_elements(blockers)));\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"vp_distribution_frozen_source","owner":"postgres","config":["search_path=public"],"signature":"vp_distribution_frozen_source(jsonb,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.vp_distribution_frozen_source(p_money_source jsonb, p_money_allocation jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare s jsonb:=p_money_source; a jsonb:=nullif(p_money_allocation,''null''::jsonb);\n l jsonb; economics jsonb; item jsonb; ready jsonb; commercial jsonb; invoice_header jsonb; classification text; k text;\n lines jsonb:=''[]''; blockers jsonb:=''[]''; valid boolean; amount numeric;\n cash numeric; wht numeric; vat numeric; base numeric; pool numeric; economic numeric; company_cash numeric;\n total_pool numeric:=0; total_economic numeric:=0; total_company_cash numeric:=0;\n line_cash numeric:=0; line_wht numeric:=0; line_vat numeric:=0; line_base numeric:=0;\nbegin\n if jsonb_typeof(s) is distinct from ''object'' then\n  return jsonb_build_object(''schema_version'',1,''policy_version'',''vp_distribution_v1'',\n   ''money_source'',s,''money_allocation'',a,''lines'',''[]''::jsonb,\n   ''totals'',jsonb_build_object(''cash'',null,''wht'',null,''vat'',null,''base'',null,\n     ''professional_pool'',null,''company_economic'',null,''company_cash'',null),\n   ''blockers'',jsonb_build_array(''money_source_unavailable''));\n end if;\n if jsonb_typeof(s->''blockers'')=''array'' then blockers:=s->''blockers'';\n else blockers:=jsonb_build_array(''money_source_invalid''); end if;\n begin\n  if s->''schema_version'' is distinct from ''1''::jsonb\n    or jsonb_typeof(s->''payment'') is distinct from ''object''\n    or jsonb_typeof(s#>''{payment,currency}'') is distinct from ''string''\n    or nullif(btrim(s#>>''{payment,currency}''),'''') is null\n    or jsonb_typeof(s#>''{payment,id}'') is distinct from ''string''\n    or nullif(s#>>''{payment,id}'','''') is null\n    or jsonb_typeof(s->''lines'') is distinct from ''array''\n    or jsonb_typeof(s->''invoices'') is distinct from ''array''\n  then raise exception ''INVALID''; end if;\n  perform (s#>>''{payment,id}'')::uuid;\n  for k in select unnest(array[''cash'',''wht'',''settlement'']) loop\n   if jsonb_typeof(s->''payment''->k) is distinct from ''number'' then raise exception ''INVALID''; end if;\n   amount:=(s->''payment''->>k)::numeric;\n   if amount<0 or amount<>round(amount,2) then raise exception ''INVALID''; end if;\n  end loop;\n  for k in select unnest(array[''proven_base'',''proven_vat'',''unallocated_settlement'']) loop\n   if jsonb_typeof(s->k) is distinct from ''number'' then raise exception ''INVALID''; end if;\n   amount:=(s->>k)::numeric;\n   if amount<0 or amount<>round(amount,2) then raise exception ''INVALID''; end if;\n  end loop;\n  cash:=(s#>>''{payment,cash}'')::numeric; wht:=(s#>>''{payment,wht}'')::numeric;\n  base:=(s->>''proven_base'')::numeric; vat:=(s->>''proven_vat'')::numeric;\n  if cash+wht is distinct from (s#>>''{payment,settlement}'')::numeric\n    or (s->>''unallocated_settlement'')::numeric<>0 then blockers:=blockers||jsonb_build_array(''settlement_evidence_invalid''); end if;\n exception when others then\n  blockers:=blockers||jsonb_build_array(''money_source_invalid'');\n  cash:=null; wht:=null; base:=null; vat:=null;\n end;\n if s#>>''{payment,status}'' is distinct from ''confirmed'' then blockers:=blockers||jsonb_build_array(''payment_not_confirmed''); end if;\n if a is not null then\n  if jsonb_typeof(a) is distinct from ''object''\n    or a->>''payment_id'' is distinct from s#>>''{payment,id}''\n    or coalesce(a->>''status'','''') not in (''draft'',''reviewed'',''finalized'')\n    or a->''source_snapshot_json'' is distinct from s\n  then blockers:=blockers||jsonb_build_array(''money_allocation_stale''); end if;\n  begin\n   if public.money_allocation_decisions(s,a->''decisions_json'',false) is distinct from a->''decisions_json''\n   then raise exception ''INVALID''; end if;\n   if exists(select 1 from jsonb_array_elements(a->''decisions_json'') x\n     where coalesce(x->>''category'','''') not in (''company_revenue'',''unallocated''))\n   then blockers:=blockers||jsonb_build_array(''money_allocation_conflict''); end if;\n  exception when others then blockers:=blockers||jsonb_build_array(''money_allocation_invalid''); end;\n end if;\n for l in select value from jsonb_array_elements(case when jsonb_typeof(s->''lines'')=''array'' then s->''lines'' else ''[]''::jsonb end) loop\n  item:=l->''source_item''; ready:=item#>''{source_snapshot_json,ready_snapshot}''; commercial:=ready->''commercial'';\n  classification:=ready#>>''{economic,classification}''; valid:=true;\n  pool:=0; economic:=0; company_cash:=0;\n  if classification is null or classification not in (''professional_fee'',''additional_service'',''reimbursable_expense'',''government_or_court_fee'')\n  then blockers:=blockers||jsonb_build_array(''classification_unsupported''); valid:=false; end if;\n  begin\n   if jsonb_typeof(l) is distinct from ''object'' or jsonb_typeof(item) is distinct from ''object''\n     or item->>''id'' is distinct from l->>''invoice_item_id''\n     or item->>''invoice_id'' is distinct from l->>''invoice_id''\n     or item->>''source_state'' is distinct from ''active''\n   then raise exception ''INVALID''; end if;\n   if nullif(l->>''invoice_item_id'','''') is null or nullif(l->>''invoice_id'','''') is null then raise exception ''INVALID''; end if;\n   perform (l->>''invoice_item_id'')::uuid; perform (l->>''invoice_id'')::uuid;\n   if (select count(*) from jsonb_array_elements(s->''invoices'') inv where inv->>''invoice_id''=l->>''invoice_id'')<>1\n   then raise exception ''INVALID''; end if;\n   select inv#>''{issued_snapshot,invoice}'' into invoice_header from jsonb_array_elements(s->''invoices'') inv\n    where inv->>''invoice_id''=l->>''invoice_id'';\n   if invoice_header->>''id'' is distinct from l->>''invoice_id''\n     or jsonb_typeof(invoice_header->''client_id'') is distinct from ''string''\n     or nullif(invoice_header->>''client_id'','''') is null\n     or ready#>>''{charge,client_id}'' is distinct from invoice_header->>''client_id''\n   then raise exception ''INVALID''; end if;\n   perform (invoice_header->>''client_id'')::uuid;\n   for k in select unnest(array[''cash'',''wht'',''vat'',''base'',''settlement'']) loop\n    if jsonb_typeof(l->k) is distinct from ''number'' then raise exception ''INVALID''; end if;\n    amount:=(l->>k)::numeric;\n    if amount<0 or amount<>round(amount,2) then raise exception ''INVALID''; end if;\n   end loop;\n   if (l->>''base'')::numeric<=0\n     or (l->>''base'')::numeric+(l->>''vat'')::numeric is distinct from (l->>''settlement'')::numeric\n     or (l->>''cash'')::numeric+(l->>''wht'')::numeric is distinct from (l->>''settlement'')::numeric\n   then raise exception ''INVALID''; end if;\n   line_cash:=line_cash+(l->>''cash'')::numeric; line_wht:=line_wht+(l->>''wht'')::numeric;\n   line_base:=line_base+(l->>''base'')::numeric; line_vat:=line_vat+(l->>''vat'')::numeric;\n   if (l->>''base'')::numeric-(l->>''wht'')::numeric<0 then\n    blockers:=blockers||jsonb_build_array(''base_less_than_wht''); valid:=false;\n   end if;\n   if jsonb_typeof(ready) is distinct from ''object'' or ready->''schema_version'' is distinct from ''1''::jsonb\n     or item#>''{source_snapshot_json,schema_version}'' is distinct from ''2''::jsonb\n     or jsonb_typeof(item->''source_billable_charge_id'') is distinct from ''string''\n     or nullif(item->>''source_billable_charge_id'','''') is null\n     or ready#>>''{charge,id}'' is distinct from item->>''source_billable_charge_id''\n     or item#>>''{source_snapshot_json,billable_charge_id}'' is distinct from item->>''source_billable_charge_id''\n     or ready#>>''{charge,status}'' is distinct from ''ready_to_invoice''\n     or jsonb_typeof(commercial) is distinct from ''object''\n     or jsonb_typeof(commercial->''currency'') is distinct from ''string''\n     or nullif(btrim(commercial->>''currency''),'''') is null\n     or commercial->>''currency'' is distinct from s#>>''{payment,currency}''\n   then raise exception ''INVALID''; end if;\n   perform (item->>''source_billable_charge_id'')::uuid;\n   for k in select unnest(array[''amount_before_vat'',''vat_amount'',''total_amount'']) loop\n    if jsonb_typeof(commercial->k) is distinct from ''number'' then raise exception ''INVALID''; end if;\n    amount:=(commercial->>k)::numeric;\n    if amount<0 or amount<>round(amount,2) then raise exception ''INVALID''; end if;\n   end loop;\n   for k in select unnest(array[''amount_before_vat'',''vat_amount'',''line_total'']) loop\n    if jsonb_typeof(item->k) is distinct from ''number'' then raise exception ''INVALID''; end if;\n   end loop;\n   if (commercial->>''amount_before_vat'')::numeric is distinct from (l->>''base'')::numeric\n     or (commercial->>''vat_amount'')::numeric is distinct from (l->>''vat'')::numeric\n     or (commercial->>''total_amount'')::numeric is distinct from (l->>''settlement'')::numeric\n     or (item->>''amount_before_vat'')::numeric is distinct from (l->>''base'')::numeric\n     or (item->>''vat_amount'')::numeric is distinct from (l->>''vat'')::numeric\n     or (item->>''line_total'')::numeric is distinct from (l->>''settlement'')::numeric\n   then raise exception ''INVALID''; end if;\n  exception when others then blockers:=blockers||jsonb_build_array(''frozen_economic_evidence_invalid''); valid:=false;\n  end;\n  if valid then\n   economics:=public.vp_received_line_economics((l->>''base'')::numeric,(l->>''wht'')::numeric,classification);\n   pool:=(economics->>''professional_pool'')::numeric; economic:=(economics->>''company_economic'')::numeric; company_cash:=(economics->>''company_cash'')::numeric;\n  end if;\n  total_pool:=total_pool+pool; total_economic:=total_economic+economic; total_company_cash:=total_company_cash+company_cash;\n  lines:=lines||jsonb_build_array(l||jsonb_build_object(''classification'',classification,''professional_pool'',pool,\n    ''company_economic'',economic,''company_cash'',company_cash));\n end loop;\n if jsonb_array_length(lines)=0 then blockers:=blockers||jsonb_build_array(''frozen_lines_missing''); end if;\n if (select count(distinct x->>''invoice_item_id'') from jsonb_array_elements(lines) x)<>jsonb_array_length(lines)\n then blockers:=blockers||jsonb_build_array(''frozen_lines_invalid''); end if;\n if line_cash is distinct from cash or line_wht is distinct from wht or line_base is distinct from base or line_vat is distinct from vat\n   or cash is distinct from total_company_cash+total_pool+vat\n then blockers:=blockers||jsonb_build_array(''cash_reconciliation_invalid''); end if;\n return jsonb_build_object(''schema_version'',1,''policy_version'',''vp_distribution_v1'',''money_source'',s,''money_allocation'',a,\n  ''lines'',lines,''totals'',jsonb_build_object(''cash'',cash,''wht'',wht,''vat'',vat,''base'',base,\n    ''professional_pool'',total_pool,''company_economic'',total_economic,''company_cash'',total_company_cash),\n  ''blockers'',(select coalesce(jsonb_agg(distinct value order by value),''[]'') from jsonb_array_elements(blockers)));\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"vp_distribution_source","owner":"postgres","config":["search_path=public"],"signature":"vp_distribution_source(uuid)","definition":"CREATE OR REPLACE FUNCTION public.vp_distribution_source(p_payment_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare s jsonb; result jsonb; a public.finance_payment_money_allocations%rowtype; p public.finance_payments%rowtype;\nbegin\n select * into p from public.finance_payments where id=p_payment_id;\n if p.id is null then raise exception ''VP_DISTRIBUTION_PAYMENT_MISSING''; end if;\n select * into a from public.finance_payment_money_allocations where payment_id=p_payment_id and status<>''superseded'';\n begin s:=public.money_allocation_source(p_payment_id);\n exception when others then s:=null; end;\n result:=public.vp_distribution_frozen_source(s,case when a.id is null then null else to_jsonb(a) end);\n -- Preserve 044''s full source; this additional client proof belongs only to 045.\n if s is not null and (p.client_id is null or jsonb_typeof(s->''invoices'') is distinct from ''array''\n   or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(s->''invoices'')=''array'' then s->''invoices'' else ''[]''::jsonb end) inv\n     where inv#>>''{issued_snapshot,invoice,client_id}'' is distinct from p.client_id::text)) then\n  result:=jsonb_set(result,''{blockers}'',(select jsonb_agg(distinct value order by value)\n    from jsonb_array_elements((result->''blockers'')||jsonb_build_array(''invoice_client_evidence_invalid''))));\n end if;\n return result;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"vp_received_line_economics","owner":"postgres","config":["search_path=public"],"signature":"vp_received_line_economics(numeric,numeric,text)","definition":"CREATE OR REPLACE FUNCTION public.vp_received_line_economics(p_base numeric, p_wht numeric, p_classification text)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\nbegin\n if p_base is null or p_wht is null or p_base<0 or p_wht<0 or p_base<p_wht or p_base<>round(p_base,2) or p_wht<>round(p_wht,2)\n  or p_classification is null or p_classification not in(''professional_fee'',''additional_service'',''reimbursable_expense'',''government_or_court_fee'')\n then raise exception ''VP_DISTRIBUTION_SOURCE_UNPROVEN''; end if;\n return jsonb_build_object(''professional_pool'',case when p_classification=''professional_fee'' then p_base-p_wht else 0 end,\n  ''company_economic'',case when p_classification=''professional_fee'' then 0 else p_base end,\n  ''company_cash'',case when p_classification=''professional_fee'' then 0 else p_base-p_wht end);\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":false,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"vp_received_lock","owner":"postgres","config":["search_path=public"],"signature":"vp_received_lock(uuid,uuid)","definition":"CREATE OR REPLACE FUNCTION public.vp_received_lock(p_payment_id uuid, p_direct_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n if (p_payment_id is null)=(p_direct_id is null) then raise exception ''VP_DISTRIBUTION_SOURCE_UNPROVEN''; end if;\n if p_payment_id is not null then perform public.money_allocation_lock(p_payment_id); return; end if;\n perform pg_advisory_xact_lock(hashtextextended(''direct_money:''||p_direct_id::text,0));\n perform 1 from public.finance_direct_money_receipts where id=p_direct_id for update;\n if not found then raise exception ''DIRECT_MONEY_MISSING''; end if;\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false},{"acl":"{postgres=X/postgres}","name":"vp_received_source","owner":"postgres","config":["search_path=public"],"signature":"vp_received_source(uuid,uuid)","definition":"CREATE OR REPLACE FUNCTION public.vp_received_source(p_payment_id uuid, p_direct_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare a public.finance_direct_money_receipts%rowtype; s jsonb;\nbegin\n if (p_payment_id is null)=(p_direct_id is null) then raise exception ''VP_DISTRIBUTION_SOURCE_UNPROVEN''; end if;\n if p_payment_id is not null then return public.vp_distribution_source(p_payment_id); end if;\n select * into a from public.finance_direct_money_receipts where id=p_direct_id;\n if a.id is null then raise exception ''DIRECT_MONEY_MISSING''; end if;\n s:=coalesce(a.confirmed_snapshot_json,public.direct_money_snapshot(a))||jsonb_build_object(''status'',a.status,''source_version'',a.version);\n if a.classification_json is not null then s:=s||jsonb_build_object(''lines'',a.classification_json->''lines'',''classification_evidence'',a.classification_json); end if;\n s:=s||jsonb_build_object(''source_fingerprint'',md5(s::text));\n return public.vp_direct_frozen_source(s);\nend;\n$function$\n","anon_execute":false,"service_execute":false,"security_definer":true,"authenticated_execute":false}]'::jsonb)),
