BEFORE DELETE OR UPDATE ON public.finance_tax_point_events FOR EACH ROW EXECUTE FUNCTION protect_finance_tax_invoice_history()"},{"name":"tax_invoice_integrity","enabled":"O","definition":"CREATE CONSTRAINT TRIGGER tax_invoice_integrity AFTER INSERT OR UPDATE ON public.finance_tax_point_events DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_finance_tax_invoice_integrity()"}],"force_rls":false,"anon_select":false,"constraints":[{"name":"finance_tax_point_events_approved_by_user_id_fkey","validated":true,"definition":"FOREIGN KEY (approved_by_user_id) REFERENCES user_profiles(id)"},{"name":"finance_tax_point_events_check","validated":true,"definition":"CHECK (((approved_at IS NULL) = (approved_by_user_id IS NULL)))"},{"name":"finance_tax_point_events_event_type_check","validated":true,"definition":"CHECK ((event_type = ''payment_received''::text))"},{"name":"finance_tax_point_events_evidence_json_check","validated":true,"definition":"CHECK ((jsonb_typeof(evidence_json) = ''object''::text))"},{"name":"finance_tax_point_events_pkey","validated":true,"definition":"PRIMARY KEY (id)"},{"name":"finance_tax_point_events_tax_invoice_id_fkey","validated":true,"definition":"FOREIGN KEY (tax_invoice_id) REFERENCES finance_tax_invoices(id) ON DELETE RESTRICT"},{"name":"finance_tax_point_events_tax_invoice_id_key","validated":true,"definition":"UNIQUE (tax_invoice_id)"},{"name":"tax_invoice_integrity","validated":true,"definition":"TRIGGER DEFERRABLE INITIALLY DEFERRED"}],"service_select":false,"authenticated_write":false}]'::jsonb)),
