 when coalesce(a.v->>'name',b.v->>'name') in ('issue_finance_receipt','refresh_finance_receipt_draft','cancel_finance_receipt_draft','void_finance_receipt','save_finance_tax_invoice_draft','refresh_finance_tax_invoice_draft','issue_finance_tax_invoice','cancel_finance_tax_invoice_draft','save_finance_combined_document_draft','refresh_finance_combined_document_draft','issue_finance_combined_document','cancel_finance_combined_document_draft','finance_tax_invoice_draft_snapshot','finance_tax_invoice_issue_blockers','validate_finance_receipt_integrity','validate_finance_tax_invoice_integrity','guard_receipt_logo_issue','guard_finance_receipt_lifecycle','validate_finance_combined_document','tax_correction_source','create_finance_tax_correction_draft','validate_tax_correction_document','tax_position_source','tax_filing_monthly_facts_before_expense') then (a.v-'definition') is distinct from (b.v-'definition')
 else a.v is distinct from b.v end),
