 where (select value is not null from baseline) and case when coalesce(a.v->>'name',b.v->>'name') in ('finance_receipts','finance_tax_invoices','finance_combined_documents','finance_receipt_invoice_allocations','finance_tax_invoice_items','finance_tax_invoice_source_coverages','finance_tax_point_events','finance_tax_document_corrections','finance_direct_money_receipts') then
