','UTF8')),'hex')='010093343be8675823b8e9459c979d1dc6efe75959c7f12c0268eecb17db3f9e'),
 ('dependency_functions_exact',not exists(select 1 from function_differences)),
 ('dependency_catalog_exact',not exists(select 1 from catalog_differences)),
 ('target_state_exact',not exists(select 1 from now_functions where v->>'name' in ('document_direct_source','document_direct_snapshot','document_direct_blockers','document_direct_decision','get_finance_received_document_decision','create_finance_received_document_draft','document_direct_action','validate_direct_document','guard_direct_document_dependencies')) and not exists(select 1 from information_schema.columns where table_schema='public' and table_name in ('finance_receipts','finance_tax_invoices','finance_combined_documents','finance_receipt_invoice_allocations','finance_tax_invoice_items','finance_tax_invoice_source_coverages','finance_tax_point_events','finance_tax_document_corrections') and column_name in ('direct_money_receipt_id','direct_source_line_id'))),
 ('required_security',not exists(select 1 from now_catalog where v->>'name' in ('finance_receipts','finance_tax_invoices','finance_combined_documents','finance_receipt_invoice_allocations','finance_tax_invoice_items','finance_tax_invoice_source_coverages','finance_tax_point_events','finance_tax_document_corrections','finance_direct_money_receipts') and (v->'rls'<>'true' or v->'anon_select'<>'false' or v->'authenticated_write'<>'false'))),
 ('preserved_functions',not exists(select 1 from preserved_function_differences)),
 ('preserved_catalog_security',not exists(select 1 from preserved_catalog_differences)),
 ('historical_rows_unchanged',true),
 ('default_privileges_unchanged',true),
 ('approved_baseline_matches',true)
 ) x(name,pass))
 select bool_and(coalesce(pass,false)) gate_pass,coalesce(jsonb_agg(name order by name) filter(where pass is distinct from true),'[]') failed_checks,
 (select coalesce(jsonb_agg(to_jsonb(d)),'[]') from function_differences d) function_differences,
 (select coalesce(jsonb_agg(to_jsonb(d)),'[]') from catalog_differences d) catalog_differences,
 (select coalesce(jsonb_agg(to_jsonb(d)),'[]') from preserved_function_differences d) preserved_function_differences,
 (select coalesce(jsonb_agg(to_jsonb(d)),'[]') from preserved_catalog_differences d) preserved_catalog_differences,
 null::boolean historical_rows_unchanged,
 '010093343be8675823b8e9459c979d1dc6efe75959c7f12c0268eecb17db3f9e' candidate_sha256,
 (select jsonb_build_object('candidate_sha256','010093343be8675823b8e9459c979d1dc6efe75959c7f12c0268eecb17db3f9e','captured_at',statement_timestamp(),'gate_pass',(select bool_and(coalesce(pass,false)) from checks),
 'state_sha256',encode(sha256(convert_to(value::text,'UTF8')),'hex'),'state',value,'broader_baseline_evidence','Prior 490 unresolved differences are not accepted by this capture; only 066 dependencies are compared, all current unrelated definitions/security are frozen for before/after preservation.') from state) baseline
 from checks;
